// Fonction Supabase « paiement- » de Lookmiz.
// 1) Programmes de 30 jours : page de paiement Stripe (prog_checkout), vérification (prog_verify)
//    et livraison du contenu des jours, seulement si le paiement est confirmé (prog_day).
// 2) Anciennes cartes d'invitation (checkout / verify) : inchangé.
import { createClient } from 'npm:@supabase/supabase-js@2';

const CORS = { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': '*', 'Access-Control-Allow-Methods': 'POST, OPTIONS' };
const json = (d: unknown, status = 200) => new Response(JSON.stringify(d), { status, headers: { ...CORS, 'Content-Type': 'application/json' } });
const admin = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!);
const SK = Deno.env.get('STRIPE_SECRET_KEY') ?? '';
const SITE = 'https://lookmiz.com/';
// Prix côté serveur : le navigateur ne peut pas les modifier.
// Contenu des 4 programmes : jamais envoyé sans paiement confirmé.
const DAYS: Record<string, { kit: unknown; days: unknown[] }> = {"ecrans":{"kit":{"raisons":["Mieux dormir","Être plus présent avec les gens","Retrouver ma concentration","Avancer sur mes projets","Moins me comparer aux autres","Avoir plus de temps pour moi","Être moins stressé","Reprendre le sport","Relire des livres","Moins culpabiliser"],"pros":["M'occuper quand je m'ennuie","Rester en lien avec mes amis","Me détendre","Ne pas rater les infos","Me divertir","Ne pas penser à mes soucis"],"cons":["Je dors moins","Je perds des heures","Je me compare aux autres","J'ai du mal à me concentrer","Je suis plus irritable","Je remets mes projets à plus tard","Je suis moins présent avec les gens","Je me sens vidé après"],"calc":{"q":"Combien d'heures par jour passes-tu sur ton téléphone ?","unit":"h par jour","min":0,"max":12,"step":0.5,"def":4,"mult":365,"out":"heures par an","div":24,"divLabel":"jours entiers","eq":[6,"livres de 300 pages lus"],"gain":"récupérées chaque année"},"env":["Couper les notifications non essentielles","Sortir les applis des écrans d'accueil","Me déconnecter des réseaux sociaux","Passer l'écran en noir et blanc","Charger le téléphone hors de la chambre","Régler une limite de temps par appli"],"triggers":["Une notification","L'ennui","Une file d'attente","Dans mon lit","Une pause au travail","Pendant le repas","Quand je suis stressé","Quand je suis seul","Dans les transports","Avant de m'endormir"],"actions":["Respirer 1 minute","Boire un verre d'eau","Écrire une phrase dans mes notes","Poser le téléphone dans une autre pièce","Lire 2 pages","Faire quelques étirements","Appeler un ami","Marcher 5 minutes dehors","Regarder par la fenêtre","Ranger un objet"],"distract":["Nouveau message","12 notifications","Quelqu'un a aimé ta photo","Offre -50 % aujourd'hui","Tu as raté une story","Mise à jour disponible"],"myths":[["Si je coupe les notifications, je vais rater des choses importantes.",false,"Tes appels et messages de proches restent possibles. La plupart des notifications ne sont pas urgentes."],["Une envie de checker dure toute la journée.",false,"Elle monte, atteint un pic, puis retombe, souvent en quelques minutes."],["Il faut une volonté de fer pour réduire son temps d'écran.",false,"Ton environnement fait le travail : applis rangées, notifications coupées, téléphone loin du lit."],["Dormir avec le téléphone près du lit n'a aucun effet sur le sommeil.",false,"Il retarde souvent le coucher et fragilise le sommeil. Le charger hors de la chambre aide."],["Remplacer le scroll par une autre activité aide à tenir.",true,"Quand on enlève une habitude sans rien mettre à la place, le vide la rappelle."],["Si je dérape une soirée, tout est perdu.",false,"Un dérapage n'est pas une rechute : on reprend le fil le lendemain."]],"pairs":[["Notification","Couper les notifications"],["L'ennui","Lire 2 pages"],["Dans mon lit","Téléphone hors de la chambre"],["Stress","Respirer 1 minute"],["File d'attente","Regarder autour de moi"]],"pieges":[["Juste cinq minutes.",true,"Cinq minutes deviennent souvent trente. Si tu y vas, mets un minuteur avant."],["Je l'ai bien mérité.",true,"Tu peux te récompenser autrement, sans y perdre ta soirée."],["L'envie va passer si j'attends 10 minutes.",false,"Exact : une envie monte, atteint un pic puis retombe."],["J'ai besoin de savoir ce qui se passe.",true,"Presque rien n'est urgent. Les vraies urgences t'appellent."],["Je peux faire une pause d'écran maintenant.",false,"Oui. Une pause de 10 minutes est déjà une victoire."],["Je regarde juste un truc.",true,"« Juste un truc » est la porte d'entrée du scroll."],["Un dérapage n'est pas un échec.",false,"Exact. Ce qui compte, c'est de reprendre le fil."],["Je peux m'arrêter quand je veux.",true,"Alors prouve-le : arrête pendant 10 minutes, tout de suite."]],"scenarios":[{"q":"Il est 23h30, tu es dans ton lit. Tu prends ton téléphone « juste pour voir l'heure ».","c":[["J'ouvre une appli, juste deux minutes",0,"Deux minutes deviennent souvent une heure. L'idéal : le téléphone n'est pas dans la chambre."],["Je le repose et je respire 1 minute",2,"Bien joué : tu coupes l'automatisme et tu protèges ton sommeil."],["Je mets un minuteur de 5 minutes",1,"Mieux que rien, mais tu restes dans le piège."]]},{"q":"Tu t'ennuies dans la file d'attente du supermarché.","c":[["Je regarde autour de moi, sans écran",2,"Parfait. L'ennui est inconfortable un instant, puis il passe."],["Je regarde juste mes notifications",0,"C'est comme ça que le scroll recommence."],["J'écoute un podcast",1,"Ça occupe sans scroller : c'est correct."]]},{"q":"Tu as passé 2 heures sur ton téléphone sans t'en rendre compte. Tu te sens mal.","c":[["Je me dis que je suis nul et j'abandonne",0,"Le jugement dur fatigue et pousse à recommencer."],["Je note ce qui m'a déclenché et je reprends demain",2,"C'est ça, un dérapage utile : tu apprends et tu repars."],["Je supprime toutes mes applis d'un coup",1,"Radical, mais difficile à tenir. Mieux vaut avancer pas à pas."]]}],"relapse":{"heure":["Je pose le téléphone et je respire","Je bois un verre d'eau et je sors prendre l'air","Je note ce qui s'est passé"],"ajuster":["Je règle une limite de temps","Je range l'appli difficile","Je change mon heure de coucher"],"prevenir":["Un ami proche","Mon frère ou ma sœur","Mon conjoint ou ma conjointe","Un professionnel","Personne, je gère seul"]},"events":["Soirée seul","Week-end sans programme","Voyage","Stress au travail","Dimanche soir","Vacances"],"messages":["Je réduis mon temps d'écran. Peux-tu me demander demain comment ça s'est passé ?","J'essaie de lâcher mon téléphone le soir. Tu peux me le rappeler gentiment ?"],"rules":["Garder mes barrières en place","Utiliser le bouton SOS à chaque envie","Prévoir mes moments à risque","Parler à quelqu'un quand c'est dur","Bouger régulièrement","Bien dormir","Me récompenser autrement","Faire un point chaque mois","Pas de téléphone au lit","Notifications coupées"],"identite":["qui décide de son temps","qui tient ses engagements","qui prend soin de lui","qui sait demander de l'aide","qui ose dire non","qui se réveille avec de l'énergie","qui choisit ses soirées","qui protège son argent","qui est présent avec ses proches","qui avance sur ses projets","qui se respecte","qui ne se juge plus durement"],"rewards":["Un bon repas au restaurant","Une sortie au cinéma","Un week-end dans la nature","Un vêtement qui me plaît","Un moment avec un ami","Une journée sans rien faire","Un livre ou un jeu","Un hammam ou un massage","Un petit voyage","Un cadeau pour quelqu'un"],"evening":["Fixer l'heure du coucher","Téléphone hors du lit","Écrans éteints 30 minutes avant","Douche ou tisane","Préparer la journée de demain","Respirer 2 minutes"],"people":["Un ami proche","Mon frère ou ma sœur","Mon conjoint ou ma conjointe","Un parent","Un collègue de confiance","Mon médecin"],"pause":["Lève-toi et étire-toi","Bois un verre d'eau, lentement","Regarde loin, par la fenêtre","Respire lentement 5 fois","Note ce que tu ressens, en une phrase"]},"days":[["Ton pourquoi","Avant de changer quoi que ce soit, il faut savoir pour quoi tu le fais. Ce pourquoi sera ta réserve les jours difficiles : il doit venir de toi, pas de ce qu'on attend de toi.","Écris 3 raisons personnelles de reprendre la main sur ton téléphone (dormir, être présent, avancer sur un projet…). Garde-les en note sur ton écran de verrouillage.","choose",{},{"q":"Qu'est-ce qui te pousse à changer aujourd'hui ?","o":[["Ma santé","Excellent moteur. Le corps commence à récupérer très tôt : chaque jour compte déjà, même si tu ne le sens pas encore."],["Mon argent","Chiffrer l'argent regagné est l'un des meilleurs rappels les jours difficiles. On le fera dans quelques jours."],["Mes proches","Faire ça pour les autres aide, mais garde aussi une raison rien que pour toi : c'est elle qui tient quand personne ne regarde."],["Je me sens dépassé(e)","C'est une raison valable. Tu n'as pas à tout régler aujourd'hui : un seul petit pas suffit pour commencer."]]},["Récompenses imprévisibles","Notifications et flux infini marchent comme une machine à surprises : on ne sait jamais si le prochain contenu sera bon, et le cerveau en redemande.","Compte combien de fois tu ouvres une appli sans raison."]],["Mesurer sans te juger","Ton téléphone sait déjà combien de temps tu y passes. Regarder le chiffre sans te traiter de nul, c'est le vrai premier pas : on ne règle pas ce qu'on ne regarde pas.","Ouvre « Temps d'écran » (iPhone) ou « Bien-être numérique » (Android). Note ta moyenne des 7 derniers jours et tes 3 applis les plus utilisées.","calc",{},{"q":"Ton estimation de ta semaine dernière, elle est…","o":[["Plutôt juste","C'est rare : la plupart des gens sous-estiment. Vérifie quand même avec les vrais chiffres ce soir."],["Sûrement en dessous de la réalité","C'est le cas de presque tout le monde : le cerveau oublie les automatismes. Mesurer sans te juger, c'est tout ce qu'on te demande."],["Je n'ose pas regarder","Normal : voir le chiffre pique un peu. C'est pourtant ce qui permet de reprendre la main. Regarde-le comme un simple relevé."],["Je n'en ai aucune idée","Alors note pendant 3 jours, une ligne à chaque fois. Les automatismes se voient dès qu'on les écrit."]]},["Tes yeux clignent moins","Devant un écran, on cligne environ deux fois moins, d'où sécheresse et fatigue visuelle.","Cligne 10 fois, puis regarde au loin 20 secondes."]],["Ce que ça t'apporte, ce que ça te coûte","Le scroll te donne quelque chose : fuir l'ennui, ne pas être seul, se sentir à jour. Le reconnaître permet de trouver d'autres façons d'obtenir la même chose. Ce n'est pas un manque de volonté, c'est une habitude qui te rend service.","Fais deux colonnes : ce que le téléphone t'apporte / ce qu'il te coûte (temps, sommeil, humeur, concentration). Souligne ce qui pèse le plus.",null,{},{"q":"Qu'est-ce que ça t'apporte de regarder ton téléphone ?","o":[["Me détendre","La détente est réelle mais courte : elle soulage surtout le manque que l'habitude crée. Respiration lente, marche ou douche chaude donnent un calme plus durable."],["Ne plus penser à rien","C'est un vrai besoin : ton cerveau veut une pause. Une vraie pause (marche, étirements) repose mieux et ne laisse pas de culpabilité."],["Me sentir moins seul(e)","Besoin légitime. Un message ou un appel, même court, y répond mieux et plus longtemps."],["Du plaisir, tout simplement","Le plaisir compte. L'idée n'est pas de t'en priver mais de le retrouver ailleurs : dans quelques jours tu choisiras tes remplaçants."]]},["Le coût d'une interruption","Après une interruption, il faut souvent 15 à 20 minutes pour retrouver sa concentration. Chaque coup d'œil au téléphone a un prix.","Fais une tâche 25 minutes sans téléphone."]],["Tes déclencheurs","Un déclencheur, c'est ce qui te fait sortir le téléphone sans y penser : une notification, l'ennui, une file d'attente, le lit, un moment de stress. Quand tu les repères, tu les vois venir.","Aujourd'hui, à chaque fois que tu prends ton téléphone, note l'heure et ce que tu ressens juste avant. Vise 10 notes.","heat",{},{"q":"Quand l'envie est-elle la plus forte ?","o":[["Le soir, seul(e)","Fatigue et solitude : le soir, le cerveau freine moins bien. Prévois quelque chose de précis pour ces heures-là."],["Quand je m'ennuie","L'ennui est un déclencheur très fréquent. Il retombe en quelques minutes si on ne le fuit pas : prépare une action de 5 minutes."],["Quand je suis stressé(e)","Le stress donne envie d'un soulagement rapide. Un souffle plus long à l'expiration (4 s / 6 s) calme le corps en 2 minutes."],["Avec d'autres personnes","Le contexte social pèse beaucoup. Dire à une personne que tu changes suffit souvent à désamorcer."]]},["Le réflexe du pouce","Une grande partie des ouvertures sont des automatismes déclenchés par un contexte (file d'attente, canapé), pas par un besoin.","Note le lieu de tes 3 prochaines ouvertures."]],["Rendre le scroll moins facile","Ta volonté est limitée, ton environnement peut faire le travail à ta place. Chaque petit obstacle, comme un mot de passe à retaper ou une appli rangée loin, réduit les ouvertures automatiques.","Coupe toutes les notifications sauf appels et messages de proches. Sors les 3 applis les plus utilisées de ton écran d'accueil et déconnecte-toi.",null,{},{"q":"Quelle barrière poses-tu en premier ?","o":[["Supprimer l'accès","Chaque étape en plus fait baisser le passage à l'acte : un obstacle de 20 secondes laisse souvent l'envie retomber."],["Changer de lieu ou d'horaire","Les habitudes sont liées à des lieux et des heures. Change l'un des deux et l'automatisme perd son déclencheur."],["Prévenir quelqu'un","Dire ton objectif à voix haute le rend plus réel et te donne un témoin bienveillant."],["Aucune, c'est trop dur","Prends la plus petite, une seule. Une barrière imparfaite vaut mieux qu'un plan parfait jamais appliqué."]]},["Un clic de plus","Ajouter de la friction (se déconnecter, ranger l'appli) réduit nettement les ouvertures impulsives.","Déconnecte-toi d'une appli maintenant."]],["Le plan « si… alors… »","Un plan précis marche mieux qu'une bonne intention. Tu décides à l'avance quoi faire quand le déclencheur arrive, pour ne pas avoir à choisir sous l'impulsion.","Écris 3 phrases : « Si je suis dans mon lit / en file d'attente / en pause, alors je… » avec une action concrète (lire 2 pages, regarder dehors, boire un verre d'eau).","pairs",{},{"q":"Quel plan « si… alors… » te ressemble ?","o":[["Si l'envie vient, je bois de l'eau et j'attends 10 minutes","Un délai court plus un geste simple : c'est très efficace. Les plans précis marchent bien mieux que les bonnes intentions."],["Si je m'ennuie, je sors 5 minutes","Bouger change l'état du corps et coupe l'automatisme. Même monter un escalier compte."],["Si je suis stressé(e), je respire 1 minute","Inspire 4 secondes, souffle 6 : l'expiration longue ralentit le cœur et calme le système nerveux."],["Si je craque, j'appelle quelqu'un","Parler casse l'isolement et la honte, qui poussent à recommencer."]]},["L'expiration longue","Souffler plus longtemps qu'on inspire active le frein du système nerveux et fait baisser le rythme cardiaque.","Inspire 4 s, souffle 6 s, cinq fois."]],["Bilan de la semaine 1","Une semaine pour comprendre. Tu sais maintenant combien de temps tu y passes, ce que ça te donne et quand ça se déclenche. C'est suffisant pour attaquer la suite.","Relis tes notes. Complète : « Ce que j'ai appris sur moi cette semaine, c'est… ». Choisis un seul moment de la journée à protéger la semaine prochaine.",null,{},{"q":"Cette semaine, qu'est-ce qui t'a le plus surpris(e) ?","o":[["À quel point c'est automatique","Voir l'automatisme, c'est déjà la moitié du chemin : on ne peut changer que ce qu'on remarque."],["Les moments où l'envie arrive","Tu connais maintenant tes heures et tes lieux : tu peux les anticiper au lieu de les subir."],["Que ça passe quand j'attends","C'est l'info la plus utile : une envie qui passe n'est pas un ordre."],["Rien de spécial","Pas grave, c'est une semaine d'observation. Continue : les effets arrivent avec la pratique."]]},["Lumière bleue et sommeil","La lumière des écrans le soir retarde la mélatonine, l'hormone qui signale la nuit. S'endormir prend plus de temps.","Coupe les écrans 30 minutes avant de dormir."]],["Comprendre l'envie","L'envie de regarder ton téléphone monte, atteint un pic, puis retombe, même si tu ne fais rien. Savoir que ça passe change tout : une envie n'est pas un ordre.","Quand l'envie arrive, attends 2 minutes avant d'agir. Observe : où la sens-tu dans le corps ? Que devient-elle au bout de 2 minutes ?","wave",{},{"q":"Quand l'envie arrive, que fais-tu d'habitude ?","o":[["Je cède tout de suite","Normal : céder soulage vite, et c'est ce qui apprend au cerveau à recommencer. Aujourd'hui, repousse seulement de 10 minutes."],["Je lutte de toutes mes forces","Lutter épuise. Observe l'envie comme une vague : elle monte, plafonne, redescend. Laisse-la passer sans la combattre."],["Je me distrais","Très bien : 10 minutes de distraction suffisent souvent. Prépare-en deux à l'avance, à portée de main."],["Je ne sais pas","Aujourd'hui, note l'heure et ce que tu ressens quand elle vient. Un schéma va apparaître."]]},["Une envie dure peu","Une envie atteint un pic puis retombe en quelques minutes si on ne la nourrit pas.","Chronomètre ta prochaine envie."]],["La règle des 10 minutes","Quand une envie arrive, ne te dis pas « jamais », dis-toi « dans 10 minutes ». Souvent, l'envie est partie avant. Si elle est encore là, tu y vas en conscience, pas en automatique.","Utilise le bouton SOS du site (ou un minuteur de 10 minutes) à chaque envie aujourd'hui. Compte combien sont passées.","hold",{},{"q":"Peux-tu tenir 10 minutes avant de passer à l'acte ?","o":[["Oui, facilement","Alors fais-en une règle : la plupart des envies retombent avant 10 minutes."],["Oui, avec une distraction","Parfait. Prépare deux distractions : musique, verre d'eau, marche. Elles font la moitié du travail."],["Difficile","Commence par 2 minutes. Chaque envie traversée entraîne ton cerveau à tolérer l'inconfort."],["Impossible","Pas de souci : 1 minute compte déjà. Le bouton SOS te guide pendant 10 minutes, un souffle après l'autre."]]},["Le pouvoir du délai","Attendre 10 minutes laisse l'émotion redescendre et la partie réfléchie du cerveau (cortex préfrontal) reprendre la main.","Lance un minuteur de 10 minutes avant de céder."]],["Respirer pour retomber","Quand tu veux décrocher, le corps s'agite. Une respiration lente, avec un souffle plus long que l'inspiration, aide à calmer le système nerveux en quelques minutes.","Fais 2 minutes de respiration (inspire 4 secondes, souffle 6), deux fois dans la journée, dont une avant de prendre ton téléphone par réflexe.","breathe",{},{"q":"Quand tu es tendu(e), ton souffle est plutôt…","o":[["Court et haut","Respirer haut met le corps en alerte. Allonge l'expiration : c'est le levier le plus rapide pour te calmer."],["Je le retiens parfois","Retenir son souffle augmente la tension. Souffle doucement par la bouche, comme dans une paille."],["Je n'y ai jamais fait attention","Pose une main sur le ventre : si elle ne bouge pas, ta respiration est haute. Essaie de la faire gonfler."],["Plutôt calme","Bien. Garde ce réflexe pour les moments d'envie, c'est là qu'il compte le plus."]]},["Le nerf vague","Respirer lentement stimule le nerf vague, qui ralentit le cœur et apaise. Quelques minutes suffisent.","Deux minutes de respiration avant de prendre ton téléphone."]],["Quand tu t'ennuies","L'ennui est l'un des premiers déclencheurs. Il est inconfortable parce qu'on ne le laisse jamais durer. T'y habituer, c'est retrouver des idées et de l'attention.","Choisis un moment d'ennui (transport, attente, repas) et laisse ton téléphone dans la poche. Note ce qui te passe par la tête.","slot",{},{"q":"Pour t'occuper 10 minutes, tu préfères…","o":[["Bouger","Le mouvement réduit les envies et améliore l'humeur en quelques minutes."],["Parler à quelqu'un","Une voix humaine apaise plus vite qu'un écran ou un produit."],["Faire quelque chose de mes mains","Cuisine, dessin, rangement : occuper les mains occupe aussi l'attention, l'envie perd de la place."],["Rien ne me tente","Normal au début : l'envie rend tout fade. Essaie quand même 3 minutes, l'envie baisse avant que l'activité ne devienne agréable."]]},["L'ennui est utile","Quand l'attention n'est pas stimulée, le cerveau passe en « mode par défaut », lié à la créativité et à la mémoire.","Reste 3 minutes sans rien faire, juste à observer."]],["Stress et fatigue","On scrolle davantage quand on est stressé ou fatigué : le cerveau cherche une pause facile. Si tu t'accordes de vraies pauses à ces moments, le téléphone devient moins nécessaire.","Prévois 3 pauses de 5 minutes sans écran aujourd'hui : étirements, fenêtre ouverte, verre d'eau, marche.",null,{},{"q":"Quand tu es stressé(e), ton corps réagit surtout par…","o":[["De la tension (épaules, mâchoire)","Relâche : épaules vers le bas, mâchoire détendue, trois souffles lents."],["De la fatigue","La fatigue baisse le frein de la volonté. Une sieste de 15 à 20 minutes aide, sinon couche-toi plus tôt ce soir."],["De l'agitation","Marche rapide 5 minutes : elle dépense l'adrénaline en trop."],["Je ne sais pas","Scanne : tête, épaules, ventre, jambes. Où ça serre ? C'est là qu'il faut respirer."]]},["Le cortisol","Le stress élève le cortisol et pousse vers un soulagement rapide. Marcher 10 minutes aide à le faire redescendre.","Marche 10 minutes sans téléphone."]],["Réseaux sociaux et comparaison","Les réseaux montrent le meilleur de la vie des autres, et s'y comparer fatigue. Tu peux garder ce qui t'apporte quelque chose et couper le reste.","Mets en sourdine ou désabonne-toi de 10 comptes qui te donnent un mauvais sentiment. Garde ceux qui t'apprennent ou te font rire.","myths",{},{"q":"Quelle idée te retient le plus ?","o":[["J'en ai besoin pour me détendre ou dormir","Ça détend sur l'instant mais entretient le manque ensuite. À terme, la détente et le sommeil naturels reviennent."],["Je gère, ce n'est pas un problème","Si tu es ici, c'est que tu veux plus de contrôle. Fais confiance à ça."],["Tout le monde le fait","Beaucoup le font, et beaucoup changent aussi. Tu n'es pas seul(e) dans les deux cas."],["Juste une fois ne compte pas","Chaque fois renforce le circuit de l'habitude. L'exception est souvent la porte d'entrée."]]},["La comparaison sociale","Voir des vies filtrées active la comparaison, associée à une humeur plus basse chez beaucoup de gros utilisateurs.","Désabonne-toi de 3 comptes qui te font te sentir mal."]],["Bilan de la semaine 2","Tu as appris à voir l'envie venir et à la laisser passer. Même quelques envies surmontées comptent : ce sont elles qui construisent la nouvelle habitude.","Regarde ton compteur d'envies surmontées. Note le moment le plus dur de la semaine et ce qui t'a aidé.",null,{},{"q":"Ce qui t'a le plus aidé(e) cette semaine ?","o":[["Attendre 10 minutes","Garde-le : c'est ton outil principal. Il marche d'autant mieux qu'il est automatique."],["Respirer","La respiration est toujours avec toi. Utilise-la avant que l'envie ne soit à son maximum."],["Éloigner ce qui donne accès","Bien joué : réduire l'accès est l'une des méthodes les plus solides."],["Rien de précis","Pas grave. Regarde le bilan : tu as peut-être tenu plus que tu ne le penses."]]},["L'attention se reconstruit","L'attention se muscle : des plages sans interruption la réentraînent peu à peu.","Lis 20 minutes sans téléphone."]],["Remplacer, pas seulement enlever","Si tu enlèves une habitude sans rien mettre à la place, le vide la rappelle. Choisis des activités simples, accessibles, qui occupent les mains ou la tête.","Liste 5 activités de 10 minutes faisables n'importe où (livre, dessin, appel à un ami, podcast, étirements). Garde la liste en fond d'écran.",null,{},{"q":"Quel remplaçant te semble le plus réaliste ?","o":[["Un geste (eau, étirements)","Les petits gestes sont faciles à répéter. Garde-les à portée de main."],["Une activité courte (marche, jeu)","Dix minutes suffisent souvent. Choisis-en une que tu peux faire n'importe où."],["Une personne (appel, message)","Un lien humain est l'un des meilleurs remplaçants. Mets 2 prénoms dans tes favoris."],["Je n'en ai pas encore","Essaie les trois cette semaine. Tu verras vite lequel marche pour toi."]]},["Les endorphines du mouvement","L'activité physique libère des substances de l'humeur (endorphines, dopamine) sans effet « pot sans fond ».","Cinq minutes de mouvement quand l'envie arrive."]],["Bouger","Le mouvement change l'humeur et l'énergie, et occupe le temps où tu aurais scrollé. Pas besoin de sport intense : marcher compte.","Marche 20 minutes aujourd'hui, sans écran. Un podcast est autorisé.","move",{},{"q":"Ton niveau de mouvement dans une journée ?","o":[["Presque aucun","Commence par 5 minutes de marche : c'est déjà un effet mesurable sur l'humeur."],["Un peu","Ajoute 10 minutes à l'heure où l'envie est la plus forte."],["Régulier","Excellent. Place-le aux heures à risque : c'est là qu'il protège le plus."],["Beaucoup","Parfait. N'oublie pas le repos : il fait partie de la récupération."]]},["Marcher aide le cerveau","Marcher 10 à 15 minutes améliore souvent l'humeur et l'attention, et réduit l'envie sur le moment.","Une marche, sans écouteurs."]],["Soirées et week-ends","Les moments sans cadre sont les plus risqués. Un planning léger, même flou, évite de glisser dans le scroll par défaut.","Planifie ce week-end 2 activités concrètes hors écran, avec un horaire.",null,{},{"q":"Le plus dur dans tes week-ends, c'est…","o":[["Le temps libre","Prévois deux activités par jour : le vide appelle l'habitude."],["Les amis","Propose un lieu ou une activité sans l'habitude, ou dis-le d'avance. Les vrais amis comprennent."],["Le soir tard","Fixe une heure limite de coucher : la fatigue baisse les défenses."],["Rien de particulier","Prévois quand même un plan B, au cas où."]]},["Le soir, la volonté baisse","En fin de journée, fatigue et décisions accumulées réduisent l'autocontrôle : on cède plus facilement.","Mets ton téléphone en charge hors de la chambre."]],["En parler à quelqu'un","Dire à un proche ce que tu fais t'engage et te soutient. Tu n'as pas à te justifier : une phrase simple suffit.","Dis à une personne de confiance que tu réduis ton temps d'écran. Propose-lui de te demander des nouvelles ce soir.",null,{},{"q":"À qui pourrais-tu en parler ?","o":[["Un(e) ami(e)","Un ami de confiance suffit. Dis simplement : « j'essaie de changer, peux-tu me demander demain comment ça va ? »"],["Un proche de la famille","Choisis la personne la plus calme et la moins critique. Un message écrit peut être plus facile."],["Un professionnel ou une ligne d'aide","Excellente idée : ton médecin est là pour ça, gratuitement et sans jugement."],["Personne pour l'instant","C'est possible, et ce n'est pas grave. Une ligne d'aide (ton médecin) peut être ton premier interlocuteur."]]},["Le contact apaise","Parler à quelqu'un de confiance fait baisser la réaction au stress, souvent plus qu'un écran.","Appelle quelqu'un au lieu de scroller."]],["Les pensées-pièges","« Juste cinq minutes », « je l'ai bien mérité », « je regarde juste un truc ». Ces phrases sont normales. Les repérer leur enlève du pouvoir.","Écris 3 phrases que tu te dis souvent avant de scroller. À côté de chacune, une réponse honnête et courte.","pieges",{},{"q":"Quelle pensée te fait le plus craquer ?","o":[["« Juste une fois »","C'est le piège le plus courant. Réponse : « si c'est juste une fois, je peux attendre demain »."],["« Je l'ai bien mérité »","Oui, et tu peux te récompenser autrement : repas, film, sortie. Sans la facture."],["« Je m'y mets demain »","Demain sera pareil. Réponse : « je commence par les 10 prochaines minutes »."],["« J'ai déjà craqué, tant pis »","Un faux pas n'efface pas les jours passés. Reprends dès la prochaine heure."]]},["Le cerveau négocie","Pour obtenir un soulagement rapide, le cerveau fabrique des excuses (« juste 5 minutes »). Les repérer leur enlève du pouvoir.","Note ta pensée-piège préférée."]],["Te récompenser autrement","Ton cerveau aime les petites récompenses. Tu peux en garder sans passer par l'écran : un café, un moment dehors, une série à plusieurs.","Choisis une récompense pour chaque jour tenu cette semaine. Note-la maintenant.",null,{},{"q":"Quelle récompense te ferait vraiment plaisir ?","o":[["Un bon repas","Parfait : choisis le jour et le lieu à l'avance, une récompense prévue motive mieux qu'une récompense improvisée."],["Une sortie","Planifie-la dans ton agenda dès aujourd'hui : l'avoir devant soi aide à tenir."],["Un achat","Mets de côté la somme économisée dans une enveloppe : la voir grossir motive."],["Du repos","Le repos est une vraie récompense. Offre-toi une soirée sans obligation."]]},["La récompense prévue","Une récompense choisie à l'avance renforce un nouveau comportement mieux qu'une récompense improvisée.","Choisis ta récompense de la semaine."]],["Bilan de la semaine 3","Trois semaines de pratique. Regarde les chiffres, pas ton impression : on se juge toujours plus sévèrement qu'on ne le mérite.","Compare ton temps d'écran moyen de la semaine à celui du jour 2. Écris l'écart, quel qu'il soit.",null,{},{"q":"Ce qui a changé depuis le début ?","o":[["Mon sommeil","Un meilleur sommeil réduit l'impulsivité : c'est un cercle vertueux qui s'installe."],["Mon humeur","Chaque jour, le cerveau se rééquilibre un peu. L'humeur suit souvent avec un décalage."],["Mon argent","Note la somme : c'est un des gains les plus concrets."],["Pas encore grand-chose","Normal : les changements sont souvent lents au début. Continue, ils arrivent avec la régularité."]]},["Le sommeil répare","Moins d'écran le soir améliore souvent la qualité du sommeil, et un sommeil réparateur réduit l'impulsivité.","Note l'heure à laquelle tu te réveilles demain."]],["Un dérapage n'est pas une rechute","Tu vas peut-être craquer une soirée. Ce n'est pas un échec, c'est une information. Ce qui compte, c'est de reprendre le fil le lendemain, sans te punir.","Écris la phrase que tu te diras après un gros dérapage. Courte, bienveillante, qui te remet en route.","scenario",{},{"q":"Si tu craques ce soir, tu te diras…","o":[["« Je suis nul(le) »","La honte nourrit le cycle. Parle-toi comme à un ami : « ça arrive, je reprends »."],["« C'est une information »","Exactement. Note ce qui l'a déclenché et ajuste ton plan."],["« Autant tout lâcher »","C'est l'effet « tant pis », le vrai piège. Reprends au prochain repas, pas à la prochaine semaine."],["« Je préviens quelqu'un »","Excellent réflexe : ça casse l'isolement et la honte."]]},["Un faux pas, pas une chute","Un dérapage ne défait pas les circuits déjà en place : ce qui compte, c'est la régularité dans la durée.","Écris ta phrase de reprise."]],["Ton plan en cas de rechute","Prévoir le plan B enlève la peur. Qu'est-ce qui m'a fait craquer ? Qu'est-ce que je change ? Qui je préviens ?","Rédige un plan en 3 points : ce que je fais dans l'heure, ce que j'analyse, ce que j'ajuste.","relapse",{},{"q":"En cas de rechute, ce qui t'aiderait le plus ?","o":[["Un message tout prêt","Écris-le maintenant, il sera là quand tu en auras besoin. Tu n'auras plus qu'à l'envoyer."],["Quelqu'un à appeler","Choisis la personne et enregistre son numéro en favori."],["Une règle simple","Par exemple : « je m'arrête là, je bois de l'eau, je reprends demain »."],["Je préfère ne pas y penser","C'est compréhensible, mais prévoir réduit la peur. Ça prend 2 minutes et tu seras plus serein(e)."]]},["Anticiper apaise","Prévoir ce qu'on fera en cas de craquage réduit la panique et l'effet « tant pis ».","Relis ton plan B ce soir."]],["Qui tu deviens","Tu ne fais pas que supprimer un comportement : tu deviens quelqu'un qui décide de son attention. Cette image aide à tenir sur la durée.","Complète 3 fois : « Je suis quelqu'un qui… » à propos de ton rapport au téléphone.",null,{},{"q":"Dans 6 mois, tu aimerais être quelqu'un qui…","o":[["Dort bien","Un objectif concret : les nuits s'améliorent souvent dès les premières semaines."],["Tient ses engagements","Chaque petit engagement tenu renforce la confiance en toi."],["A de l'énergie","L'énergie revient avec le sommeil, le mouvement et moins d'à-coups."],["Se sent libre","La liberté, c'est choisir. Chaque envie traversée est un choix de plus."]]},["L'habitude met du temps","Un comportement répété dans le même contexte devient automatique après plusieurs semaines (de 2 à 8 selon les études).","Répète ta nouvelle habitude à la même heure."]],["Les moments à risque à venir","Vacances, périodes de stress, soirées seul : certains moments vont remettre le scroll en jeu. Les prévoir, c'est déjà y être préparé.","Liste les 3 prochains moments à risque des 4 semaines à venir et ce que tu feras à chaque fois.",null,{},{"q":"Ton prochain moment à risque, c'est…","o":[["Un week-end","Prévois deux activités par jour et une heure de coucher."],["Une fête ou un événement","Décide à l'avance ce que tu fais et à quelle heure tu pars."],["Une période de stress","Planifie des pauses et du mouvement. Le stress est un déclencheur majeur."],["Je ne sais pas","Regarde ton agenda des 2 semaines à venir : tu en verras un ou deux."]]},["Le contexte déclenche","Un lieu ou une heure associés à l'habitude suffisent à déclencher l'envie. Les repérer permet de s'y préparer.","Note ton prochain moment à risque."]],["Mieux dormir","Le téléphone au lit est l'un des plus gros voleurs de sommeil. Mieux dormir rend aussi les envies plus faciles à gérer.","Ce soir, charge ton téléphone hors de ta chambre, ou loin du lit, et utilise un réveil classique si besoin.","evening",{},{"q":"Tes nuits en ce moment ?","o":[["Courtes","Une nuit courte renforce l'envie et réduit le contrôle. Couche-toi 30 minutes plus tôt ce soir."],["Agitées","Écrans coupés 30 minutes avant, chambre fraîche (18-19 °C) et dîner léger aident."],["Correctes","Bien. Garde un horaire régulier : c'est ça qui consolide."],["Très bonnes","Parfait. Protège-les : c'est un de tes meilleurs alliés."]]},["Sommeil et envies","Une nuit courte augmente l'appétit pour le plaisir immédiat et diminue le contrôle des impulsions.","Couche-toi 30 minutes plus tôt."]],["Le temps que tu récupères","Ce temps est ton vrai gain. Le chiffrer le rend concret et motive.","Calcule : (temps d'écran du jour 2 moins temps actuel) × 30 jours. Écris ce que tu peux faire avec ces heures.",null,{},{"q":"Le temps ou l'argent récupéré, tu en feras…","o":[["Du repos","Le repos compte aussi. Planifie-le au lieu de le subir."],["Un projet","Choisis un petit projet de 30 minutes par jour : c'est ce qui remplit le vide."],["Du temps avec des proches","Les liens sont l'un des meilleurs soutiens pour tenir."],["Un plaisir ou de l'épargne","Mets une somme de côté chaque semaine : la voir grossir motive."]]},["Une heure par jour, c'est 15 jours","Une heure d'écran en moins chaque jour représente environ 15 jours entiers récupérés sur une année.","Choisis à quoi tu consacres 30 minutes récupérées."]],["Ton réseau de soutien","Si ton usage affecte ton sommeil, ton travail ou ton humeur au point que tu n'y arrives pas seul, en parler à un professionnel est une bonne idée. Ce n'est pas un échec.","Repère un interlocuteur : ton médecin généraliste, ou un psychologue. Si tu vas mal, le 3114 répond 24h/24.",null,{},{"q":"Qui est ton premier appel en cas de coup dur ?","o":[["Un(e) ami(e)","Garde son numéro en favori. Dis-lui d'avance qu'il peut t'aider."],["Un proche de la famille","Préviens-le à l'avance : il saura quoi répondre quand ça arrivera."],["Un professionnel","ton médecin est joignable. Note le numéro dans ton téléphone."],["Je n'ai pas de nom","Alors ton médecin peut être ce nom. C'est gratuit, tu n'as pas à te justifier."]]},["Le lien protège","Des liens sociaux de qualité sont associés à une meilleure santé et à de meilleures chances de tenir un changement.","Propose un moment à quelqu'un cette semaine."]],["Lettre à toi-même","Ce que tu as fait pendant 30 jours mérite d'être écrit. Cette lettre te servira les jours où tu auras oublié pourquoi c'était important.","Écris-toi une lettre pour dans 3 mois : ce que tu as appris, ce que tu veux avoir gardé, ce que tu te souhaites.","letter",{},{"q":"Pour toi dans 3 mois, le plus important à te rappeler ?","o":[["Ce que j'ai tenu","Écris-le : les chiffres sont des preuves quand le doute revient."],["Pourquoi j'ai commencé","Relis ton pourquoi du premier jour. Il est dans ton espace."],["Que ça passe","Oui : une envie passe toujours. C'est ta meilleure information."],["Que je mérite d'aller bien","C'est vrai. Écris-le comme si tu parlais à un ami."]]},["Écrire aide","Écrire ce qu'on ressent aide à réguler les émotions : c'est ce qu'on appelle l'écriture expressive.","Écris 5 minutes, sans te relire."]],["Et maintenant ?","30 jours, c'est un début, pas une fin. Garde 2 ou 3 règles qui ont marché, relâche le reste, et refais le point une fois par mois.","Choisis les 3 règles à garder. Plante un rappel mensuel dans ton agenda : « Point écrans ».","final",{},{"q":"Pour la suite, tu comptes…","o":[["Continuer chaque jour","Excellent. La régularité fait plus que l'intensité."],["Faire un point par semaine","Très bien : un point de 10 minutes le dimanche suffit."],["Appeler en cas de doute","ton médecin est là. Un coup de fil évite souvent une rechute."],["Je ne sais pas encore","Pas de pression. Garde juste la règle : au moindre doute, 10 minutes d'attente et un souffle lent."]]},["Garder le cap","Les rechutes sont fréquentes dans tout changement de comportement ; ce qui compte, c'est de reprendre vite.","Fixe un rappel mensuel pour faire le point."]]]},"pornographie":{"kit":{"raisons":["Plus d'énergie","Mieux me concentrer","Être plus présent dans mon couple","Me sentir fier de moi","Retrouver du temps","Mieux dormir","Moins de culpabilité","Des relations plus vraies","Avoir confiance en moi","Reprendre le contrôle"],"pros":["Calmer le stress","Combler l'ennui","Me sentir moins seul","Avoir du plaisir rapidement","M'endormir","Me détendre"],"cons":["De la culpabilité","Du temps perdu","Moins de sommeil","Des attentes irréalistes","Moins d'énergie","De la distance avec les autres","Plus de difficultés à me concentrer","De la honte"],"calc":{"q":"Combien d'heures par semaine y passes-tu ?","unit":"h par semaine","min":0,"max":20,"step":0.5,"def":3,"mult":52,"out":"heures par an","div":24,"divLabel":"jours entiers","eq":[2,"sorties au cinéma"],"gain":"récupérées chaque année"},"env":["Installer un filtre ou bloqueur de contenus adultes","Désactiver la navigation privée","Supprimer les comptes et favoris","Téléphone hors du lit","Laisser la porte de ma chambre ouverte","Prévoir un programme pour mes soirées seul"],"triggers":["Seul à la maison","Le soir tard","L'ennui","Le stress","La fatigue","Après une dispute","Après un verre","Dans mon lit","Quand je me sens seul","Quand je me sens nul"],"actions":["Changer de pièce","Prendre une douche","Faire quelques pompes","Appeler quelqu'un","Sortir marcher","Respirer 1 minute","Écouter de la musique","Boire un verre d'eau","Ranger un objet","Écrire ce que je ressens"],"distract":["Lien suggéré","Nouvelle vidéo pour toi","Onglet resté ouvert","Publicité adulte","Notification d'un site","Message d'un inconnu"],"myths":[["Cette habitude se règle avec de la honte et de la culpabilité.",false,"La honte pousse souvent à recommencer : on se sent mal, on cherche du soulagement."],["Une envie dure jusqu'à ce qu'on y cède.",false,"Elle monte, atteint un pic puis retombe, même si tu ne fais rien."],["Rendre l'accès plus difficile aide vraiment.",true,"Moins d'accès facile, c'est moins de décisions à prendre sous l'impulsion."],["Un dérapage prouve que je n'y arriverai jamais.",false,"C'est une information, pas une fin. Tu reprends le fil."],["Le soir, seul et fatigué, est le moment le plus risqué.",true,"Fatigue, solitude et téléphone à la main : prévois un plan pour ces moments."],["Ce que je vois à l'écran reflète la vraie intimité.",false,"C'est une mise en scène. Les vraies relations ont d'autres rythmes et d'autres envies."]],"pairs":[["Seul le soir","Appeler quelqu'un"],["L'ennui","Sortir marcher"],["Le stress","Respirer 1 minute"],["Dans mon lit","Téléphone hors du lit"],["Une envie forte","Changer de pièce"]],"pieges":[["Juste une fois.",true,"« Juste une fois » est la phrase qui relance le cycle."],["Personne ne le saura.",true,"Toi, tu le sauras. Et la culpabilité reviendra."],["L'envie va passer si je change de pièce.",false,"Oui. Changer de lieu coupe souvent l'automatisme."],["Je l'ai bien mérité.",true,"Tu peux te récompenser autrement : un bon repas, un film, un moment avec des amis."],["Je peux en parler à quelqu'un de confiance.",false,"Oui. Garder ça pour soi entretient la honte."],["Ça me détend, il n'y a pas de mal.",true,"Ça détend sur le moment, mais ça laisse souvent de la culpabilité."],["Un dérapage n'est pas un échec.",false,"Exact. Tu reprends le fil sans te punir."],["Je gère, je n'ai besoin de rien changer.",true,"Si tu es ici, c'est que tu veux changer. Fais confiance à ça."]],"scenarios":[{"q":"Il est minuit, tu es seul, fatigué, le téléphone à la main. L'envie monte.","c":[["Je laisse le téléphone dans la chambre et je vais dans une autre pièce",2,"Parfait : tu changes de lieu et tu coupes l'accès."],["Je me dis que c'est la dernière fois",0,"« La dernière fois » revient presque toujours. Mieux vaut agir maintenant."],["Je regarde juste mes messages",1,"Pas idéal : le téléphone au lit reste le déclencheur."]]},{"q":"Tu as une dispute avec ton partenaire et tu te sens nul.","c":[["Je sors marcher 10 minutes",2,"Bien : tu laisses redescendre l'émotion sans passer par l'habitude."],["J'ouvre un onglet pour me détendre",0,"Tu apaises sur le moment, mais la culpabilité arrive ensuite."],["Je mets de la musique",1,"Ça aide un peu. Ajoute un changement de pièce."]]},{"q":"Tu as craqué hier soir. Ce matin, tu te sens honteux.","c":[["Je me dis que je ne m'en sortirai jamais",0,"La honte fatigue et pousse à recommencer."],["Je note ce qui a déclenché l'envie et je reprends aujourd'hui",2,"C'est exactement ça : une information, pas une fin."],["Je fais comme si rien ne s'était passé",1,"Mieux vaut regarder ce qui s'est passé pour mieux t'en protéger."]]}],"relapse":{"heure":["Je ferme tout et je change de pièce","Je prends une douche et je respire","Je note ce qui s'est passé"],"ajuster":["Je renforce mon filtre","Je change mes soirées seul","Je parle à quelqu'un"],"prevenir":["Un ami proche","Mon frère ou ma sœur","Mon conjoint ou ma conjointe","Un professionnel","Personne, je gère seul"]},"events":["Soirée seul","Voyage ou hôtel","Période de stress","Après une dispute","Week-end seul","Nuit sans sommeil"],"messages":["J'essaie de changer une habitude. Peux-tu me demander de mes nouvelles cette semaine ?","Je traverse une période difficile. Tu pourrais m'appeler ce soir ?"],"rules":["Garder mes barrières en place","Utiliser le bouton SOS à chaque envie","Prévoir mes moments à risque","Parler à quelqu'un quand c'est dur","Bouger régulièrement","Bien dormir","Me récompenser autrement","Faire un point chaque mois","Garder mon filtre actif","Pas de téléphone dans le lit"],"identite":["qui décide de son temps","qui tient ses engagements","qui prend soin de lui","qui sait demander de l'aide","qui ose dire non","qui se réveille avec de l'énergie","qui choisit ses soirées","qui protège son argent","qui est présent avec ses proches","qui avance sur ses projets","qui se respecte","qui ne se juge plus durement"],"rewards":["Un bon repas au restaurant","Une sortie au cinéma","Un week-end dans la nature","Un vêtement qui me plaît","Un moment avec un ami","Une journée sans rien faire","Un livre ou un jeu","Un hammam ou un massage","Un petit voyage","Un cadeau pour quelqu'un"],"evening":["Fixer l'heure du coucher","Téléphone hors du lit","Écrans éteints 30 minutes avant","Douche ou tisane","Préparer la journée de demain","Respirer 2 minutes"],"people":["Un ami proche","Mon frère ou ma sœur","Mon conjoint ou ma conjointe","Un parent","Un collègue de confiance","Mon médecin"],"pause":["Lève-toi et étire-toi","Bois un verre d'eau, lentement","Regarde loin, par la fenêtre","Respire lentement 5 fois","Note ce que tu ressens, en une phrase"]},"days":[["Ton pourquoi","Pas pour la honte, pour toi. Les raisons qui tiennent dans le temps sont positives : plus d'énergie, de concentration, de présence, des relations plus vraies. Ce pourquoi sera ta réserve les jours difficiles.","Écris 3 raisons personnelles de vouloir changer. Évite « parce que c'est mal » : cherche ce que tu veux gagner.","choose",{},{"q":"Qu'est-ce qui te pousse à changer aujourd'hui ?","o":[["Ma santé","Excellent moteur. Le corps commence à récupérer très tôt : chaque jour compte déjà, même si tu ne le sens pas encore."],["Mon argent","Chiffrer l'argent regagné est l'un des meilleurs rappels les jours difficiles. On le fera dans quelques jours."],["Mes proches","Faire ça pour les autres aide, mais garde aussi une raison rien que pour toi : c'est elle qui tient quand personne ne regarde."],["Je me sens dépassé(e)","C'est une raison valable. Tu n'as pas à tout régler aujourd'hui : un seul petit pas suffit pour commencer."]]},["Le circuit de la récompense","Le plaisir sexuel libère de la dopamine. Avec une nouveauté infinie à portée de clic, le cerveau peut s'habituer à chercher toujours plus de stimulation.","Note ce que tu cherchais vraiment : détente, ennui, solitude ?"]],["Regarder honnêtement","On ne règle pas ce qu'on ne regarde pas. Mesurer ton habitude sans te juger, c'est te donner un point de départ réel.","Pendant 7 jours, note chaque fois : heure, lieu, durée, ce que tu ressentais avant. Aujourd'hui, reprends les 7 derniers jours de mémoire.","calc",{},{"q":"Ton estimation de ta semaine dernière, elle est…","o":[["Plutôt juste","C'est rare : la plupart des gens sous-estiment. Vérifie quand même avec les vrais chiffres ce soir."],["Sûrement en dessous de la réalité","C'est le cas de presque tout le monde : le cerveau oublie les automatismes. Mesurer sans te juger, c'est tout ce qu'on te demande."],["Je n'ose pas regarder","Normal : voir le chiffre pique un peu. C'est pourtant ce qui permet de reprendre la main. Regarde-le comme un simple relevé."],["Je n'en ai aucune idée","Alors note pendant 3 jours, une ligne à chaque fois. Les automatismes se voient dès qu'on les écrit."]]},["La nouveauté relance","Le cerveau réagit fortement à la nouveauté : le défilement de contenus la renouvelle sans fin et allonge les sessions.","Note la durée de ta dernière session."]],["Ce que ça t'apporte, ce que ça te coûte","Cette habitude te rend service : elle calme le stress, comble l'ennui ou la solitude. Le reconnaître permet de chercher d'autres façons d'obtenir la même chose. Elle a aussi un coût : temps, sommeil, culpabilité, attentes irréalistes.","Fais deux colonnes : ce que ça t'apporte / ce que ça te coûte. Souligne ce qui pèse le plus.",null,{},{"q":"Qu'est-ce que ça t'apporte de regarder du porno ?","o":[["Me détendre","La détente est réelle mais courte : elle soulage surtout le manque que l'habitude crée. Respiration lente, marche ou douche chaude donnent un calme plus durable."],["Ne plus penser à rien","C'est un vrai besoin : ton cerveau veut une pause. Une vraie pause (marche, étirements) repose mieux et ne laisse pas de culpabilité."],["Me sentir moins seul(e)","Besoin légitime. Un message ou un appel, même court, y répond mieux et plus longtemps."],["Du plaisir, tout simplement","Le plaisir compte. L'idée n'est pas de t'en priver mais de le retrouver ailleurs : dans quelques jours tu choisiras tes remplaçants."]]},["Un soulagement bref","Beaucoup l'utilisent pour calmer le stress. Le soulagement est réel mais bref, et laisse souvent de la culpabilité.","Note comment tu te sens 10 minutes après."]],["Tes déclencheurs","Heure, lieu, émotion, appareil : ce sont les signaux qui déclenchent l'envie. Ennui, stress, solitude, fatigue et alcool reviennent souvent. Quand tu les repères, tu les vois venir.","Relis tes notes du jour 2. Repère les 3 déclencheurs les plus fréquents.","heat",{},{"q":"Quand l'envie est-elle la plus forte ?","o":[["Le soir, seul(e)","Fatigue et solitude : le soir, le cerveau freine moins bien. Prévois quelque chose de précis pour ces heures-là."],["Quand je m'ennuie","L'ennui est un déclencheur très fréquent. Il retombe en quelques minutes si on ne le fuit pas : prépare une action de 5 minutes."],["Quand je suis stressé(e)","Le stress donne envie d'un soulagement rapide. Un souffle plus long à l'expiration (4 s / 6 s) calme le corps en 2 minutes."],["Avec d'autres personnes","Le contexte social pèse beaucoup. Dire à une personne que tu changes suffit souvent à désamorcer."]]},["Heure et lieu","Les habitudes sont liées à un contexte (seul, tard, au lit). Changer le contexte coupe l'automatisme.","Pas de téléphone dans le lit ce soir."]],["Rendre l'accès plus difficile","La volonté s'épuise, l'environnement peut faire le travail. Moins d'accès facile, c'est moins de décisions à prendre sous l'envie.","Installe un filtre ou un bloqueur de contenus adultes sur tes appareils. Désactive la navigation privée. Mets ton téléphone hors du lit ce soir.",null,{},{"q":"Quelle barrière poses-tu en premier ?","o":[["Supprimer l'accès","Chaque étape en plus fait baisser le passage à l'acte : un obstacle de 20 secondes laisse souvent l'envie retomber."],["Changer de lieu ou d'horaire","Les habitudes sont liées à des lieux et des heures. Change l'un des deux et l'automatisme perd son déclencheur."],["Prévenir quelqu'un","Dire ton objectif à voix haute le rend plus réel et te donne un témoin bienveillant."],["Aucune, c'est trop dur","Prends la plus petite, une seule. Une barrière imparfaite vaut mieux qu'un plan parfait jamais appliqué."]]},["Moins d'accès, moins d'envie","Le soir, la volonté est limitée. Rendre l'accès plus difficile (filtre, pas d'écran dans la chambre) réduit les décisions impulsives.","Installe un filtre de contenu."]],["Le plan « si… alors… »","Un plan précis marche mieux qu'une bonne intention. Tu décides à l'avance de ce que tu feras quand le déclencheur arrive.","Écris 3 phrases : « Si je suis seul le soir / ennuyé / stressé, alors je… » avec une action concrète (sortir, appeler quelqu'un, douche, marcher).","pairs",{},{"q":"Quel plan « si… alors… » te ressemble ?","o":[["Si l'envie vient, je bois de l'eau et j'attends 10 minutes","Un délai court plus un geste simple : c'est très efficace. Les plans précis marchent bien mieux que les bonnes intentions."],["Si je m'ennuie, je sors 5 minutes","Bouger change l'état du corps et coupe l'automatisme. Même monter un escalier compte."],["Si je suis stressé(e), je respire 1 minute","Inspire 4 secondes, souffle 6 : l'expiration longue ralentit le cœur et calme le système nerveux."],["Si je craque, j'appelle quelqu'un","Parler casse l'isolement et la honte, qui poussent à recommencer."]]},["L'expiration longue","Souffler plus longtemps qu'on inspire active le frein du système nerveux et calme l'excitation.","Inspire 4 s, souffle 6 s, cinq fois."]],["Bilan de la semaine 1","Une semaine pour comprendre. Tu connais ton habitude, tes déclencheurs et tu as mis quelques barrières. C'est déjà beaucoup.","Complète : « Ce que j'ai appris sur moi cette semaine, c'est… ». Choisis un seul moment de la journée à protéger la semaine prochaine.",null,{},{"q":"Cette semaine, qu'est-ce qui t'a le plus surpris(e) ?","o":[["À quel point c'est automatique","Voir l'automatisme, c'est déjà la moitié du chemin : on ne peut changer que ce qu'on remarque."],["Les moments où l'envie arrive","Tu connais maintenant tes heures et tes lieux : tu peux les anticiper au lieu de les subir."],["Que ça passe quand j'attends","C'est l'info la plus utile : une envie qui passe n'est pas un ordre."],["Rien de spécial","Pas grave, c'est une semaine d'observation. Continue : les effets arrivent avec la pratique."]]},["Écrans tard, nuit courte","Les écrans tard retardent le sommeil, et un sommeil court amplifie les envies le lendemain.","Écran coupé 30 minutes avant de dormir."]],["Comprendre l'envie","L'envie monte, atteint un pic, puis retombe, même si tu ne fais rien. Savoir que ça passe change tout : une envie n'est pas un ordre.","Quand l'envie arrive, attends 2 minutes avant d'agir. Où la sens-tu dans le corps ? Que devient-elle au bout de 2 minutes ?","wave",{},{"q":"Quand l'envie arrive, que fais-tu d'habitude ?","o":[["Je cède tout de suite","Normal : céder soulage vite, et c'est ce qui apprend au cerveau à recommencer. Aujourd'hui, repousse seulement de 10 minutes."],["Je lutte de toutes mes forces","Lutter épuise. Observe l'envie comme une vague : elle monte, plafonne, redescend. Laisse-la passer sans la combattre."],["Je me distrais","Très bien : 10 minutes de distraction suffisent souvent. Prépare-en deux à l'avance, à portée de main."],["Je ne sais pas","Aujourd'hui, note l'heure et ce que tu ressens quand elle vient. Un schéma va apparaître."]]},["Une vague, pas un ordre","L'excitation et l'envie montent puis redescendent en quelques minutes si on ne les nourrit pas.","Chronomètre ta prochaine envie."]],["La règle des 10 minutes","Ne te dis pas « jamais », dis-toi « dans 10 minutes, et dans une autre pièce ». Changer de lieu et d'activité coupe souvent l'automatisme.","Utilise le bouton SOS du site à chaque envie aujourd'hui. Compte combien sont passées.","hold",{},{"q":"Peux-tu tenir 10 minutes avant de passer à l'acte ?","o":[["Oui, facilement","Alors fais-en une règle : la plupart des envies retombent avant 10 minutes."],["Oui, avec une distraction","Parfait. Prépare deux distractions : musique, verre d'eau, marche. Elles font la moitié du travail."],["Difficile","Commence par 2 minutes. Chaque envie traversée entraîne ton cerveau à tolérer l'inconfort."],["Impossible","Pas de souci : 1 minute compte déjà. Le bouton SOS te guide pendant 10 minutes, un souffle après l'autre."]]},["Le délai","Attendre 10 minutes laisse redescendre l'émotion et redonne la main à la partie réfléchie du cerveau.","Lance un minuteur de 10 minutes."]],["Respirer pour retomber","Une respiration lente, avec un souffle plus long que l'inspiration, aide à calmer le corps en quelques minutes.","Fais 2 minutes de respiration (inspire 4 secondes, souffle 6), deux fois dans la journée, dont une avant d'aller te coucher.","breathe",{},{"q":"Quand tu es tendu(e), ton souffle est plutôt…","o":[["Court et haut","Respirer haut met le corps en alerte. Allonge l'expiration : c'est le levier le plus rapide pour te calmer."],["Je le retiens parfois","Retenir son souffle augmente la tension. Souffle doucement par la bouche, comme dans une paille."],["Je n'y ai jamais fait attention","Pose une main sur le ventre : si elle ne bouge pas, ta respiration est haute. Essaie de la faire gonfler."],["Plutôt calme","Bien. Garde ce réflexe pour les moments d'envie, c'est là qu'il compte le plus."]]},["Le nerf vague","Respirer lentement stimule le nerf vague, qui ralentit le cœur et apaise le corps.","Deux minutes de respiration, deux fois aujourd'hui."]],["Ennui et solitude","L'ennui et la solitude sont des déclencheurs fréquents. Ce que tu cherches vraiment, c'est souvent du contact, de la détente ou un peu de plaisir.","Aujourd'hui, ajoute un contact humain réel : message, appel, café avec quelqu'un.","slot",{},{"q":"Pour t'occuper 10 minutes, tu préfères…","o":[["Bouger","Le mouvement réduit les envies et améliore l'humeur en quelques minutes."],["Parler à quelqu'un","Une voix humaine apaise plus vite qu'un écran ou un produit."],["Faire quelque chose de mes mains","Cuisine, dessin, rangement : occuper les mains occupe aussi l'attention, l'envie perd de la place."],["Rien ne me tente","Normal au début : l'envie rend tout fade. Essaie quand même 3 minutes, l'envie baisse avant que l'activité ne devienne agréable."]]},["La solitude fait mal","Le sentiment de solitude active des zones proches de la douleur physique. Un contact humain, même bref, l'apaise.","Envoie un message à quelqu'un."]],["Stress, fatigue et nuit","La fatigue fragilise : tard le soir, seul, le téléphone à la main, c'est le moment le plus risqué. Une routine de soirée t'aide.","Fixe une heure de coucher. 30 minutes avant, téléphone hors de la chambre. Prévois une activité calme pour te détendre.",null,{},{"q":"Quand tu es stressé(e), ton corps réagit surtout par…","o":[["De la tension (épaules, mâchoire)","Relâche : épaules vers le bas, mâchoire détendue, trois souffles lents."],["De la fatigue","La fatigue baisse le frein de la volonté. Une sieste de 15 à 20 minutes aide, sinon couche-toi plus tôt ce soir."],["De l'agitation","Marche rapide 5 minutes : elle dépense l'adrénaline en trop."],["Je ne sais pas","Scanne : tête, épaules, ventre, jambes. Où ça serre ? C'est là qu'il faut respirer."]]},["Stress et cortisol","Le stress augmente le cortisol et donne envie d'un soulagement rapide. Marcher 10 minutes le fait redescendre.","Marche 10 minutes dehors."]],["Honte et culpabilité","La honte pousse souvent à recommencer : on se sent mal, on cherche du soulagement, on retombe. Se parler avec respect, comme à un ami, casse ce cycle.","Écris à toi-même ce que tu dirais à un ami dans la même situation. Relis-le à voix haute.","myths",{},{"q":"Quelle idée te retient le plus ?","o":[["J'en ai besoin pour me détendre ou dormir","Ça détend sur l'instant mais entretient le manque ensuite. À terme, la détente et le sommeil naturels reviennent."],["Je gère, ce n'est pas un problème","Si tu es ici, c'est que tu veux plus de contrôle. Fais confiance à ça."],["Tout le monde le fait","Beaucoup le font, et beaucoup changent aussi. Tu n'es pas seul(e) dans les deux cas."],["Juste une fois ne compte pas","Chaque fois renforce le circuit de l'habitude. L'exception est souvent la porte d'entrée."]]},["La honte nourrit le cycle","La honte augmente le stress, qui augmente l'envie : un cercle. La bienveillance envers soi le casse.","Parle-toi comme à un ami."]],["Bilan de la semaine 2","Tu as appris à voir l'envie venir et à la laisser passer. Chaque envie surmontée construit la nouvelle habitude.","Regarde ton compteur d'envies surmontées. Note le moment le plus dur de la semaine et ce qui t'a aidé.",null,{},{"q":"Ce qui t'a le plus aidé(e) cette semaine ?","o":[["Attendre 10 minutes","Garde-le : c'est ton outil principal. Il marche d'autant mieux qu'il est automatique."],["Respirer","La respiration est toujours avec toi. Utilise-la avant que l'envie ne soit à son maximum."],["Éloigner ce qui donne accès","Bien joué : réduire l'accès est l'une des méthodes les plus solides."],["Rien de précis","Pas grave. Regarde le bilan : tu as peut-être tenu plus que tu ne le penses."]]},["L'énergie revient","Dormir assez et bouger rétablissent l'humeur et l'énergie, et réduisent les envies.","Couche-toi à heure fixe ce soir."]],["Remplacer, pas seulement enlever","Si tu enlèves une habitude sans rien mettre à la place, le vide la rappelle. Cherche des activités qui te détendent ou te font du bien autrement.","Liste 5 activités de 10 à 20 minutes qui te détendent (douche, musique, lecture, sport, cuisine). Garde la liste accessible.",null,{},{"q":"Quel remplaçant te semble le plus réaliste ?","o":[["Un geste (eau, étirements)","Les petits gestes sont faciles à répéter. Garde-les à portée de main."],["Une activité courte (marche, jeu)","Dix minutes suffisent souvent. Choisis-en une que tu peux faire n'importe où."],["Une personne (appel, message)","Un lien humain est l'un des meilleurs remplaçants. Mets 2 prénoms dans tes favoris."],["Je n'en ai pas encore","Essaie les trois cette semaine. Tu verras vite lequel marche pour toi."]]},["Changer d'état","Douche, musique, mouvement : ces gestes changent l'état du corps et coupent l'envie sur le moment.","Prends une douche fraîche ou tiède en cas d'envie."]],["Bouger","Le mouvement change l'humeur et dépense l'énergie. Pas besoin de sport intense : marcher compte.","Fais 20 minutes d'activité physique aujourd'hui, de préférence à l'heure où l'envie vient le plus.","move",{},{"q":"Ton niveau de mouvement dans une journée ?","o":[["Presque aucun","Commence par 5 minutes de marche : c'est déjà un effet mesurable sur l'humeur."],["Un peu","Ajoute 10 minutes à l'heure où l'envie est la plus forte."],["Régulier","Excellent. Place-le aux heures à risque : c'est là qu'il protège le plus."],["Beaucoup","Parfait. N'oublie pas le repos : il fait partie de la récupération."]]},["Le sport calme","L'exercice réduit l'anxiété et améliore le sommeil, deux moteurs de l'envie.","20 minutes de marche rapide."]],["Soirées et week-ends","Les moments seul et sans programme sont les plus risqués. Un planning léger évite de glisser par défaut.","Planifie les 2 prochaines soirées seul : un horaire, une activité, un moment de coucher.",null,{},{"q":"Le plus dur dans tes week-ends, c'est…","o":[["Le temps libre","Prévois deux activités par jour : le vide appelle l'habitude."],["Les amis","Propose un lieu ou une activité sans l'habitude, ou dis-le d'avance. Les vrais amis comprennent."],["Le soir tard","Fixe une heure limite de coucher : la fatigue baisse les défenses."],["Rien de particulier","Prévois quand même un plan B, au cas où."]]},["Seul, fatigué, téléphone en main","Cette combinaison est la plus à risque : fatigue, solitude et accès facile. Il suffit d'en retirer un pour baisser le risque.","Laisse le téléphone hors de la chambre."]],["En parler à quelqu'un","Garder ça pour soi entretient la honte. Parler à un ami de confiance, à un médecin ou à un thérapeute allège. Tu n'as pas à tout dire : une phrase suffit.","Choisis une personne de confiance et dis-lui que tu essaies de changer cette habitude. Ou prends rendez-vous avec un professionnel.",null,{},{"q":"À qui pourrais-tu en parler ?","o":[["Un(e) ami(e)","Un ami de confiance suffit. Dis simplement : « j'essaie de changer, peux-tu me demander demain comment ça va ? »"],["Un proche de la famille","Choisis la personne la plus calme et la moins critique. Un message écrit peut être plus facile."],["Un professionnel ou une ligne d'aide","Excellente idée : ton médecin ou un psychologue est là pour ça, gratuitement et sans jugement."],["Personne pour l'instant","C'est possible, et ce n'est pas grave. Une ligne d'aide (ton médecin ou un psychologue) peut être ton premier interlocuteur."]]},["Le lien réduit la honte","Le soutien social réduit la honte, un moteur de l'habitude.","Parle à une personne de confiance."]],["Les pensées-pièges","« Juste une fois », « personne ne le saura », « je l'ai bien mérité ». Ces phrases sont normales. Les repérer leur enlève du pouvoir.","Écris 3 phrases que tu te dis avant de craquer. À côté de chacune, une réponse honnête et courte.","pieges",{},{"q":"Quelle pensée te fait le plus craquer ?","o":[["« Juste une fois »","C'est le piège le plus courant. Réponse : « si c'est juste une fois, je peux attendre demain »."],["« Je l'ai bien mérité »","Oui, et tu peux te récompenser autrement : repas, film, sortie. Sans la facture."],["« Je m'y mets demain »","Demain sera pareil. Réponse : « je commence par les 10 prochaines minutes »."],["« J'ai déjà craqué, tant pis »","Un faux pas n'efface pas les jours passés. Reprends dès la prochaine heure."]]},["Le cerveau négocie","Pour obtenir un soulagement rapide, le cerveau fabrique des excuses. Les repérer leur enlève du pouvoir.","Note ta pensée-piège préférée."]],["Te récompenser autrement","Ton cerveau aime les petites récompenses. Tu peux en garder sans passer par là : un bon repas, un film, un moment avec des amis.","Choisis une récompense pour chaque jour tenu cette semaine. Note-la maintenant.",null,{},{"q":"Quelle récompense te ferait vraiment plaisir ?","o":[["Un bon repas","Parfait : choisis le jour et le lieu à l'avance, une récompense prévue motive mieux qu'une récompense improvisée."],["Une sortie","Planifie-la dans ton agenda dès aujourd'hui : l'avoir devant soi aide à tenir."],["Un achat","Mets de côté la somme économisée dans une enveloppe : la voir grossir motive."],["Du repos","Le repos est une vraie récompense. Offre-toi une soirée sans obligation."]]},["La récompense prévue","Une récompense choisie à l'avance renforce un nouveau comportement mieux qu'une récompense improvisée.","Choisis ta récompense de la semaine."]],["Bilan de la semaine 3","Trois semaines de pratique. Regarde ce qui a changé : l'envie, le sommeil, l'humeur, le temps libre.","Écris 3 changements que tu constates, même petits.",null,{},{"q":"Ce qui a changé depuis le début ?","o":[["Mon sommeil","Un meilleur sommeil réduit l'impulsivité : c'est un cercle vertueux qui s'installe."],["Mon humeur","Chaque jour, le cerveau se rééquilibre un peu. L'humeur suit souvent avec un décalage."],["Mon argent","Note la somme : c'est un des gains les plus concrets."],["Pas encore grand-chose","Normal : les changements sont souvent lents au début. Continue, ils arrivent avec la régularité."]]},["La concentration revient","Beaucoup de personnes notent peu à peu une meilleure concentration et plus d'énergie quand elles réduisent l'habitude.","Note ton niveau de concentration de 1 à 10."]],["Un dérapage n'est pas une rechute","Tu vas peut-être craquer. Ce n'est pas un échec, c'est une information. Ce qui compte, c'est de reprendre le fil, sans te punir.","Écris la phrase que tu te diras après un dérapage. Courte, bienveillante, qui te remet en route.","scenario",{},{"q":"Si tu craques ce soir, tu te diras…","o":[["« Je suis nul(le) »","La honte nourrit le cycle. Parle-toi comme à un ami : « ça arrive, je reprends »."],["« C'est une information »","Exactement. Note ce qui l'a déclenché et ajuste ton plan."],["« Autant tout lâcher »","C'est l'effet « tant pis », le vrai piège. Reprends au prochain repas, pas à la prochaine semaine."],["« Je préviens quelqu'un »","Excellent réflexe : ça casse l'isolement et la honte."]]},["Un faux pas, pas une chute","Un dérapage ne défait pas les circuits déjà en place. Reprendre vite compte plus que la perfection.","Écris ta phrase de reprise."]],["Ton plan en cas de rechute","Prévoir le plan B enlève la peur. Qu'est-ce qui m'a fait craquer ? Qu'est-ce que je change ? Qui je préviens ?","Rédige un plan en 3 points : ce que je fais dans l'heure, ce que j'analyse, ce que j'ajuste.","relapse",{},{"q":"En cas de rechute, ce qui t'aiderait le plus ?","o":[["Un message tout prêt","Écris-le maintenant, il sera là quand tu en auras besoin. Tu n'auras plus qu'à l'envoyer."],["Quelqu'un à appeler","Choisis la personne et enregistre son numéro en favori."],["Une règle simple","Par exemple : « je m'arrête là, je bois de l'eau, je reprends demain »."],["Je préfère ne pas y penser","C'est compréhensible, mais prévoir réduit la peur. Ça prend 2 minutes et tu seras plus serein(e)."]]},["Anticiper apaise","Prévoir ce qu'on fera en cas de craquage réduit la panique et l'effet « tant pis ».","Relis ton plan B ce soir."]],["Attentes et vraies relations","Ce qu'on voit à l'écran est une mise en scène. S'en détacher aide à retrouver du désir et du lien avec de vraies personnes, avec leurs rythmes et leurs envies.","Écris ce que tu veux dans une vraie relation (lien, complicité, écoute). Laisse de côté ce que tu as vu à l'écran.",null,{},{"q":"Dans 6 mois, tu aimerais être quelqu'un qui…","o":[["Dort bien","Un objectif concret : les nuits s'améliorent souvent dès les premières semaines."],["Tient ses engagements","Chaque petit engagement tenu renforce la confiance en toi."],["A de l'énergie","L'énergie revient avec le sommeil, le mouvement et moins d'à-coups."],["Se sent libre","La liberté, c'est choisir. Chaque envie traversée est un choix de plus."]]},["L'ocytocine du contact","Le contact (se serrer, toucher, parler sincèrement) libère de l'ocytocine, liée au lien et à l'apaisement.","Un échange sincère ou un câlin aujourd'hui."]],["Les moments à risque à venir","Voyages, soirées seul, périodes de stress : certains moments vont remettre l'envie en jeu. Les prévoir, c'est déjà y être préparé.","Liste les 3 prochains moments à risque des 4 semaines à venir et ce que tu feras à chaque fois.",null,{},{"q":"Ton prochain moment à risque, c'est…","o":[["Un week-end","Prévois deux activités par jour et une heure de coucher."],["Une fête ou un événement","Décide à l'avance ce que tu fais et à quelle heure tu pars."],["Une période de stress","Planifie des pauses et du mouvement. Le stress est un déclencheur majeur."],["Je ne sais pas","Regarde ton agenda des 2 semaines à venir : tu en verras un ou deux."]]},["Le contexte déclenche","Un lieu ou une heure associés à l'habitude suffisent à déclencher l'envie. Les repérer permet de s'y préparer.","Note ton prochain moment à risque."]],["Mieux dormir","Le téléphone au lit, tard le soir, est un déclencheur et un voleur de sommeil. Dormir mieux rend les envies plus faciles à gérer.","Ce soir, charge ton téléphone hors de ta chambre. Utilise un réveil classique si besoin.","evening",{},{"q":"Tes nuits en ce moment ?","o":[["Courtes","Une nuit courte renforce l'envie et réduit le contrôle. Couche-toi 30 minutes plus tôt ce soir."],["Agitées","Écrans coupés 30 minutes avant, chambre fraîche (18-19 °C) et dîner léger aident."],["Correctes","Bien. Garde un horaire régulier : c'est ça qui consolide."],["Très bonnes","Parfait. Protège-les : c'est un de tes meilleurs alliés."]]},["Sommeil et impulsivité","Une nuit courte réduit le contrôle des impulsions. Dormir 7 à 9 heures est un des meilleurs outils.","Fixe une heure de coucher."]],["Le temps que tu récupères","Ce temps est ton vrai gain. Le chiffrer le rend concret et motive.","Estime les heures par semaine que ça te prenait. Multiplie par 4. Écris ce que tu peux faire avec ce temps.",null,{},{"q":"Le temps ou l'argent récupéré, tu en feras…","o":[["Du repos","Le repos compte aussi. Planifie-le au lieu de le subir."],["Un projet","Choisis un petit projet de 30 minutes par jour : c'est ce qui remplit le vide."],["Du temps avec des proches","Les liens sont l'un des meilleurs soutiens pour tenir."],["Un plaisir ou de l'épargne","Mets une somme de côté chaque semaine : la voir grossir motive."]]},["Du temps pour toi","Quelques heures par semaine récupérées font plusieurs jours par an : de quoi relancer un projet ou une activité.","Choisis 30 minutes récupérées pour une activité."]],["Ton réseau de soutien","Si tu n'y arrives pas seul, ou si ça affecte ton couple, ton sommeil ou ton humeur, un médecin, un psychologue ou un sexologue peut t'aider. Ce n'est pas un échec.","Repère un professionnel (médecin généraliste pour commencer). Si tu vas mal, le 3114 répond 24h/24.",null,{},{"q":"Qui est ton premier appel en cas de coup dur ?","o":[["Un(e) ami(e)","Garde son numéro en favori. Dis-lui d'avance qu'il peut t'aider."],["Un proche de la famille","Préviens-le à l'avance : il saura quoi répondre quand ça arrivera."],["Un professionnel","ton médecin ou un psychologue est joignable. Note le numéro dans ton téléphone."],["Je n'ai pas de nom","Alors ton médecin ou un psychologue peut être ce nom. C'est gratuit, tu n'as pas à te justifier."]]},["Le lien protège","Des liens sociaux de qualité sont associés à une meilleure santé et à de meilleures chances de tenir un changement.","Propose un moment à quelqu'un cette semaine."]],["Lettre à toi-même","Ce que tu as fait pendant 30 jours mérite d'être écrit. Cette lettre te servira les jours où tu auras oublié pourquoi c'était important.","Écris-toi une lettre pour dans 3 mois : ce que tu as appris, ce que tu veux avoir gardé, ce que tu te souhaites.","letter",{},{"q":"Pour toi dans 3 mois, le plus important à te rappeler ?","o":[["Ce que j'ai tenu","Écris-le : les chiffres sont des preuves quand le doute revient."],["Pourquoi j'ai commencé","Relis ton pourquoi du premier jour. Il est dans ton espace."],["Que ça passe","Oui : une envie passe toujours. C'est ta meilleure information."],["Que je mérite d'aller bien","C'est vrai. Écris-le comme si tu parlais à un ami."]]},["Écrire aide","Écrire ce qu'on ressent aide à réguler les émotions, c'est ce qu'on appelle l'écriture expressive.","Écris 5 minutes, sans te relire."]],["Et maintenant ?","30 jours, c'est un début, pas une fin. Garde 2 ou 3 règles qui ont marché, relâche le reste, et refais le point une fois par mois.","Choisis les 3 règles à garder. Plante un rappel mensuel dans ton agenda.","final",{},{"q":"Pour la suite, tu comptes…","o":[["Continuer chaque jour","Excellent. La régularité fait plus que l'intensité."],["Faire un point par semaine","Très bien : un point de 10 minutes le dimanche suffit."],["Appeler en cas de doute","ton médecin ou un psychologue est là. Un coup de fil évite souvent une rechute."],["Je ne sais pas encore","Pas de pression. Garde juste la règle : au moindre doute, 10 minutes d'attente et un souffle lent."]]},["Garder le cap","Les rechutes sont fréquentes dans tout changement de comportement ; ce qui compte, c'est de reprendre vite.","Fixe un rappel mensuel pour faire le point."]]]},"jeux-d-argent":{"kit":{"raisons":["Protéger mon argent","Retrouver la paix avec mes proches","Arrêter de mentir","Rembourser mes dettes","Dormir tranquille","Reprendre le contrôle","Avoir un projet","Être fier de moi","Moins de stress","Retrouver du temps"],"pros":["L'excitation","L'espoir de gagner","L'évasion","Être avec des amis","Me sentir vivant","Oublier mes soucis"],"cons":["Je perds de l'argent","Je mens à mes proches","Je suis stressé en permanence","Je dors moins","Je m'endette","Je pense au jeu tout le temps","Je m'éloigne des gens","J'ai honte"],"calc":{"q":"Combien mets-tu par semaine ?","unit":"€ par semaine","min":0,"max":500,"step":5,"def":40,"mult":52,"out":"€ par an","div":0,"divLabel":"","eq":[500,"week-ends en amoureux"],"gain":"récupérés chaque année"},"env":["Désinstaller les applis de paris","Supprimer les cartes enregistrées","Me désabonner des mails de promotions","Demander l'interdiction volontaire de jeux (site de l'ANJ)","Mettre en place un virement d'épargne le jour de la paie","Demander à un proche de garder une carte"],"triggers":["Le jour de paie","Un jour de match","Une notification de bonus","L'ennui","Après une perte","Avec des amis qui jouent","Quand je suis stressé","Le week-end","Tard le soir","Quand j'ai de l'argent sur moi"],"actions":["Ne rien déposer pendant 24 heures","Appeler quelqu'un","Sortir marcher","Respirer 1 minute","Fermer l'appli et la désinstaller","Faire du sport","Écrire le montant déjà perdu","Changer de pièce","Regarder le match sans parier","Écouter de la musique"],"distract":["Bonus de bienvenue","Cote boostée ce soir","Dernière chance de te refaire","Match en direct","Tu as 20 € offerts","Ton pari t'attend"],"myths":[["Après une série de pertes, un gain est « dû ».",false,"Chaque pari est indépendant. Le hasard n'a pas de mémoire."],["Une mise pour se refaire règle le problème.",false,"Courir après ses pertes les aggrave presque toujours."],["Les bonus sont un cadeau.",false,"Les bonus sont conçus pour te faire jouer plus longtemps."],["L'envie de jouer finit par retomber si on ne fait rien.",true,"Elle monte, atteint un pic, puis redescend. Attendre 24 heures aide."],["Parler de ses dettes à quelqu'un est une faiblesse.",false,"Demander de l'aide est une force. Des conseillers gratuits existent."],["Bloquer l'accès aux sites aide à tenir.",true,"Moins de facilité, c'est moins de décisions sous l'impulsion."]],"pairs":[["Le jour de paie","Virement d'épargne automatique"],["Un jour de match","Regarder sans parier"],["Une notification","Désinstaller l'appli"],["L'ennui","Sortir marcher"],["Après une perte","Appeler quelqu'un"]],"pieges":[["Je vais me refaire.",true,"C'est la pensée la plus coûteuse : chaque mise pour récupérer alourdit la perte."],["J'ai un système.",true,"Aucun système ne bat la mathématique du jeu sur la durée."],["Je peux attendre 24 heures avant de déposer.",false,"Oui : l'envie retombe, tu décides à tête reposée."],["J'étais proche, la prochaine sera la bonne.",true,"Être « proche » n'a aucune valeur. Chaque pari est indépendant."],["Je vais en parler à Joueurs info service.",false,"Excellente idée : c'est gratuit, anonyme, au 09 74 75 13 13."],["Juste un petit pari pour le match.",true,"Un petit pari relance le cycle. Regarde le match, sans mise."],["Un dérapage n'efface pas mes progrès.",false,"Exact. Arrête-toi là et reprends le fil."],["Ce n'est que de l'argent.",true,"C'est ton argent, ton temps et ta tranquillité."]],"scenarios":[{"q":"C'est le jour de paie. Une notification te propose un bonus de 20 €.","c":[["Je dépose un petit montant pour en profiter",0,"Les bonus sont faits pour te faire jouer plus. C'est le piège."],["Je supprime la notification et je vire une part de ma paie en épargne",2,"Parfait : tu protèges ton argent avant d'avoir la tentation."],["J'attends demain pour décider",1,"Bon réflexe : la règle des 24 heures. Ajoute le virement d'épargne."]]},{"q":"Tu as perdu 80 € hier. Ce soir, l'envie de te refaire est très forte.","c":[["Je mise plus pour récupérer d'un coup",0,"C'est le piège le plus coûteux : la perte grossit."],["Je ne dépose rien, je note le montant perdu et j'appelle quelqu'un",2,"Tu casses le cycle : tu agis, tu n'attends pas que l'envie passe seul."],["Je me dis que je jouerai juste un peu",0,"« Juste un peu » relance la spirale."]]},{"q":"Tes amis regardent le match et parient entre eux.","c":[["Je regarde sans parier et je prends une boisson",2,"Tu restes dans le groupe sans jouer. C'est possible."],["Je pars sans rien dire",1,"Ça protège, mais n'oublie pas d'expliquer à un ami pourquoi."],["Je mise une petite somme pour ne pas me sentir à l'écart",0,"C'est ce qui relance le cycle. Préviens plutôt un ami de ta décision."]]}],"relapse":{"heure":["Je m'arrête et je ne redépose rien","Je bloque mes paiements et mes comptes","J'appelle quelqu'un"],"ajuster":["Je demande l'interdiction volontaire de jeux","Je confie ma carte à un proche","Je désinstalle les applis restantes"],"prevenir":["Un ami proche","Mon frère ou ma sœur","Mon conjoint ou ma conjointe","Un professionnel","Personne, je gère seul"]},"events":["Jour de paie","Grand tournoi sportif","Soirée entre amis","Week-end seul","Période de stress","Vacances"],"messages":["J'essaie d'arrêter les paris. Peux-tu m'aider à ne pas jouer pendant les matchs ?","Je veux reprendre le contrôle de mon argent. Peux-tu garder ma carte ce mois-ci ?"],"rules":["Garder mes barrières en place","Utiliser le bouton SOS à chaque envie","Prévoir mes moments à risque","Parler à quelqu'un quand c'est dur","Bouger régulièrement","Bien dormir","Me récompenser autrement","Faire un point chaque mois","Ne jamais déposer le jour même","Jamais de pari pour se refaire"],"identite":["qui décide de son temps","qui tient ses engagements","qui prend soin de lui","qui sait demander de l'aide","qui ose dire non","qui se réveille avec de l'énergie","qui choisit ses soirées","qui protège son argent","qui est présent avec ses proches","qui avance sur ses projets","qui se respecte","qui ne se juge plus durement"],"rewards":["Un bon repas au restaurant","Une sortie au cinéma","Un week-end dans la nature","Un vêtement qui me plaît","Un moment avec un ami","Une journée sans rien faire","Un livre ou un jeu","Un hammam ou un massage","Un petit voyage","Un cadeau pour quelqu'un"],"evening":["Fixer l'heure du coucher","Téléphone hors du lit","Écrans éteints 30 minutes avant","Douche ou tisane","Préparer la journée de demain","Respirer 2 minutes"],"people":["Un ami proche","Mon frère ou ma sœur","Mon conjoint ou ma conjointe","Un parent","Un collègue de confiance","Mon médecin"],"pause":["Lève-toi et étire-toi","Bois un verre d'eau, lentement","Regarde loin, par la fenêtre","Respire lentement 5 fois","Note ce que tu ressens, en une phrase"],"money":["Mettre en place un virement d'épargne le jour de la paie","Fixer un plafond de retrait hebdomadaire","Confier une carte à un proche","Demander l'interdiction volontaire de jeux (ANJ)","Supprimer les moyens de paiement enregistrés"],"steps":["Lister toutes mes dettes et leurs montants","Appeler un Point Conseil Budget (gratuit)","Prévenir mes créanciers avant les retards","Établir un budget mensuel simple","Ne contracter aucun nouveau crédit","Appeler Joueurs info service : 09 74 75 13 13"]},"days":[["Ton pourquoi","Avant de changer quoi que ce soit, sache pour quoi tu le fais : l'argent, la famille, la tranquillité, le temps. Ce pourquoi sera ta réserve les jours difficiles.","Écris 3 raisons personnelles d'arrêter. Garde-les en note sur ton écran de verrouillage.","choose",{},{"q":"Qu'est-ce qui te pousse à changer aujourd'hui ?","o":[["Ma santé","Excellent moteur. Le corps commence à récupérer très tôt : chaque jour compte déjà, même si tu ne le sens pas encore."],["Mon argent","Chiffrer l'argent regagné est l'un des meilleurs rappels les jours difficiles. On le fera dans quelques jours."],["Mes proches","Faire ça pour les autres aide, mais garde aussi une raison rien que pour toi : c'est elle qui tient quand personne ne regarde."],["Je me sens dépassé(e)","C'est une raison valable. Tu n'as pas à tout régler aujourd'hui : un seul petit pas suffit pour commencer."]]},["Le cerveau aime l'incertain","La dopamine monte surtout à l'attente d'un gain incertain, plus qu'au gain lui-même. C'est l'attente qui accroche.","Remarque l'excitation avant de miser, pas après."]],["Le vrai chiffre","On se souvient des gains, on oublie les pertes. Le premier acte de contrôle, c'est de regarder le vrai chiffre, sans te juger.","Sur tes relevés bancaires des 3 derniers mois, additionne les dépôts sur les sites de jeux et de paris. Soustrais les retraits. Écris le résultat.","calc",{},{"q":"Ton estimation de ta semaine dernière, elle est…","o":[["Plutôt juste","C'est rare : la plupart des gens sous-estiment. Vérifie quand même avec les vrais chiffres ce soir."],["Sûrement en dessous de la réalité","C'est le cas de presque tout le monde : le cerveau oublie les automatismes. Mesurer sans te juger, c'est tout ce qu'on te demande."],["Je n'ose pas regarder","Normal : voir le chiffre pique un peu. C'est pourtant ce qui permet de reprendre la main. Regarde-le comme un simple relevé."],["Je n'en ai aucune idée","Alors note pendant 3 jours, une ligne à chaque fois. Les automatismes se voient dès qu'on les écrit."]]},["La maison gagne","Les jeux sont conçus avec un avantage pour l'opérateur : sur la durée, la perte attendue est certaine, même si de petits gains arrivent.","Écris le total que tu as misé le mois dernier."]],["Ce que ça t'apporte, ce que ça te coûte","Le jeu te donne de l'excitation, de l'espoir, une évasion. Le reconnaître permet de chercher d'autres sources. Il a aussi un coût : argent, stress, mensonges, temps.","Fais deux colonnes : ce que le jeu t'apporte / ce qu'il te coûte. Souligne ce qui pèse le plus.",null,{},{"q":"Qu'est-ce que ça t'apporte de jouer ?","o":[["Me détendre","La détente est réelle mais courte : elle soulage surtout le manque que l'habitude crée. Respiration lente, marche ou douche chaude donnent un calme plus durable."],["Ne plus penser à rien","C'est un vrai besoin : ton cerveau veut une pause. Une vraie pause (marche, étirements) repose mieux et ne laisse pas de culpabilité."],["Me sentir moins seul(e)","Besoin légitime. Un message ou un appel, même court, y répond mieux et plus longtemps."],["Du plaisir, tout simplement","Le plaisir compte. L'idée n'est pas de t'en priver mais de le retrouver ailleurs : dans quelques jours tu choisiras tes remplaçants."]]},["Les « presque gagné »","Un « presque gagné » active les circuits de la récompense presque comme un gain, et pousse à rejouer.","Quand tu « as failli gagner », rappelle-toi : c'est une perte."]],["Tes déclencheurs","La paie, un match, une notification de bonus, l'ennui, après une perte : ce sont des déclencheurs. Quand tu les repères, tu les vois venir.","Note les 5 dernières fois où tu as joué : le jour, l'heure, ce qui s'est passé juste avant et ce que tu ressentais.","heat",{},{"q":"Quand l'envie est-elle la plus forte ?","o":[["Le soir, seul(e)","Fatigue et solitude : le soir, le cerveau freine moins bien. Prévois quelque chose de précis pour ces heures-là."],["Quand je m'ennuie","L'ennui est un déclencheur très fréquent. Il retombe en quelques minutes si on ne le fuit pas : prépare une action de 5 minutes."],["Quand je suis stressé(e)","Le stress donne envie d'un soulagement rapide. Un souffle plus long à l'expiration (4 s / 6 s) calme le corps en 2 minutes."],["Avec d'autres personnes","Le contexte social pèse beaucoup. Dire à une personne que tu changes suffit souvent à désamorcer."]]},["Des signaux qui conditionnent","Notifications, sons, bonus, matchs : ces signaux conditionnent l'envie. Les couper réduit le déclenchement.","Coupe toutes les notifications de paris."]],["Verrouiller l'accès","La volonté s'épuise, des barrières font le travail. Supprimer la facilité, c'est supprimer des décisions sous l'impulsion.","Désinstalle les applis de paris, supprime les cartes enregistrées, désabonne-toi des mails promotionnels. Renseigne-toi sur l'interdiction volontaire de jeux sur le site de l'ANJ.",null,{},{"q":"Quelle barrière poses-tu en premier ?","o":[["Supprimer l'accès","Chaque étape en plus fait baisser le passage à l'acte : un obstacle de 20 secondes laisse souvent l'envie retomber."],["Changer de lieu ou d'horaire","Les habitudes sont liées à des lieux et des heures. Change l'un des deux et l'automatisme perd son déclencheur."],["Prévenir quelqu'un","Dire ton objectif à voix haute le rend plus réel et te donne un témoin bienveillant."],["Aucune, c'est trop dur","Prends la plus petite, une seule. Une barrière imparfaite vaut mieux qu'un plan parfait jamais appliqué."]]},["La friction aide","Plus il y a d'étapes (désinstaller, retirer sa carte), plus l'envie a le temps de retomber.","Désinstalle une application de paris."]],["Le plan « si… alors… »","Un plan précis marche mieux qu'une bonne intention. Tu décides à l'avance de ce que tu feras quand le déclencheur arrive.","Écris 3 phrases : « Si je reçois une notification / un jour de match / après avoir perdu, alors je… » avec une action concrète.","pairs",{},{"q":"Quel plan « si… alors… » te ressemble ?","o":[["Si l'envie vient, je bois de l'eau et j'attends 10 minutes","Un délai court plus un geste simple : c'est très efficace. Les plans précis marchent bien mieux que les bonnes intentions."],["Si je m'ennuie, je sors 5 minutes","Bouger change l'état du corps et coupe l'automatisme. Même monter un escalier compte."],["Si je suis stressé(e), je respire 1 minute","Inspire 4 secondes, souffle 6 : l'expiration longue ralentit le cœur et calme le système nerveux."],["Si je craque, j'appelle quelqu'un","Parler casse l'isolement et la honte, qui poussent à recommencer."]]},["L'expiration longue","Souffler plus longtemps qu'on inspire active le frein du système nerveux et fait baisser l'excitation.","Inspire 4 s, souffle 6 s, cinq fois."]],["Bilan de la semaine 1","Tu connais ton chiffre, tes déclencheurs, et tu as verrouillé l'accès. C'est la base.","Complète : « Ce que j'ai appris sur moi cette semaine, c'est… ». Choisis le moment le plus risqué de la semaine prochaine.",null,{},{"q":"Cette semaine, qu'est-ce qui t'a le plus surpris(e) ?","o":[["À quel point c'est automatique","Voir l'automatisme, c'est déjà la moitié du chemin : on ne peut changer que ce qu'on remarque."],["Les moments où l'envie arrive","Tu connais maintenant tes heures et tes lieux : tu peux les anticiper au lieu de les subir."],["Que ça passe quand j'attends","C'est l'info la plus utile : une envie qui passe n'est pas un ordre."],["Rien de spécial","Pas grave, c'est une semaine d'observation. Continue : les effets arrivent avec la pratique."]]},["Fatigué, on décide mal","Fatigué, on prend de plus mauvaises décisions, financières notamment. Le sommeil protège le cortex préfrontal, celui qui freine.","Pas de pari après 22 h, jamais."]],["Comprendre l'envie de jouer","L'envie monte, atteint un pic, puis retombe, même si tu ne fais rien. L'espoir de gagner est puissant, mais il ne dure pas. Une envie n'est pas un ordre.","Quand l'envie arrive, attends 2 minutes avant d'agir. Où la sens-tu dans le corps ? Que devient-elle ?","wave",{},{"q":"Quand l'envie arrive, que fais-tu d'habitude ?","o":[["Je cède tout de suite","Normal : céder soulage vite, et c'est ce qui apprend au cerveau à recommencer. Aujourd'hui, repousse seulement de 10 minutes."],["Je lutte de toutes mes forces","Lutter épuise. Observe l'envie comme une vague : elle monte, plafonne, redescend. Laisse-la passer sans la combattre."],["Je me distrais","Très bien : 10 minutes de distraction suffisent souvent. Prépare-en deux à l'avance, à portée de main."],["Je ne sais pas","Aujourd'hui, note l'heure et ce que tu ressens quand elle vient. Un schéma va apparaître."]]},["Une vague","L'envie de jouer monte, plafonne puis redescend, même si on ne fait rien.","Chronomètre ta prochaine envie."]],["La règle des 24 heures","Ne dépose jamais le jour même. En te donnant 24 heures, tu laisses l'envie retomber, et tu décides à tête reposée.","Utilise le bouton SOS à chaque envie. Écris-toi : « Pas de dépôt avant demain ».","hold",{"sec":24,"t":"Les 24 heures, version courte"},{"q":"Peux-tu tenir 10 minutes avant de passer à l'acte ?","o":[["Oui, facilement","Alors fais-en une règle : la plupart des envies retombent avant 10 minutes."],["Oui, avec une distraction","Parfait. Prépare deux distractions : musique, verre d'eau, marche. Elles font la moitié du travail."],["Difficile","Commence par 2 minutes. Chaque envie traversée entraîne ton cerveau à tolérer l'inconfort."],["Impossible","Pas de souci : 1 minute compte déjà. Le bouton SOS te guide pendant 10 minutes, un souffle après l'autre."]]},["24 heures","Attendre 24 heures laisse l'excitation et le stress redescendre : on décide à tête reposée.","Écris : « pas de dépôt avant demain »."]],["Respirer pour retomber","Une respiration lente, avec un souffle plus long que l'inspiration, aide à calmer le corps en quelques minutes.","Fais 2 minutes de respiration (inspire 4 secondes, souffle 6) quand l'envie monte.","breathe",{},{"q":"Quand tu es tendu(e), ton souffle est plutôt…","o":[["Court et haut","Respirer haut met le corps en alerte. Allonge l'expiration : c'est le levier le plus rapide pour te calmer."],["Je le retiens parfois","Retenir son souffle augmente la tension. Souffle doucement par la bouche, comme dans une paille."],["Je n'y ai jamais fait attention","Pose une main sur le ventre : si elle ne bouge pas, ta respiration est haute. Essaie de la faire gonfler."],["Plutôt calme","Bien. Garde ce réflexe pour les moments d'envie, c'est là qu'il compte le plus."]]},["Le nerf vague","Respirer lentement stimule le nerf vague, qui ralentit le cœur et apaise.","Deux minutes de respiration avant d'ouvrir une appli."]],["« Je vais me refaire »","C'est la pensée la plus coûteuse. Chaque mise pour récupérer une perte rend la suivante plus lourde. Les mathématiques ne sont pas de ton côté.","Écris le montant que tu as déjà perdu et ce que tu aurais pu en faire. Relis-le quand l'envie de te refaire monte.","chase",{},{"q":"Pour t'occuper 10 minutes, tu préfères…","o":[["Bouger","Le mouvement réduit les envies et améliore l'humeur en quelques minutes."],["Parler à quelqu'un","Une voix humaine apaise plus vite qu'un écran ou un produit."],["Faire quelque chose de mes mains","Cuisine, dessin, rangement : occuper les mains occupe aussi l'attention, l'envie perd de la place."],["Rien ne me tente","Normal au début : l'envie rend tout fade. Essaie quand même 3 minutes, l'envie baisse avant que l'activité ne devienne agréable."]]},["Se refaire coûte plus","Après une perte, le cerveau cherche à la compenser (aversion à la perte). C'est l'une des erreurs de jugement les plus coûteuses.","Écris le montant déjà perdu, et relis-le au moment de « te refaire »."]],["Confier la gestion de ton argent","Moins tu as d'accès direct à l'argent, moins tu peux jouer sur un coup de tête. Demander de l'aide ici est une force.","Mets en place un virement automatique d'épargne le jour de la paie. Pense à confier un compte à un proche, ou à fixer un plafond de paiement.",null,{},{"q":"Quand tu es stressé(e), ton corps réagit surtout par…","o":[["De la tension (épaules, mâchoire)","Relâche : épaules vers le bas, mâchoire détendue, trois souffles lents."],["De la fatigue","La fatigue baisse le frein de la volonté. Une sieste de 15 à 20 minutes aide, sinon couche-toi plus tôt ce soir."],["De l'agitation","Marche rapide 5 minutes : elle dépense l'adrénaline en trop."],["Je ne sais pas","Scanne : tête, épaules, ventre, jambes. Où ça serre ? C'est là qu'il faut respirer."]]},["Le stress de l'argent","Les soucis d'argent maintiennent le corps en alerte (cortisol), ce qui donne envie d'un soulagement rapide.","Marche 10 minutes quand l'inquiétude monte."]],["Bonus, cotes et publicités","Bonus, cotes « boostées », notifications : ces outils sont conçus pour te faire jouer plus. Savoir comment ils fonctionnent aide à ne plus tomber dans le panneau.","Désactive toutes les notifications liées aux paris. Note la dernière promotion qui t'a fait craquer.","myths",{},{"q":"Quelle idée te retient le plus ?","o":[["J'en ai besoin pour me détendre ou dormir","Ça détend sur l'instant mais entretient le manque ensuite. À terme, la détente et le sommeil naturels reviennent."],["Je gère, ce n'est pas un problème","Si tu es ici, c'est que tu veux plus de contrôle. Fais confiance à ça."],["Tout le monde le fait","Beaucoup le font, et beaucoup changent aussi. Tu n'es pas seul(e) dans les deux cas."],["Juste une fois ne compte pas","Chaque fois renforce le circuit de l'habitude. L'exception est souvent la porte d'entrée."]]},["Les bonus sont un appât","Bonus et cotes « boostées » sont conçus pour prolonger le jeu. Les comprendre aide à ne plus tomber dans le panneau.","Note la dernière offre qui t'a fait jouer."]],["Bilan de la semaine 2","Tu as appris à voir l'envie venir, à l'attendre et à protéger ton argent. Chaque jour sans jouer compte.","Regarde ton compteur de jours sans jouer et d'envies surmontées. Note le moment le plus dur et ce qui t'a aidé.",null,{},{"q":"Ce qui t'a le plus aidé(e) cette semaine ?","o":[["Attendre 10 minutes","Garde-le : c'est ton outil principal. Il marche d'autant mieux qu'il est automatique."],["Respirer","La respiration est toujours avec toi. Utilise-la avant que l'envie ne soit à son maximum."],["Éloigner ce qui donne accès","Bien joué : réduire l'accès est l'une des méthodes les plus solides."],["Rien de précis","Pas grave. Regarde le bilan : tu as peut-être tenu plus que tu ne le penses."]]},["L'énergie du mouvement","L'activité physique libère des endorphines et fait baisser le stress, sans risque financier.","20 minutes de sport à l'heure où tu jouais."]],["Remplacer l'excitation","Le jeu comblait un besoin d'excitation ou d'évasion. Cherche d'autres sources : sport, défis, projets, rencontres.","Liste 5 activités qui te donnent de l'énergie ou du plaisir (sport, défi, loisir, sortie). Planifie-en une cette semaine.",null,{},{"q":"Quel remplaçant te semble le plus réaliste ?","o":[["Un geste (eau, étirements)","Les petits gestes sont faciles à répéter. Garde-les à portée de main."],["Une activité courte (marche, jeu)","Dix minutes suffisent souvent. Choisis-en une que tu peux faire n'importe où."],["Une personne (appel, message)","Un lien humain est l'un des meilleurs remplaçants. Mets 2 prénoms dans tes favoris."],["Je n'en ai pas encore","Essaie les trois cette semaine. Tu verras vite lequel marche pour toi."]]},["Une excitation saine","On peut retrouver de l'excitation par le sport, les défis ou les rencontres : l'adrénaline de l'effort est un bon substitut.","Planifie une activité qui te met au défi."]],["Bouger","Le mouvement change l'humeur et occupe les moments à risque. Pas besoin de sport intense : marcher compte.","Fais 20 minutes d'activité physique aujourd'hui, de préférence à l'heure où tu jouais.","move",{},{"q":"Ton niveau de mouvement dans une journée ?","o":[["Presque aucun","Commence par 5 minutes de marche : c'est déjà un effet mesurable sur l'humeur."],["Un peu","Ajoute 10 minutes à l'heure où l'envie est la plus forte."],["Régulier","Excellent. Place-le aux heures à risque : c'est là qu'il protège le plus."],["Beaucoup","Parfait. N'oublie pas le repos : il fait partie de la récupération."]]},["Bouger fait baisser l'envie","Marcher 10 à 15 minutes améliore souvent l'humeur et réduit l'envie sur le moment.","Une marche, sans téléphone."]],["Jours de match et soirées","Les gros événements sportifs et les soirées entre amis sont des moments à risque. Un plan évite de se retrouver coincé.","Regarde les 2 prochains événements sportifs importants. Décide à l'avance ce que tu feras : où tu regardes, avec qui, sans pari.",null,{},{"q":"Le plus dur dans tes week-ends, c'est…","o":[["Le temps libre","Prévois deux activités par jour : le vide appelle l'habitude."],["Les amis","Propose un lieu ou une activité sans l'habitude, ou dis-le d'avance. Les vrais amis comprennent."],["Le soir tard","Fixe une heure limite de coucher : la fatigue baisse les défenses."],["Rien de particulier","Prévois quand même un plan B, au cas où."]]},["Le direct amplifie","L'émotion du direct et le contexte social amplifient l'impulsivité. Un plan à l'avance protège.","Décide d'avance où tu regardes le match, sans pari."]],["En parler à quelqu'un","Cacher entretient la honte et les pertes. Parler à un proche de confiance, ou à Joueurs info service (09 74 75 13 13, gratuit et anonyme), allège.","Choisis une personne de confiance et dis-lui que tu arrêtes les paris. Ou appelle Joueurs info service.",null,{},{"q":"À qui pourrais-tu en parler ?","o":[["Un(e) ami(e)","Un ami de confiance suffit. Dis simplement : « j'essaie de changer, peux-tu me demander demain comment ça va ? »"],["Un proche de la famille","Choisis la personne la plus calme et la moins critique. Un message écrit peut être plus facile."],["Un professionnel ou une ligne d'aide","Excellente idée : Joueurs info service (09 74 75 13 13) est là pour ça, gratuitement et sans jugement."],["Personne pour l'instant","C'est possible, et ce n'est pas grave. Une ligne d'aide (Joueurs info service (09 74 75 13 13)) peut être ton premier interlocuteur."]]},["Le secret pèse","Cacher le jeu entretient le stress et la honte, deux moteurs de l'envie.","Parle à une personne de confiance ou appelle le 09 74 75 13 13."]],["Les pensées-pièges","« Juste un petit pari », « j'ai un système », « j'étais proche ». Ces phrases sont normales. Les repérer leur enlève du pouvoir.","Écris 3 phrases que tu te dis avant de parier. À côté de chacune, une réponse honnête et courte.","pieges",{},{"q":"Quelle pensée te fait le plus craquer ?","o":[["« Juste une fois »","C'est le piège le plus courant. Réponse : « si c'est juste une fois, je peux attendre demain »."],["« Je l'ai bien mérité »","Oui, et tu peux te récompenser autrement : repas, film, sortie. Sans la facture."],["« Je m'y mets demain »","Demain sera pareil. Réponse : « je commence par les 10 prochaines minutes »."],["« J'ai déjà craqué, tant pis »","Un faux pas n'efface pas les jours passés. Reprends dès la prochaine heure."]]},["L'illusion de contrôle","Le cerveau croit pouvoir « lire » le hasard. Chaque tirage est pourtant indépendant, aucun système ne bat les maths.","Écris la pensée « j'ai un système » et sa réponse honnête."]],["Te récompenser autrement","Ton cerveau aime les petites récompenses. Tu peux en garder sans jouer : un bon repas, un loisir, un week-end avec l'argent économisé.","Choisis une récompense pour chaque semaine tenue. Calcule combien ça coûte, et compare à ce que tu aurais joué.",null,{},{"q":"Quelle récompense te ferait vraiment plaisir ?","o":[["Un bon repas","Parfait : choisis le jour et le lieu à l'avance, une récompense prévue motive mieux qu'une récompense improvisée."],["Une sortie","Planifie-la dans ton agenda dès aujourd'hui : l'avoir devant soi aide à tenir."],["Un achat","Mets de côté la somme économisée dans une enveloppe : la voir grossir motive."],["Du repos","Le repos est une vraie récompense. Offre-toi une soirée sans obligation."]]},["La récompense prévue","Une récompense choisie à l'avance renforce un nouveau comportement mieux qu'une récompense improvisée.","Choisis ta récompense de la semaine, financée par l'argent non joué."]],["Bilan de la semaine 3","Trois semaines de pratique. Regarde ce qui a changé : l'argent, le stress, le sommeil, l'humeur.","Écris 3 changements que tu constates, même petits.",null,{},{"q":"Ce qui a changé depuis le début ?","o":[["Mon sommeil","Un meilleur sommeil réduit l'impulsivité : c'est un cercle vertueux qui s'installe."],["Mon humeur","Chaque jour, le cerveau se rééquilibre un peu. L'humeur suit souvent avec un décalage."],["Mon argent","Note la somme : c'est un des gains les plus concrets."],["Pas encore grand-chose","Normal : les changements sont souvent lents au début. Continue, ils arrivent avec la régularité."]]},["Le sommeil répare","Un sommeil régulier améliore l'humeur et le contrôle des impulsions.","Couche-toi à heure fixe ce soir."]],["Un dérapage n'est pas une rechute","Si tu craques, arrête immédiatement et ne cherche surtout pas à te refaire. Ce n'est pas un échec, c'est une information. Reprends le fil dès que possible.","Écris ce que tu feras si tu as joué : arrêter, ne rien redéposer, le dire à quelqu'un. Une phrase bienveillante pour reprendre.","scenario",{},{"q":"Si tu craques ce soir, tu te diras…","o":[["« Je suis nul(le) »","La honte nourrit le cycle. Parle-toi comme à un ami : « ça arrive, je reprends »."],["« C'est une information »","Exactement. Note ce qui l'a déclenché et ajuste ton plan."],["« Autant tout lâcher »","C'est l'effet « tant pis », le vrai piège. Reprends au prochain repas, pas à la prochaine semaine."],["« Je préviens quelqu'un »","Excellent réflexe : ça casse l'isolement et la honte."]]},["Un faux pas, pas une chute","Un dérapage ne défait pas les circuits déjà en place. S'arrêter tout de suite compte, ne pas se « refaire ».","Écris : « si je joue, j'arrête et je ne redépose rien »."]],["Ton plan en cas de rechute","Prévoir le plan B enlève la peur. Qu'est-ce qui m'a fait craquer ? Qu'est-ce que je change ? Qui je préviens ?","Rédige un plan en 3 points : ce que je fais dans l'heure (arrêter, geler les paiements, appeler quelqu'un), ce que j'analyse, ce que j'ajuste.","relapse",{},{"q":"En cas de rechute, ce qui t'aiderait le plus ?","o":[["Un message tout prêt","Écris-le maintenant, il sera là quand tu en auras besoin. Tu n'auras plus qu'à l'envoyer."],["Quelqu'un à appeler","Choisis la personne et enregistre son numéro en favori."],["Une règle simple","Par exemple : « je m'arrête là, je bois de l'eau, je reprends demain »."],["Je préfère ne pas y penser","C'est compréhensible, mais prévoir réduit la peur. Ça prend 2 minutes et tu seras plus serein(e)."]]},["Anticiper apaise","Prévoir ce qu'on fera en cas de craquage réduit la panique et l'effet « tant pis ».","Relis ton plan B ce soir."]],["Faire face aux dettes","Si tu as des dettes, les regarder en face est difficile, et c'est ce qui permet d'avancer. Il existe des conseillers gratuits pour t'aider à faire un plan.","Liste tes dettes et leurs montants. Renseigne-toi sur un Point Conseil Budget près de chez toi, gratuit.",null,{},{"q":"Dans 6 mois, tu aimerais être quelqu'un qui…","o":[["Dort bien","Un objectif concret : les nuits s'améliorent souvent dès les premières semaines."],["Tient ses engagements","Chaque petit engagement tenu renforce la confiance en toi."],["A de l'énergie","L'énergie revient avec le sommeil, le mouvement et moins d'à-coups."],["Se sent libre","La liberté, c'est choisir. Chaque envie traversée est un choix de plus."]]},["L'anxiété des dettes","L'angoisse des dettes active la réponse de stress. Faire un plan concret et demander de l'aide la fait redescendre.","Note ce que tu dois et appelle un Point Conseil Budget."]],["Les moments à risque à venir","Jour de paie, grands tournois, fêtes, périodes de stress : certains moments vont remettre le jeu en jeu. Les prévoir, c'est déjà y être préparé.","Liste les 3 prochains moments à risque des 4 semaines à venir et ce que tu feras à chaque fois.",null,{},{"q":"Ton prochain moment à risque, c'est…","o":[["Un week-end","Prévois deux activités par jour et une heure de coucher."],["Une fête ou un événement","Décide à l'avance ce que tu fais et à quelle heure tu pars."],["Une période de stress","Planifie des pauses et du mouvement. Le stress est un déclencheur majeur."],["Je ne sais pas","Regarde ton agenda des 2 semaines à venir : tu en verras un ou deux."]]},["Le contexte déclenche","Un jour de paie, un match, un salon : le cerveau associe ces moments au jeu. Les repérer permet de s'y préparer.","Note les 3 prochaines dates à risque."]],["Mieux dormir","Le stress et les nuits courtes fragilisent. Dormir mieux rend les envies plus faciles à gérer.","Fixe une heure de coucher. Téléphone hors du lit ce soir. Prévois une activité calme avant de dormir.","evening",{},{"q":"Tes nuits en ce moment ?","o":[["Courtes","Une nuit courte renforce l'envie et réduit le contrôle. Couche-toi 30 minutes plus tôt ce soir."],["Agitées","Écrans coupés 30 minutes avant, chambre fraîche (18-19 °C) et dîner léger aident."],["Correctes","Bien. Garde un horaire régulier : c'est ça qui consolide."],["Très bonnes","Parfait. Protège-les : c'est un de tes meilleurs alliés."]]},["Dormir, c'est se protéger","Le manque de sommeil augmente l'attrait pour la prise de risque. Dormir mieux rend les envies plus faciles à gérer.","Fixe une heure de coucher."]],["L'argent que tu récupères","Cet argent est ton vrai gain. Le chiffrer le rend concret et motive.","Reprends ton chiffre du jour 2. Divise-le par 3 pour avoir un montant par mois. Écris ce que tu veux faire avec cet argent.",null,{},{"q":"Le temps ou l'argent récupéré, tu en feras…","o":[["Du repos","Le repos compte aussi. Planifie-le au lieu de le subir."],["Un projet","Choisis un petit projet de 30 minutes par jour : c'est ce qui remplit le vide."],["Du temps avec des proches","Les liens sont l'un des meilleurs soutiens pour tenir."],["Un plaisir ou de l'épargne","Mets une somme de côté chaque semaine : la voir grossir motive."]]},["L'argent regagné","Chaque euro non joué est un euro tangible. Le voir s'accumuler renforce la motivation.","Fais un virement automatique le jour de la paie."]],["Ton réseau d'aide","Si tu n'y arrives pas seul, ou si tu es endetté, en parler à un professionnel est une bonne idée. Ce n'est pas un échec : Joueurs info service (09 74 75 13 13), ton médecin, un centre d'addictologie (CSAPA).","Note le numéro de Joueurs info service et le nom d'un médecin à qui t'adresser. Si tu vas mal, le 3114 répond 24h/24.",null,{},{"q":"Qui est ton premier appel en cas de coup dur ?","o":[["Un(e) ami(e)","Garde son numéro en favori. Dis-lui d'avance qu'il peut t'aider."],["Un proche de la famille","Préviens-le à l'avance : il saura quoi répondre quand ça arrivera."],["Un professionnel","Joueurs info service (09 74 75 13 13) est joignable. Note le numéro dans ton téléphone."],["Je n'ai pas de nom","Alors Joueurs info service (09 74 75 13 13) peut être ce nom. C'est gratuit, tu n'as pas à te justifier."]]},["Le lien protège","Des liens sociaux de qualité sont associés à une meilleure santé et à de meilleures chances de tenir un changement.","Note le 09 74 75 13 13 et un nom de confiance."]],["Lettre à toi-même","Ce que tu as fait pendant 30 jours mérite d'être écrit. Cette lettre te servira les jours où tu auras oublié pourquoi c'était important.","Écris-toi une lettre pour dans 3 mois : ce que tu as appris, ce que tu veux avoir gardé, ce que tu te souhaites.","letter",{},{"q":"Pour toi dans 3 mois, le plus important à te rappeler ?","o":[["Ce que j'ai tenu","Écris-le : les chiffres sont des preuves quand le doute revient."],["Pourquoi j'ai commencé","Relis ton pourquoi du premier jour. Il est dans ton espace."],["Que ça passe","Oui : une envie passe toujours. C'est ta meilleure information."],["Que je mérite d'aller bien","C'est vrai. Écris-le comme si tu parlais à un ami."]]},["Écrire aide","Écrire ce qu'on ressent aide à réguler les émotions, c'est ce qu'on appelle l'écriture expressive.","Écris 5 minutes, sans te relire."]],["Et maintenant ?","30 jours, c'est un début, pas une fin. Garde les barrières qui ont marché, et refais le point une fois par mois. Ne remets jamais le jeu « juste pour voir ».","Choisis les 3 règles à garder. Plante un rappel mensuel dans ton agenda.","final",{},{"q":"Pour la suite, tu comptes…","o":[["Continuer chaque jour","Excellent. La régularité fait plus que l'intensité."],["Faire un point par semaine","Très bien : un point de 10 minutes le dimanche suffit."],["Appeler en cas de doute","Joueurs info service (09 74 75 13 13) est là. Un coup de fil évite souvent une rechute."],["Je ne sais pas encore","Pas de pression. Garde juste la règle : au moindre doute, 10 minutes d'attente et un souffle lent."]]},["Garder le cap","Les rechutes sont fréquentes dans tout changement de comportement ; ce qui compte, c'est de reprendre vite.","Garde l'interdiction volontaire de jeux si tu l'as demandée."]]]},"vape-tabac":{"kit":{"raisons":["Retrouver mon souffle","Ma santé","L'argent économisé","Faire du sport","Être un exemple pour mes proches","Ne plus dépendre d'un produit","Mieux dormir","Retrouver le goût et l'odorat","Avoir plus d'énergie","Me sentir libre"],"pros":["Me détendre","Une pause","Un rituel social","Gérer le stress","Me concentrer","Mes habitudes du café"],"cons":["Je manque de souffle","Ça coûte cher","Je dépends de la nicotine","Je tousse","Je suis irritable quand j'en manque","Je m'inquiète pour ma santé","Je dors moins bien","Ça me prend du temps"],"calc":{"q":"Combien dépenses-tu par semaine ?","unit":"€ par semaine","min":0,"max":150,"step":1,"def":30,"mult":52,"out":"€ par an","div":0,"divLabel":"","eq":[60,"bons restaurants"],"gain":"économisés chaque année"},"env":["Choisir mon jour d'arrêt","Parler à mon pharmacien ou à mon médecin","Jeter ou donner mon matériel","Nettoyer ma voiture et mon logement","Préparer chewing-gums et collations","Prévenir mes proches"],"triggers":["Le café","Après le repas","Une pause au travail","En soirée","Avec de l'alcool","Le stress","Dans la voiture","L'ennui","Avec des amis qui fument","Au réveil"],"actions":["Boire un grand verre d'eau","Mâcher un chewing-gum","Respirer lentement","Marcher 5 minutes","Me brosser les dents","Appeler un ami","Croquer une carotte","Faire les 4 D","Changer de pièce","Écrire ce que je ressens"],"distract":["Un collègue sort fumer","L'odeur d'une cigarette","Pause café","Un ami propose une bouffée","Une publicité de vape","Fin de repas"],"myths":[["Une bouffée après l'arrêt ne change rien.",false,"Elle relance souvent la dépendance. Mieux vaut t'arrêter tout de suite."],["La détente après une cigarette est surtout la fin du manque.",true,"La nicotine calme le manque qu'elle a créé."],["Les envies durent toute la journée.",false,"Elles montent, atteignent un pic et retombent en quelques minutes."],["Des substituts nicotiniques peuvent aider à arrêter.",true,"Parles-en à ton pharmacien ou à ton médecin, ou appelle Tabac info service (39 89)."],["Il faut arrêter seul, sans aide.",false,"L'accompagnement augmente les chances de réussir. Le 39 89 est gratuit."],["Un craquage = tout recommencer de zéro.",false,"Un dérapage n'est pas une rechute : on reprend le fil."]],"pairs":[["Le café","Le boire debout, dans une autre pièce"],["Après le repas","Me brosser les dents"],["Le stress","Respirer lentement"],["En soirée","Une boisson sans alcool à la main"],["Une envie forte","Les 4 D"]],"pieges":[["Juste une.",true,"« Juste une » relance la dépendance."],["Ce soir c'est exceptionnel.",true,"Il y aura toujours une occasion « exceptionnelle »."],["Je vais attendre 10 minutes.",false,"L'envie monte, atteint un pic puis retombe."],["Je contrôle, je peux faire une exception.",true,"Le contrôle revient seulement si tu arrêtes complètement."],["Je peux demander de l'aide au 39 89.",false,"Oui, c'est gratuit et accompagné par un tabacologue."],["Ça va me calmer.",true,"Ça calme le manque créé par la nicotine, pas ton vrai stress."],["Un dérapage n'est pas un échec.",false,"Exact. Tu t'arrêtes là et tu reprends."],["Un seul de plus ne changera rien.",true,"Ça relance l'envie et rapproche de la rechute."]],"scenarios":[{"q":"Pause café au travail. Ton collègue sort fumer comme d'habitude.","c":[["Je sors avec lui, sans fumer",1,"Possible, mais tu restes exposé à l'envie. Mieux vaut changer de routine."],["Je bois mon café debout, ailleurs, avec un chewing-gum",2,"Tu gardes la pause et tu changes le geste. Bien joué."],["Je prends juste une bouffée",0,"Une bouffée relance la dépendance."]]},{"q":"En soirée, après quelques verres, un ami te propose une cigarette.","c":[["Je refuse en disant « non merci, j'arrête »",2,"Simple, clair, tu n'as pas à te justifier."],["J'accepte, c'est la fête",0,"L'alcool et la fête sont les moments les plus risqués. Prévois ton plan à l'avance."],["Je m'éloigne sans rien dire",1,"Ça protège, mais n'hésite pas à expliquer ta décision."]]},{"q":"Jour 3 sans nicotine : tu es irritable et l'envie est très forte.","c":[["Je lance les 4 D : délai, distraction, eau, respiration",2,"Tu appliques une méthode qui marche et tu laisses passer l'envie."],["Je me dis que c'est trop dur et j'abandonne",0,"Les premiers jours sont souvent les plus intenses. Ça passe. Appelle le 39 89 si besoin."],["Je me promets d'arrêter demain",0,"Le « demain » repousse l'arrêt. Tu es déjà dedans."]]}],"relapse":{"heure":["Je m'arrête là et je jette ce qu'il reste","Je bois un verre d'eau et je sors prendre l'air","J'appelle le 39 89 ou un proche"],"ajuster":["Je demande des substituts à mon pharmacien","Je change mes routines du café","Je prends rendez-vous avec mon médecin"],"prevenir":["Un ami proche","Mon frère ou ma sœur","Mon conjoint ou ma conjointe","Un professionnel","Personne, je gère seul"]},"events":["Soirée avec alcool","Pause café","Période de stress","Repas de famille","Vacances","Dispute"],"messages":["J'arrête la cigarette ou la vape. Peux-tu me soutenir cette semaine ?","Peux-tu éviter de m'en proposer ? Ça m'aiderait beaucoup."],"rules":["Garder mes barrières en place","Utiliser le bouton SOS à chaque envie","Prévoir mes moments à risque","Parler à quelqu'un quand c'est dur","Bouger régulièrement","Bien dormir","Me récompenser autrement","Faire un point chaque mois","Aucune bouffée, jamais","Appeler le 39 89 si ça devient dur"],"identite":["qui décide de son temps","qui tient ses engagements","qui prend soin de lui","qui sait demander de l'aide","qui ose dire non","qui se réveille avec de l'énergie","qui choisit ses soirées","qui protège son argent","qui est présent avec ses proches","qui avance sur ses projets","qui se respecte","qui ne se juge plus durement"],"rewards":["Un bon repas au restaurant","Une sortie au cinéma","Un week-end dans la nature","Un vêtement qui me plaît","Un moment avec un ami","Une journée sans rien faire","Un livre ou un jeu","Un hammam ou un massage","Un petit voyage","Un cadeau pour quelqu'un"],"evening":["Fixer l'heure du coucher","Téléphone hors du lit","Écrans éteints 30 minutes avant","Douche ou tisane","Préparer la journée de demain","Respirer 2 minutes"],"people":["Un ami proche","Mon frère ou ma sœur","Mon conjoint ou ma conjointe","Un parent","Un collègue de confiance","Mon médecin"],"pause":["Lève-toi et étire-toi","Bois un verre d'eau, lentement","Regarde loin, par la fenêtre","Respire lentement 5 fois","Note ce que tu ressens, en une phrase"],"method":["Patch nicotinique","Gommes ou pastilles","Rendez-vous avec mon pharmacien","Rendez-vous avec mon médecin","Appeler Tabac info service (39 89)","Sans substitut, avec mon plan"],"veille":["Relire mon pourquoi","Jeter ou donner mon matériel","Préparer chewing-gums, eau et collations","Prévenir 2 personnes","Fixer mon heure de coucher","Choisir mon premier geste de remplacement"],"geste":["Chewing-gum","Cure-dent","Verre d'eau","Bâtonnet de cannelle","Balle antistress","Crayon dans les doigts"],"snacks":["Fruits","Carottes","Noix","Yaourt","Pommes","Tisane"],"timeline":[["20 minutes","La fréquence cardiaque et la tension commencent à redescendre."],["24 heures","Le monoxyde de carbone quitte progressivement le sang."],["2 à 3 jours","Le goût et l'odorat reviennent peu à peu."],["2 à 4 semaines","Beaucoup de personnes respirent plus facilement et toussent moins."],["1 à 3 mois","Le souffle et l'énergie s'améliorent souvent nettement."],["1 an","Le risque de maladie cardiaque diminue fortement par rapport à un fumeur."]]},"days":[["Ton pourquoi","Avant d'arrêter, sache pour quoi tu le fais : la santé, le souffle, l'argent, le sport, la liberté. Ce pourquoi sera ta réserve les jours difficiles.","Écris 3 raisons personnelles d'arrêter. Garde-les en note sur ton écran de verrouillage.","choose",{},{"q":"Qu'est-ce qui te pousse à changer aujourd'hui ?","o":[["Ma santé","Excellent moteur. Le corps commence à récupérer très tôt : chaque jour compte déjà, même si tu ne le sens pas encore."],["Mon argent","Chiffrer l'argent regagné est l'un des meilleurs rappels les jours difficiles. On le fera dans quelques jours."],["Mes proches","Faire ça pour les autres aide, mais garde aussi une raison rien que pour toi : c'est elle qui tient quand personne ne regarde."],["Je me sens dépassé(e)","C'est une raison valable. Tu n'as pas à tout régler aujourd'hui : un seul petit pas suffit pour commencer."]]},["10 à 20 secondes","En fumant, la nicotine atteint le cerveau en quelques secondes. C'est ce qui rend le réflexe « geste + récompense » si puissant.","Repère à quel moment le geste précède l'envie."]],["Ta consommation réelle","On sous-estime presque toujours. Savoir exactement combien tu consommes, c'est un point de départ réel. Pour la vape, compte aussi la quantité de nicotine.","Pendant 3 jours, note chaque cigarette ou chaque session de vape : l'heure, le lieu, ce qui se passe juste avant. Aujourd'hui, estime ta consommation habituelle.","calc",{},{"q":"Ton estimation de ta semaine dernière, elle est…","o":[["Plutôt juste","C'est rare : la plupart des gens sous-estiment. Vérifie quand même avec les vrais chiffres ce soir."],["Sûrement en dessous de la réalité","C'est le cas de presque tout le monde : le cerveau oublie les automatismes. Mesurer sans te juger, c'est tout ce qu'on te demande."],["Je n'ose pas regarder","Normal : voir le chiffre pique un peu. C'est pourtant ce qui permet de reprendre la main. Regarde-le comme un simple relevé."],["Je n'en ai aucune idée","Alors note pendant 3 jours, une ligne à chaque fois. Les automatismes se voient dès qu'on les écrit."]]},["La nicotine reste environ 2 heures","La nicotine met environ 2 heures à diminuer de moitié dans le sang : le manque revient par vagues tout au long de la journée.","Note l'heure de tes envies : elles reviennent en rythme."]],["Ce que ça t'apporte, ce que ça te coûte","La détente ressentie après une bouffée est souvent la fin du manque de nicotine. Le comprendre aide à voir le piège. Ça coûte aussi du souffle, de l'argent et du temps.","Fais deux colonnes : ce que ça t'apporte / ce que ça te coûte (argent, souffle, santé). Souligne ce qui pèse le plus.",null,{},{"q":"Qu'est-ce que ça t'apporte de fumer ou vapoter ?","o":[["Me détendre","La détente est réelle mais courte : elle soulage surtout le manque que l'habitude crée. Respiration lente, marche ou douche chaude donnent un calme plus durable."],["Ne plus penser à rien","C'est un vrai besoin : ton cerveau veut une pause. Une vraie pause (marche, étirements) repose mieux et ne laisse pas de culpabilité."],["Me sentir moins seul(e)","Besoin légitime. Un message ou un appel, même court, y répond mieux et plus longtemps."],["Du plaisir, tout simplement","Le plaisir compte. L'idée n'est pas de t'en priver mais de le retrouver ailleurs : dans quelques jours tu choisiras tes remplaçants."]]},["Le calme est un soulagement","La détente ressentie après une cigarette vient surtout du soulagement du manque que la nicotine a créé.","Note comment tu te sens 10 minutes après."]],["Tes déclencheurs","Café, pause, après le repas, soirée, alcool, stress, voiture : ce sont des déclencheurs. Quand tu les repères, tu les vois venir.","Note tes 5 moments de la journée où l'envie est la plus forte.","heat",{},{"q":"Quand l'envie est-elle la plus forte ?","o":[["Le soir, seul(e)","Fatigue et solitude : le soir, le cerveau freine moins bien. Prévois quelque chose de précis pour ces heures-là."],["Quand je m'ennuie","L'ennui est un déclencheur très fréquent. Il retombe en quelques minutes si on ne le fuit pas : prépare une action de 5 minutes."],["Quand je suis stressé(e)","Le stress donne envie d'un soulagement rapide. Un souffle plus long à l'expiration (4 s / 6 s) calme le corps en 2 minutes."],["Avec d'autres personnes","Le contexte social pèse beaucoup. Dire à une personne que tu changes suffit souvent à désamorcer."]]},["Le cerveau associe","Café, repas, alcool : le cerveau associe ces moments à la nicotine. Changer l'ordre ou le lieu défait l'association.","Bois ton café debout, dans une autre pièce."]],["Choisir ta méthode et ta date","Beaucoup de personnes arrêtent avec de l'aide : substituts nicotiniques (patchs, gommes), accompagnement d'un tabacologue, ton médecin. Demande conseil à ton pharmacien ou ton médecin, ou appelle Tabac info service (39 89).","Choisis ton jour d'arrêt, dans 3 jours. Parle à ton pharmacien ou ton médecin de ce qui peut t'aider.","toolbox",{"src":"method","min":1,"max":3,"t":"Choisis ta méthode","i":"Touche jusqu'à 3 aides qui te conviennent. Tu peux en parler à ton pharmacien ou au 39 89."},{"q":"Quelle barrière poses-tu en premier ?","o":[["Supprimer l'accès","Chaque étape en plus fait baisser le passage à l'acte : un obstacle de 20 secondes laisse souvent l'envie retomber."],["Changer de lieu ou d'horaire","Les habitudes sont liées à des lieux et des heures. Change l'un des deux et l'automatisme perd son déclencheur."],["Prévenir quelqu'un","Dire ton objectif à voix haute le rend plus réel et te donne un témoin bienveillant."],["Aucune, c'est trop dur","Prends la plus petite, une seule. Une barrière imparfaite vaut mieux qu'un plan parfait jamais appliqué."]]},["Les substituts aident","Patchs, gommes et pastilles augmentent nettement les chances d'arrêter, surtout avec un accompagnement. Demande à ton pharmacien.","Appelle Tabac info service : 39 89, gratuit."]],["Préparer le terrain","Tu mets toutes les chances de ton côté avant le jour J : pas de stock, pas de tentation facile, un plan pour les moments difficiles.","Prévois de jeter ou donner ton matériel le jour J. Nettoie ta voiture et ton appartement. Prépare chewing-gums, eau et collations.","checklist",{"key":"env","t":"Préparer le terrain"},{"q":"Quel plan « si… alors… » te ressemble ?","o":[["Si l'envie vient, je bois de l'eau et j'attends 10 minutes","Un délai court plus un geste simple : c'est très efficace. Les plans précis marchent bien mieux que les bonnes intentions."],["Si je m'ennuie, je sors 5 minutes","Bouger change l'état du corps et coupe l'automatisme. Même monter un escalier compte."],["Si je suis stressé(e), je respire 1 minute","Inspire 4 secondes, souffle 6 : l'expiration longue ralentit le cœur et calme le système nerveux."],["Si je craque, j'appelle quelqu'un","Parler casse l'isolement et la honte, qui poussent à recommencer."]]},["Plus de stock, moins de rechute","Se débarrasser du matériel et des stocks évite les rechutes impulsives : l'envie passe avant que tu n'aies le temps d'aller en acheter.","Jette ou donne tout ton matériel."]],["La veille du jour J","Dernière étape avant l'arrêt. Tu te prépares, tu te reposes, tu te donnes un cadre pour demain.","Relis ton pourquoi. Prévois demain : ce que tu feras pour les moments à risque, qui tu préviens, et ce que tu fais de ton matériel.",null,{},{"q":"Cette semaine, qu'est-ce qui t'a le plus surpris(e) ?","o":[["À quel point c'est automatique","Voir l'automatisme, c'est déjà la moitié du chemin : on ne peut changer que ce qu'on remarque."],["Les moments où l'envie arrive","Tu connais maintenant tes heures et tes lieux : tu peux les anticiper au lieu de les subir."],["Que ça passe quand j'attends","C'est l'info la plus utile : une envie qui passe n'est pas un ordre."],["Rien de spécial","Pas grave, c'est une semaine d'observation. Continue : les effets arrivent avec la pratique."]]},["Bien dormir avant le jour J","Dormir suffisamment avant l'arrêt aide à mieux gérer les premières envies : la fatigue amplifie le manque.","Couche-toi tôt ce soir."]],["Jour J : ta première journée sans","Les premiers jours sont souvent les plus intenses. Chaque envie passe. Bois de l'eau, bouge, évite l'alcool, et reste près de ton plan.","Touche « J'ai arrêté » dans le suivi pour lancer ton compteur. Utilise le bouton SOS à chaque envie. Va te coucher fier de ta journée.","wave",{"t":"Jour J : surfe sur l'envie"},{"q":"Quand l'envie arrive, que fais-tu d'habitude ?","o":[["Je cède tout de suite","Normal : céder soulage vite, et c'est ce qui apprend au cerveau à recommencer. Aujourd'hui, repousse seulement de 10 minutes."],["Je lutte de toutes mes forces","Lutter épuise. Observe l'envie comme une vague : elle monte, plafonne, redescend. Laisse-la passer sans la combattre."],["Je me distrais","Très bien : 10 minutes de distraction suffisent souvent. Prépare-en deux à l'avance, à portée de main."],["Je ne sais pas","Aujourd'hui, note l'heure et ce que tu ressens quand elle vient. Un schéma va apparaître."]]},["Premières heures","Dès les premières heures, la fréquence cardiaque et la tension redescendent. Le monoxyde de carbone baisse en quelques heures.","Bois un grand verre d'eau toutes les heures."]],["Comprendre le manque","Le manque de nicotine se traduit par de l'irritabilité, de la fatigue, des envies. Ça passe, souvent en quelques jours à quelques semaines. L'envie monte, atteint un pic, puis retombe.","Note chaque envie : l'heure, l'intensité de 1 à 10, ce qui l'a calmée.","myths",{"t":"Comprendre le manque"},{"q":"Peux-tu tenir 10 minutes avant de passer à l'acte ?","o":[["Oui, facilement","Alors fais-en une règle : la plupart des envies retombent avant 10 minutes."],["Oui, avec une distraction","Parfait. Prépare deux distractions : musique, verre d'eau, marche. Elles font la moitié du travail."],["Difficile","Commence par 2 minutes. Chaque envie traversée entraîne ton cerveau à tolérer l'inconfort."],["Impossible","Pas de souci : 1 minute compte déjà. Le bouton SOS te guide pendant 10 minutes, un souffle après l'autre."]]},["Le manque culmine tôt","Irritabilité et envies culminent souvent aux jours 2 à 3, puis diminuent sur 2 à 4 semaines.","Prévois des activités faciles pour ces jours."]],["Les 4 D","Quatre réflexes simples : Délai (attends 10 minutes), Distraction (change d'activité), Drink (bois de l'eau), Deep breath (respire lentement).","Applique les 4 D à chaque envie aujourd'hui. Note lesquels marchent le mieux pour toi.","pairs",{"t":"Les 4 D : associe chaque envie à son réflexe"},{"q":"Quand tu es tendu(e), ton souffle est plutôt…","o":[["Court et haut","Respirer haut met le corps en alerte. Allonge l'expiration : c'est le levier le plus rapide pour te calmer."],["Je le retiens parfois","Retenir son souffle augmente la tension. Souffle doucement par la bouche, comme dans une paille."],["Je n'y ai jamais fait attention","Pose une main sur le ventre : si elle ne bouge pas, ta respiration est haute. Essaie de la faire gonfler."],["Plutôt calme","Bien. Garde ce réflexe pour les moments d'envie, c'est là qu'il compte le plus."]]},["Une envie dure 3 à 5 minutes","Une envie de fumer dure généralement 3 à 5 minutes. Boire de l'eau et respirer aident à la traverser.","Applique les 4 D : délai, distraction, eau, respiration."]],["Tes routines","Café, pause, après le repas : ces moments étaient des habitudes. Tu peux garder le moment et changer le geste.","Change l'ordre ou le lieu de 2 routines (café debout, pause en marchant, brosse-toi les dents après le repas).","slot",{"t":"Change ta routine"},{"q":"Pour t'occuper 10 minutes, tu préfères…","o":[["Bouger","Le mouvement réduit les envies et améliore l'humeur en quelques minutes."],["Parler à quelqu'un","Une voix humaine apaise plus vite qu'un écran ou un produit."],["Faire quelque chose de mes mains","Cuisine, dessin, rangement : occuper les mains occupe aussi l'attention, l'envie perd de la place."],["Rien ne me tente","Normal au début : l'envie rend tout fade. Essaie quand même 3 minutes, l'envie baisse avant que l'activité ne devienne agréable."]]},["Les routines se défont","Le café, la pause, l'après-repas : garde le moment, change le geste. L'association se défait en quelques semaines.","Brosse-toi les dents juste après le repas."]],["Stress et humeur","L'irritabilité des premières semaines est temporaire. Si tu as du mal à gérer ton humeur, des pauses et du mouvement aident.","Prévois 3 pauses de 5 minutes aujourd'hui : étirements, fenêtre ouverte, marche.",null,{},{"q":"Quand tu es stressé(e), ton corps réagit surtout par…","o":[["De la tension (épaules, mâchoire)","Relâche : épaules vers le bas, mâchoire détendue, trois souffles lents."],["De la fatigue","La fatigue baisse le frein de la volonté. Une sieste de 15 à 20 minutes aide, sinon couche-toi plus tôt ce soir."],["De l'agitation","Marche rapide 5 minutes : elle dépense l'adrénaline en trop."],["Je ne sais pas","Scanne : tête, épaules, ventre, jambes. Où ça serre ? C'est là qu'il faut respirer."]]},["Le stress de base baisse","La nicotine ne réduit pas le stress en moyenne : après quelques semaines sans, beaucoup de personnes se sentent moins tendues.","Prévois 3 pauses de 5 minutes aujourd'hui."]],["Soirées et alcool","L'alcool et les soirées sont l'un des moments les plus risqués. Prévois ton plan avant de sortir.","Avant la prochaine soirée : décide de ce que tu bois, de ce que tu fais quand on te propose, et qui est au courant de ton arrêt.","planner",{"t":"Ta prochaine soirée, sans"},{"q":"Quelle idée te retient le plus ?","o":[["J'en ai besoin pour me détendre ou dormir","Ça détend sur l'instant mais entretient le manque ensuite. À terme, la détente et le sommeil naturels reviennent."],["Je gère, ce n'est pas un problème","Si tu es ici, c'est que tu veux plus de contrôle. Fais confiance à ça."],["Tout le monde le fait","Beaucoup le font, et beaucoup changent aussi. Tu n'es pas seul(e) dans les deux cas."],["Juste une fois ne compte pas","Chaque fois renforce le circuit de l'habitude. L'exception est souvent la porte d'entrée."]]},["L'alcool et la rechute","L'alcool baisse la vigilance et les freins : c'est l'un des premiers déclencheurs de rechute.","Choisis une boisson sans alcool pour ta prochaine soirée."]],["Bilan de la semaine 2","Tu as passé la première semaine sans. Chaque envie surmontée construit la nouvelle habitude.","Regarde ton compteur de jours et d'envies surmontées. Note le moment le plus dur et ce qui t'a aidé.",null,{},{"q":"Ce qui t'a le plus aidé(e) cette semaine ?","o":[["Attendre 10 minutes","Garde-le : c'est ton outil principal. Il marche d'autant mieux qu'il est automatique."],["Respirer","La respiration est toujours avec toi. Utilise-la avant que l'envie ne soit à son maximum."],["Éloigner ce qui donne accès","Bien joué : réduire l'accès est l'une des méthodes les plus solides."],["Rien de précis","Pas grave. Regarde le bilan : tu as peut-être tenu plus que tu ne le penses."]]},["La toux peut augmenter","Au début, la toux peut augmenter : les cils des bronches repoussent et nettoient les voies respiratoires. C'est un signe de récupération.","Bois chaud et respire lentement."]],["Remplacer le geste","Les mains et la bouche ont besoin d'occuper leur place. Trouve un geste de remplacement.","Choisis 3 remplacements (chewing-gum, cure-dent, eau, bâtonnet, balle antistress). Garde-les sur toi.",null,{},{"q":"Quel remplaçant te semble le plus réaliste ?","o":[["Un geste (eau, étirements)","Les petits gestes sont faciles à répéter. Garde-les à portée de main."],["Une activité courte (marche, jeu)","Dix minutes suffisent souvent. Choisis-en une que tu peux faire n'importe où."],["Une personne (appel, message)","Un lien humain est l'un des meilleurs remplaçants. Mets 2 prénoms dans tes favoris."],["Je n'en ai pas encore","Essaie les trois cette semaine. Tu verras vite lequel marche pour toi."]]},["Mains et bouche occupées","Le geste main-bouche est une partie de l'habitude. Un chewing-gum ou un cure-dent le remplace efficacement.","Garde ton remplaçant dans la poche."]],["Bouger","Le sport aide à gérer les envies et à retrouver du souffle. Pas besoin de sport intense : marcher compte.","Fais 20 minutes de marche ou d'activité aujourd'hui. Note comment tu te sens après.","move",{},{"q":"Ton niveau de mouvement dans une journée ?","o":[["Presque aucun","Commence par 5 minutes de marche : c'est déjà un effet mesurable sur l'humeur."],["Un peu","Ajoute 10 minutes à l'heure où l'envie est la plus forte."],["Régulier","Excellent. Place-le aux heures à risque : c'est là qu'il protège le plus."],["Beaucoup","Parfait. N'oublie pas le repos : il fait partie de la récupération."]]},["Le souffle revient","Après quelques semaines, la capacité respiratoire s'améliore et l'effort devient plus facile.","Monte un escalier et note ton souffle."]],["Appétit et poids","Après l'arrêt, l'appétit augmente souvent. Prévoir des collations saines évite de remplacer la cigarette par la nourriture.","Prépare des collations (fruits, carottes, noix). Bois de l'eau avant de manger.",null,{},{"q":"Le plus dur dans tes week-ends, c'est…","o":[["Le temps libre","Prévois deux activités par jour : le vide appelle l'habitude."],["Les amis","Propose un lieu ou une activité sans l'habitude, ou dis-le d'avance. Les vrais amis comprennent."],["Le soir tard","Fixe une heure limite de coucher : la fatigue baisse les défenses."],["Rien de particulier","Prévois quand même un plan B, au cas où."]]},["Appétit et métabolisme","L'arrêt peut augmenter l'appétit et ralentir un peu le métabolisme. Manger équilibré et bouger limite la prise de poids.","Prépare des collations : fruits, carottes, noix."]],["En parler à ton entourage","Dire que tu arrêtes t'engage et te soutient. Demande à ceux qui vapent ou fument de ne pas t'en proposer.","Préviens 2 personnes que tu arrêtes. Dis-leur ce dont tu as besoin.",null,{},{"q":"À qui pourrais-tu en parler ?","o":[["Un(e) ami(e)","Un ami de confiance suffit. Dis simplement : « j'essaie de changer, peux-tu me demander demain comment ça va ? »"],["Un proche de la famille","Choisis la personne la plus calme et la moins critique. Un message écrit peut être plus facile."],["Un professionnel ou une ligne d'aide","Excellente idée : Tabac info service (39 89) est là pour ça, gratuitement et sans jugement."],["Personne pour l'instant","C'est possible, et ce n'est pas grave. Une ligne d'aide (Tabac info service (39 89)) peut être ton premier interlocuteur."]]},["La caféine agit plus fort","Les fumeurs éliminent la caféine plus vite. Après l'arrêt, le même café agit plus fort : réduis un peu.","Prends un café de moins aujourd'hui."]],["Les pensées-pièges","« Juste une », « juste ce soir », « je contrôle ». Ces phrases sont normales. Les repérer leur enlève du pouvoir.","Écris 3 phrases que tu te dis avant de craquer. À côté de chacune, une réponse honnête et courte.","pieges",{},{"q":"Quelle pensée te fait le plus craquer ?","o":[["« Juste une fois »","C'est le piège le plus courant. Réponse : « si c'est juste une fois, je peux attendre demain »."],["« Je l'ai bien mérité »","Oui, et tu peux te récompenser autrement : repas, film, sortie. Sans la facture."],["« Je m'y mets demain »","Demain sera pareil. Réponse : « je commence par les 10 prochaines minutes »."],["« J'ai déjà craqué, tant pis »","Un faux pas n'efface pas les jours passés. Reprends dès la prochaine heure."]]},["Le cerveau négocie","Pour obtenir un soulagement rapide, le cerveau fabrique des excuses (« juste une »). Les repérer leur enlève du pouvoir.","Note ta pensée-piège préférée."]],["Te récompenser avec l'argent économisé","L'argent économisé est ton vrai bonus. Le voir grossir motive.","Calcule ce que tu économises par semaine. Choisis une récompense pour le premier mois.",null,{},{"q":"Quelle récompense te ferait vraiment plaisir ?","o":[["Un bon repas","Parfait : choisis le jour et le lieu à l'avance, une récompense prévue motive mieux qu'une récompense improvisée."],["Une sortie","Planifie-la dans ton agenda dès aujourd'hui : l'avoir devant soi aide à tenir."],["Un achat","Mets de côté la somme économisée dans une enveloppe : la voir grossir motive."],["Du repos","Le repos est une vraie récompense. Offre-toi une soirée sans obligation."]]},["L'argent regagné","Chaque semaine sans, c'est plusieurs dizaines d'euros en plus. Les voir s'accumuler renforce la motivation.","Mets la somme de côté dans une enveloppe."]],["Bilan de la semaine 3","Trois semaines de pratique. Regarde ce qui a changé : souffle, énergie, humeur, argent.","Écris 3 changements que tu constates, même petits.",null,{},{"q":"Ce qui a changé depuis le début ?","o":[["Mon sommeil","Un meilleur sommeil réduit l'impulsivité : c'est un cercle vertueux qui s'installe."],["Mon humeur","Chaque jour, le cerveau se rééquilibre un peu. L'humeur suit souvent avec un décalage."],["Mon argent","Note la somme : c'est un des gains les plus concrets."],["Pas encore grand-chose","Normal : les changements sont souvent lents au début. Continue, ils arrivent avec la régularité."]]},["Le goût revient","Goût et odorat reviennent souvent en quelques jours à quelques semaines.","Goûte un aliment que tu aimes, lentement."]],["Un dérapage n'est pas une rechute","Une bouffée ne veut pas dire que tout est perdu. Ce qui compte, c'est de t'arrêter là et de reprendre le fil.","Écris la phrase que tu te diras après un dérapage. Courte, bienveillante, qui te remet en route.","scenario",{},{"q":"Si tu craques ce soir, tu te diras…","o":[["« Je suis nul(le) »","La honte nourrit le cycle. Parle-toi comme à un ami : « ça arrive, je reprends »."],["« C'est une information »","Exactement. Note ce qui l'a déclenché et ajuste ton plan."],["« Autant tout lâcher »","C'est l'effet « tant pis », le vrai piège. Reprends au prochain repas, pas à la prochaine semaine."],["« Je préviens quelqu'un »","Excellent réflexe : ça casse l'isolement et la honte."]]},["Un faux pas, pas une chute","Une bouffée ne défait pas ce qui est acquis. Ce qui compte, c'est de t'arrêter là et de reprendre tout de suite.","Écris ta phrase de reprise."]],["Ton plan en cas de rechute","Prévoir le plan B enlève la peur. Qu'est-ce qui m'a fait craquer ? Qu'est-ce que je change ? Qui j'appelle ?","Rédige un plan en 3 points : ce que je fais dans l'heure, ce que j'analyse, ce que j'ajuste. Note le 39 89.","relapse",{},{"q":"En cas de rechute, ce qui t'aiderait le plus ?","o":[["Un message tout prêt","Écris-le maintenant, il sera là quand tu en auras besoin. Tu n'auras plus qu'à l'envoyer."],["Quelqu'un à appeler","Choisis la personne et enregistre son numéro en favori."],["Une règle simple","Par exemple : « je m'arrête là, je bois de l'eau, je reprends demain »."],["Je préfère ne pas y penser","C'est compréhensible, mais prévoir réduit la peur. Ça prend 2 minutes et tu seras plus serein(e)."]]},["Anticiper apaise","Prévoir ce qu'on fera en cas de craquage réduit la panique et l'effet « tant pis ».","Relis ton plan B ce soir."]],["Ce que ton corps récupère","Au fil des semaines, beaucoup de personnes retrouvent du souffle, du goût, de l'odorat et de l'énergie. Chaque jour sans compte.","Note 3 changements que tu constates dans ton corps depuis le jour J.","timeline",{},{"q":"Dans 6 mois, tu aimerais être quelqu'un qui…","o":[["Dort bien","Un objectif concret : les nuits s'améliorent souvent dès les premières semaines."],["Tient ses engagements","Chaque petit engagement tenu renforce la confiance en toi."],["A de l'énergie","L'énergie revient avec le sommeil, le mouvement et moins d'à-coups."],["Se sent libre","La liberté, c'est choisir. Chaque envie traversée est un choix de plus."]]},["Le corps récupère","Au fil des semaines, le risque cardiaque diminue progressivement, et beaucoup de personnes retrouvent souffle et énergie.","Note 3 changements dans ton corps."]],["Les moments à risque à venir","Vacances, soirées, périodes de stress : certains moments vont remettre l'envie en jeu. Les prévoir, c'est déjà y être préparé.","Liste les 3 prochains moments à risque des 4 semaines à venir et ce que tu feras à chaque fois.",null,{},{"q":"Ton prochain moment à risque, c'est…","o":[["Un week-end","Prévois deux activités par jour et une heure de coucher."],["Une fête ou un événement","Décide à l'avance ce que tu fais et à quelle heure tu pars."],["Une période de stress","Planifie des pauses et du mouvement. Le stress est un déclencheur majeur."],["Je ne sais pas","Regarde ton agenda des 2 semaines à venir : tu en verras un ou deux."]]},["Le contexte déclenche","Vacances, soirées, fêtes : certains moments ravivent l'envie. Les repérer permet de s'y préparer.","Note les 3 prochains moments à risque."]],["Mieux dormir","Le sommeil est souvent perturbé les premières semaines. Une routine de coucher aide.","Fixe une heure de coucher. Évite caféine et écrans 1 heure avant. Prévois une activité calme.","evening",{},{"q":"Tes nuits en ce moment ?","o":[["Courtes","Une nuit courte renforce l'envie et réduit le contrôle. Couche-toi 30 minutes plus tôt ce soir."],["Agitées","Écrans coupés 30 minutes avant, chambre fraîche (18-19 °C) et dîner léger aident."],["Correctes","Bien. Garde un horaire régulier : c'est ça qui consolide."],["Très bonnes","Parfait. Protège-les : c'est un de tes meilleurs alliés."]]},["Le sommeil se remet","Le sommeil peut être perturbé les premières semaines, puis il se régule.","Évite caféine et écrans 1 heure avant de dormir."]],["L'argent économisé","Cet argent est ton vrai gain. Le chiffrer le rend concret et motive.","Calcule : (euros dépensés par semaine) × 52. Écris ce que tu veux faire avec cette somme.",null,{},{"q":"Le temps ou l'argent récupéré, tu en feras…","o":[["Du repos","Le repos compte aussi. Planifie-le au lieu de le subir."],["Un projet","Choisis un petit projet de 30 minutes par jour : c'est ce qui remplit le vide."],["Du temps avec des proches","Les liens sont l'un des meilleurs soutiens pour tenir."],["Un plaisir ou de l'épargne","Mets une somme de côté chaque semaine : la voir grossir motive."]]},["L'argent économisé","Un paquet par jour, c'est de l'ordre de 4 000 € par an : de quoi financer un vrai projet.","Calcule ta somme annuelle et choisis ce que tu en fais."]],["Ton réseau d'aide","Si tu as du mal à tenir, ou si tu as repris, un tabacologue peut t'aider, gratuitement par téléphone. Ce n'est pas un échec.","Note le 39 89 (Tabac info service) et le nom de ton médecin ou pharmacien. Si tu vas mal, le 3114 répond 24h/24.",null,{},{"q":"Qui est ton premier appel en cas de coup dur ?","o":[["Un(e) ami(e)","Garde son numéro en favori. Dis-lui d'avance qu'il peut t'aider."],["Un proche de la famille","Préviens-le à l'avance : il saura quoi répondre quand ça arrivera."],["Un professionnel","Tabac info service (39 89) est joignable. Note le numéro dans ton téléphone."],["Je n'ai pas de nom","Alors Tabac info service (39 89) peut être ce nom. C'est gratuit, tu n'as pas à te justifier."]]},["L'aide fonctionne","L'accompagnement par un tabacologue augmente les chances de réussir. Le 39 89 est gratuit.","Note le 39 89 dans tes favoris."]],["Lettre à toi-même","Ce que tu as fait pendant 30 jours mérite d'être écrit. Cette lettre te servira les jours où tu auras oublié pourquoi c'était important.","Écris-toi une lettre pour dans 3 mois : ce que tu as appris, ce que tu veux avoir gardé, ce que tu te souhaites.","letter",{},{"q":"Pour toi dans 3 mois, le plus important à te rappeler ?","o":[["Ce que j'ai tenu","Écris-le : les chiffres sont des preuves quand le doute revient."],["Pourquoi j'ai commencé","Relis ton pourquoi du premier jour. Il est dans ton espace."],["Que ça passe","Oui : une envie passe toujours. C'est ta meilleure information."],["Que je mérite d'aller bien","C'est vrai. Écris-le comme si tu parlais à un ami."]]},["Écrire aide","Écrire ce qu'on ressent aide à réguler les émotions, c'est ce qu'on appelle l'écriture expressive.","Écris 5 minutes, sans te relire."]],["Et maintenant ?","30 jours, c'est un début, pas une fin. Garde 2 ou 3 règles qui ont marché, et refais le point une fois par mois. Ne reprends jamais « juste une ».","Choisis les 3 règles à garder. Plante un rappel mensuel dans ton agenda.","final",{},{"q":"Pour la suite, tu comptes…","o":[["Continuer chaque jour","Excellent. La régularité fait plus que l'intensité."],["Faire un point par semaine","Très bien : un point de 10 minutes le dimanche suffit."],["Appeler en cas de doute","Tabac info service (39 89) est là. Un coup de fil évite souvent une rechute."],["Je ne sais pas encore","Pas de pression. Garde juste la règle : au moindre doute, 10 minutes d'attente et un souffle lent."]]},["Garder le cap","Les rechutes sont fréquentes dans tout arrêt ; ce qui compte, c'est de reprendre vite. Aucune bouffée, jamais.","Fixe un rappel mensuel pour faire le point."]]]},"cannabis":{"kit":{"raisons":["Mieux dormir","Retrouver ma motivation","Améliorer ma mémoire","Économiser mon argent","Avoir plus d'énergie","Mieux gérer mes émotions","Être plus présent","Reprendre le sport","Avancer sur mes projets","Respirer mieux"],"pros":["Me détendre","M'endormir","Être avec des amis","Oublier mes soucis","Mon rituel du soir","Me sentir moins anxieux"],"cons":["Je manque de motivation","J'oublie des choses","Ça coûte cher","Je dors mal sans","Je repousse mes projets","Je suis moins énergique","Je m'isole parfois","Je me sens dépendant"],"calc":{"q":"Combien dépenses-tu par semaine ?","unit":"€ par semaine","min":0,"max":200,"step":5,"def":40,"mult":52,"out":"€ par an","div":0,"divLabel":"","eq":[500,"week-ends en voyage"],"gain":"économisés chaque année"},"env":["Jeter ou donner mon stock et mon matériel","Supprimer les contacts et les conversations","Éviter les lieux où j'ai l'habitude de consommer","Prévoir une activité pour mon rituel du soir","Prévenir un ami de ma décision","Ne rien garder « pour plus tard »"],"triggers":["En rentrant le soir","Avec des amis","L'ennui","Le stress","Avant de dormir","Le week-end","Après le travail","Quand je suis seul","En écoutant de la musique","Quand je suis triste"],"actions":["Prendre une douche","Faire une tisane","Sortir marcher","Appeler un ami","Faire du sport","Respirer lentement","Regarder une série","Cuisiner","Écouter de la musique","Écrire ce que je ressens"],"distract":["Un ami propose un joint","L'odeur dans le couloir","Le soir en rentrant","Un message « tu passes ? »","Un morceau qui rappelle des soirées","Ennui du dimanche"],"myths":[["Le cannabis aide durablement à dormir.",false,"Il peut endormir, mais il fragilise souvent le sommeil. Arrêter perturbe d'abord les nuits, puis ça s'améliore."],["Une envie forte dure toute la soirée.",false,"Elle monte, atteint un pic puis retombe, surtout si tu fais autre chose."],["Les premiers jours sans, on peut être irritable et dormir mal.",true,"C'est fréquent et ça passe, souvent en quelques jours à quelques semaines."],["Mélanger avec du tabac n'a pas d'importance.",false,"Le tabac ajoute la dépendance à la nicotine. Les deux se travaillent ensemble."],["Changer le rituel du soir aide à tenir.",true,"Garde le moment, change le geste : douche, tisane, série, sport."],["Un dérapage = tout est à refaire.",false,"Un dérapage est une information. Tu reprends le fil."]],"pairs":[["En rentrant le soir","Prendre une douche"],["Avec des amis","Choisir un lieu sans consommation"],["Avant de dormir","Tisane et respiration"],["L'ennui","Sortir marcher"],["Le stress","Respirer lentement"]],"pieges":[["Juste pour dormir.",true,"À long terme, ça fragilise le sommeil. Une routine du soir marche mieux."],["C'est naturel, ce n'est pas grave.",true,"Naturel ne veut pas dire sans effet, surtout en cas d'usage régulier."],["J'arrête demain.",true,"« Demain » repousse. Tu peux commencer ce soir."],["Je peux changer mon rituel du soir.",false,"Oui : douche, tisane, série, sport."],["Je peux parler à une consultation jeunes consommateurs.",false,"Gratuit et confidentiel. Appelle Drogues info service : 0 800 23 13 13."],["Juste ce week-end.",true,"Les week-ends sont des moments à risque. Prévois un plan."],["Un dérapage n'est pas un échec.",false,"Exact. Tu reprends le fil sans te punir."],["Je gère, je consomme moins que les autres.",true,"Te comparer ne change pas ce que ça te coûte à toi."]],"scenarios":[{"q":"Il est 22h, tu rentres du travail. Ton rituel du soir te démange.","c":[["Je prends une douche, je fais une tisane et je mets une série",2,"Tu gardes le moment, tu changes le geste. C'est la clé."],["Je me dis que c'est la dernière fois",0,"« La dernière fois » revient presque toujours."],["Je sors une demi-heure",1,"Bien pour casser l'envie. Prévois aussi quoi faire en rentrant."]]},{"q":"Un ami t'envoie « tu passes ? Y a de quoi faire un truc ».","c":[["J'y vais, je ne consommerai pas",1,"Risqué. Mieux vaut proposer un autre plan."],["Je lui dis que j'arrête et je propose de se voir demain autrement",2,"Clair et sans conflit. Les bons amis comprennent."],["Je ne réponds pas",1,"Ça protège, mais te prive du soutien d'un ami. Dis-lui."]]},{"q":"Jour 4 sans : tu dors mal et tu es irritable.","c":[["Je consomme pour dormir cette nuit",0,"Tu vas relancer les premiers jours inconfortables. Tiens bon."],["Je lis, je fais de la respiration et je prévois une routine du soir",2,"Les nuits s'améliorent souvent en quelques jours à quelques semaines."],["J'en parle à mon médecin",2,"Excellent : si les symptômes sont difficiles, c'est une bonne idée."]]}],"relapse":{"heure":["Je m'arrête là et je jette ce qu'il reste","Je sors prendre l'air et je respire","Je note ce qui s'est passé"],"ajuster":["Je change mon rituel du soir","J'évite certains amis ou lieux","Je consulte une CJC ou mon médecin"],"prevenir":["Un ami proche","Mon frère ou ma sœur","Mon conjoint ou ma conjointe","Un professionnel","Personne, je gère seul"]},"events":["Soirée entre amis","Rentrée du travail","Week-end seul","Concert ou festival","Période de stress","Vacances"],"messages":["J'essaie d'arrêter le cannabis. Peux-tu ne pas m'en proposer ces prochaines semaines ?","Je change mon rituel du soir. Tu peux m'aider à tenir ce week-end ?"],"rules":["Garder mes barrières en place","Utiliser le bouton SOS à chaque envie","Prévoir mes moments à risque","Parler à quelqu'un quand c'est dur","Bouger régulièrement","Bien dormir","Me récompenser autrement","Faire un point chaque mois","Changer le rituel du soir","Ne rien garder à la maison"],"identite":["qui décide de son temps","qui tient ses engagements","qui prend soin de lui","qui sait demander de l'aide","qui ose dire non","qui se réveille avec de l'énergie","qui choisit ses soirées","qui protège son argent","qui est présent avec ses proches","qui avance sur ses projets","qui se respecte","qui ne se juge plus durement"],"rewards":["Un bon repas au restaurant","Une sortie au cinéma","Un week-end dans la nature","Un vêtement qui me plaît","Un moment avec un ami","Une journée sans rien faire","Un livre ou un jeu","Un hammam ou un massage","Un petit voyage","Un cadeau pour quelqu'un"],"evening":["Fixer l'heure du coucher","Téléphone hors du lit","Écrans éteints 30 minutes avant","Douche ou tisane","Préparer la journée de demain","Respirer 2 minutes"],"people":["Un ami proche","Mon frère ou ma sœur","Mon conjoint ou ma conjointe","Un parent","Un collègue de confiance","Mon médecin"],"pause":["Lève-toi et étire-toi","Bois un verre d'eau, lentement","Regarde loin, par la fenêtre","Respire lentement 5 fois","Note ce que tu ressens, en une phrase"],"timeline":[["1 à 3 jours","Les premières envies, de l'irritabilité, une nuit plus agitée : c'est fréquent."],["1 à 2 semaines","Rêves plus intenses, sommeil perturbé, humeur en dents de scie : ça se stabilise souvent."],["2 à 4 semaines","Beaucoup de personnes retrouvent des nuits plus profondes et plus d'énergie."],["1 à 2 mois","La concentration et la motivation reviennent souvent peu à peu."],["Au fil des mois","Ton argent, ton temps et ton énergie sont à toi."]]},"days":[["Ton pourquoi","Avant de changer quoi que ce soit, il faut savoir pour quoi tu le fais : le sommeil, la mémoire, la motivation, l'argent, la liberté. Ce pourquoi sera ta réserve les jours difficiles : il doit venir de toi.","Écris 3 raisons personnelles de réduire ou d'arrêter. Garde-les en note sur ton écran de verrouillage.","choose",{},{"q":"Qu'est-ce qui te pousse à changer aujourd'hui ?","o":[["Ma santé","Excellent moteur. Le corps commence à récupérer très tôt : chaque jour compte déjà, même si tu ne le sens pas encore."],["Mon argent","Chiffrer l'argent regagné est l'un des meilleurs rappels les jours difficiles. On le fera dans quelques jours."],["Mes proches","Faire ça pour les autres aide, mais garde aussi une raison rien que pour toi : c'est elle qui tient quand personne ne regarde."],["Je me sens dépassé(e)","C'est une raison valable. Tu n'as pas à tout régler aujourd'hui : un seul petit pas suffit pour commencer."]]},["Le système endocannabinoïde","Le THC agit sur des récepteurs du cerveau qui régulent l'humeur, le sommeil et l'appétit. En réduisant, ce système se rééquilibre progressivement.","Note ton humeur et ton sommeil ce soir."]],["Ta consommation réelle","On sous-estime presque toujours ce qu'on consomme et ce que ça coûte. Regarder le chiffre sans te juger, c'est le vrai premier pas : on ne règle pas ce qu'on ne regarde pas.","Note pendant 3 jours : combien, à quelle heure, où, avec qui, et ce que tu ressentais juste avant.","calc",{},{"q":"Ton estimation de ta semaine dernière, elle est…","o":[["Plutôt juste","C'est rare : la plupart des gens sous-estiment. Vérifie quand même avec les vrais chiffres ce soir."],["Sûrement en dessous de la réalité","C'est le cas de presque tout le monde : le cerveau oublie les automatismes. Mesurer sans te juger, c'est tout ce qu'on te demande."],["Je n'ose pas regarder","Normal : voir le chiffre pique un peu. C'est pourtant ce qui permet de reprendre la main. Regarde-le comme un simple relevé."],["Je n'en ai aucune idée","Alors note pendant 3 jours, une ligne à chaque fois. Les automatismes se voient dès qu'on les écrit."]]},["Le THC se stocke","Le THC se stocke dans les graisses et s'élimine lentement, sur des jours à des semaines. Les effets sur le sommeil peuvent mettre du temps à partir.","Sois patient avec toi : les nuits s'améliorent par étapes."]],["Ce que ça t'apporte, ce que ça te coûte","Le cannabis te rend service : il détend, il aide à décrocher, il rapproche des amis. Le reconnaître permet de trouver d'autres façons d'obtenir la même chose. Ça coûte aussi du sommeil, de la motivation, de l'argent.","Fais deux colonnes sur papier : ce que ça t'apporte / ce que ça te coûte. Entoure ce que tu pourrais obtenir autrement.",null,{},{"q":"Qu'est-ce que ça t'apporte de fumer ?","o":[["Me détendre","La détente est réelle mais courte : elle soulage surtout le manque que l'habitude crée. Respiration lente, marche ou douche chaude donnent un calme plus durable."],["Ne plus penser à rien","C'est un vrai besoin : ton cerveau veut une pause. Une vraie pause (marche, étirements) repose mieux et ne laisse pas de culpabilité."],["Me sentir moins seul(e)","Besoin légitime. Un message ou un appel, même court, y répond mieux et plus longtemps."],["Du plaisir, tout simplement","Le plaisir compte. L'idée n'est pas de t'en priver mais de le retrouver ailleurs : dans quelques jours tu choisiras tes remplaçants."]]},["Détente ou habitude ?","Beaucoup décrivent un calme réel, mais le cerveau s'habitue : à terme, le calme sans produit devient plus difficile à atteindre.","Note ce que tu ressens sans, 30 minutes après le moment habituel."]],["Tes déclencheurs","Un déclencheur, c'est ce qui te donne envie sans que tu y penses : rentrer chez toi, un ami, l'ennui, un morceau de musique, la fin de journée. Quand tu les repères, tu les vois venir.","À chaque envie aujourd'hui, note l'heure, le lieu et ce que tu ressens juste avant. Vise 5 notes.","heat",{},{"q":"Quand l'envie est-elle la plus forte ?","o":[["Le soir, seul(e)","Fatigue et solitude : le soir, le cerveau freine moins bien. Prévois quelque chose de précis pour ces heures-là."],["Quand je m'ennuie","L'ennui est un déclencheur très fréquent. Il retombe en quelques minutes si on ne le fuit pas : prépare une action de 5 minutes."],["Quand je suis stressé(e)","Le stress donne envie d'un soulagement rapide. Un souffle plus long à l'expiration (4 s / 6 s) calme le corps en 2 minutes."],["Avec d'autres personnes","Le contexte social pèse beaucoup. Dire à une personne que tu changes suffit souvent à désamorcer."]]},["Le cerveau associe","Le soir, le cerveau associe un lieu, un geste et un effet. Les repérer, c'est savoir quand l'envie va arriver.","Repère l'heure et le lieu de ta plus grosse envie."]],["Préparer ta méthode et ta date","Tu mets toutes les chances de ton côté : un jour d'arrêt, un environnement qui t'aide, quelqu'un qui le sait. Rien ne se garde « pour plus tard » : ce qui est à portée de main finit par être utilisé.","Choisis ton jour d'arrêt. Jette ou donne ton stock et ton matériel, supprime les contacts et conversations liés.",null,{},{"q":"Quelle barrière poses-tu en premier ?","o":[["Supprimer l'accès","Chaque étape en plus fait baisser le passage à l'acte : un obstacle de 20 secondes laisse souvent l'envie retomber."],["Changer de lieu ou d'horaire","Les habitudes sont liées à des lieux et des heures. Change l'un des deux et l'automatisme perd son déclencheur."],["Prévenir quelqu'un","Dire ton objectif à voix haute le rend plus réel et te donne un témoin bienveillant."],["Aucune, c'est trop dur","Prends la plus petite, une seule. Une barrière imparfaite vaut mieux qu'un plan parfait jamais appliqué."]]},["Rien à portée de main","Ce qui est chez toi finit par être utilisé. Retirer le stock et le matériel supprime la décision impulsive.","Jette ou donne tout ce que tu gardes."]],["Le plan « si… alors… »","Un plan précis marche mieux qu'une bonne intention. Tu décides à l'avance quoi faire quand le déclencheur arrive, pour ne pas avoir à choisir sous l'impulsion.","Écris 3 phrases : « Si je rentre le soir / si un ami propose / si je n'arrive pas à dormir, alors je… » avec une action concrète.","pairs",{},{"q":"Quel plan « si… alors… » te ressemble ?","o":[["Si l'envie vient, je bois de l'eau et j'attends 10 minutes","Un délai court plus un geste simple : c'est très efficace. Les plans précis marchent bien mieux que les bonnes intentions."],["Si je m'ennuie, je sors 5 minutes","Bouger change l'état du corps et coupe l'automatisme. Même monter un escalier compte."],["Si je suis stressé(e), je respire 1 minute","Inspire 4 secondes, souffle 6 : l'expiration longue ralentit le cœur et calme le système nerveux."],["Si je craque, j'appelle quelqu'un","Parler casse l'isolement et la honte, qui poussent à recommencer."]]},["L'expiration longue","Souffler plus longtemps qu'on inspire active le frein du système nerveux et aide à s'endormir et à se calmer.","Inspire 4 s, souffle 6 s, cinq fois."]],["Bilan de la semaine 1","Une semaine pour comprendre. Tu sais maintenant ce que tu consommes, ce que ça t'apporte et quand ça se déclenche. C'est suffisant pour attaquer la suite.","Relis tes notes. Complète : « Ce que j'ai appris sur moi cette semaine, c'est… ». Choisis un moment à protéger la semaine prochaine.",null,{},{"q":"Cette semaine, qu'est-ce qui t'a le plus surpris(e) ?","o":[["À quel point c'est automatique","Voir l'automatisme, c'est déjà la moitié du chemin : on ne peut changer que ce qu'on remarque."],["Les moments où l'envie arrive","Tu connais maintenant tes heures et tes lieux : tu peux les anticiper au lieu de les subir."],["Que ça passe quand j'attends","C'est l'info la plus utile : une envie qui passe n'est pas un ordre."],["Rien de spécial","Pas grave, c'est une semaine d'observation. Continue : les effets arrivent avec la pratique."]]},["Sommeil et humeur","Un bon sommeil stabilise l'humeur et réduit les envies. Une heure de coucher régulière aide autant que n'importe quel truc.","Fixe une heure de coucher pour la semaine."]],["Comprendre l'envie","L'envie monte, atteint un pic, puis retombe, même si tu ne fais rien. Savoir que ça passe change tout : une envie n'est pas un ordre.","Quand l'envie arrive, attends 10 minutes avant d'agir. Observe : où la sens-tu dans le corps ? Que devient-elle ?","wave",{},{"q":"Quand l'envie arrive, que fais-tu d'habitude ?","o":[["Je cède tout de suite","Normal : céder soulage vite, et c'est ce qui apprend au cerveau à recommencer. Aujourd'hui, repousse seulement de 10 minutes."],["Je lutte de toutes mes forces","Lutter épuise. Observe l'envie comme une vague : elle monte, plafonne, redescend. Laisse-la passer sans la combattre."],["Je me distrais","Très bien : 10 minutes de distraction suffisent souvent. Prépare-en deux à l'avance, à portée de main."],["Je ne sais pas","Aujourd'hui, note l'heure et ce que tu ressens quand elle vient. Un schéma va apparaître."]]},["Une vague","Une envie monte, plafonne et retombe en quelques minutes, même si on ne fait rien.","Chronomètre ta prochaine envie."]],["Tenir 10 minutes","Quand une envie arrive, ne te dis pas « jamais », dis-toi « dans 10 minutes ». Souvent, elle est partie avant. Les premiers jours, on peut être irritable et dormir mal : c'est fréquent, et ça passe.","Utilise le bouton SOS à chaque envie aujourd'hui. Compte combien sont passées.","hold",{},{"q":"Peux-tu tenir 10 minutes avant de passer à l'acte ?","o":[["Oui, facilement","Alors fais-en une règle : la plupart des envies retombent avant 10 minutes."],["Oui, avec une distraction","Parfait. Prépare deux distractions : musique, verre d'eau, marche. Elles font la moitié du travail."],["Difficile","Commence par 2 minutes. Chaque envie traversée entraîne ton cerveau à tolérer l'inconfort."],["Impossible","Pas de souci : 1 minute compte déjà. Le bouton SOS te guide pendant 10 minutes, un souffle après l'autre."]]},["Les premiers jours","Irritabilité, nuits agitées, appétit en baisse : c'est fréquent la première semaine, puis ça s'atténue sur 2 à 4 semaines.","Prévois une soirée facile, sans pression."]],["Respirer pour retomber","Une respiration lente, avec un souffle plus long que l'inspiration, aide à calmer le système nerveux en quelques minutes. C'est un outil que tu emportes partout.","Fais 2 minutes de respiration (inspire 4 secondes, souffle 6), deux fois dans la journée, dont une au moment où tu consommais.","breathe",{},{"q":"Quand tu es tendu(e), ton souffle est plutôt…","o":[["Court et haut","Respirer haut met le corps en alerte. Allonge l'expiration : c'est le levier le plus rapide pour te calmer."],["Je le retiens parfois","Retenir son souffle augmente la tension. Souffle doucement par la bouche, comme dans une paille."],["Je n'y ai jamais fait attention","Pose une main sur le ventre : si elle ne bouge pas, ta respiration est haute. Essaie de la faire gonfler."],["Plutôt calme","Bien. Garde ce réflexe pour les moments d'envie, c'est là qu'il compte le plus."]]},["Le nerf vague","Respirer lentement stimule le nerf vague, qui ralentit le cœur et apaise.","Deux minutes de respiration, deux fois aujourd'hui."]],["Le rituel du soir","Souvent, ce n'est pas le produit qui manque, c'est le moment : la pause en rentrant, le geste, le canapé. Tu peux garder le moment et changer le geste.","Choisis un nouveau rituel pour ce soir : douche chaude, tisane, série, cuisine, musique. Prépare ce qu'il te faut avant de rentrer.","slot",{},{"q":"Pour t'occuper 10 minutes, tu préfères…","o":[["Bouger","Le mouvement réduit les envies et améliore l'humeur en quelques minutes."],["Parler à quelqu'un","Une voix humaine apaise plus vite qu'un écran ou un produit."],["Faire quelque chose de mes mains","Cuisine, dessin, rangement : occuper les mains occupe aussi l'attention, l'envie perd de la place."],["Rien ne me tente","Normal au début : l'envie rend tout fade. Essaie quand même 3 minutes, l'envie baisse avant que l'activité ne devienne agréable."]]},["Le sommeil paradoxal revient","Le cannabis réduit le sommeil paradoxal. À l'arrêt, les rêves reviennent souvent plus intenses : c'est un signe de rééquilibrage.","Note un rêve au réveil, sans t'inquiéter."]],["Stress et anxiété","On consomme davantage quand on est stressé ou anxieux : le corps cherche une pause. Si tu t'accordes de vraies pauses à ces moments, le produit devient moins nécessaire.","Prévois 3 pauses de 5 minutes aujourd'hui : étirements, fenêtre ouverte, verre d'eau, marche. Note comment tu te sens après.",null,{},{"q":"Quand tu es stressé(e), ton corps réagit surtout par…","o":[["De la tension (épaules, mâchoire)","Relâche : épaules vers le bas, mâchoire détendue, trois souffles lents."],["De la fatigue","La fatigue baisse le frein de la volonté. Une sieste de 15 à 20 minutes aide, sinon couche-toi plus tôt ce soir."],["De l'agitation","Marche rapide 5 minutes : elle dépense l'adrénaline en trop."],["Je ne sais pas","Scanne : tête, épaules, ventre, jambes. Où ça serre ? C'est là qu'il faut respirer."]]},["Le stress et le corps","Le stress élève le cortisol et pousse vers un soulagement rapide. Marcher 10 minutes le fait redescendre.","Marche 10 minutes en rentrant."]],["Idées reçues sur le cannabis","« Ça aide à dormir », « c'est naturel », « je gère ». Certaines idées reçues retiennent au même endroit. Les regarder d'un œil honnête enlève du pouvoir à la routine.","Écris l'idée reçue qui te parle le plus et ce que tu en penses maintenant.","myths",{},{"q":"Quelle idée te retient le plus ?","o":[["J'en ai besoin pour me détendre ou dormir","Ça détend sur l'instant mais entretient le manque ensuite. À terme, la détente et le sommeil naturels reviennent."],["Je gère, ce n'est pas un problème","Si tu es ici, c'est que tu veux plus de contrôle. Fais confiance à ça."],["Tout le monde le fait","Beaucoup le font, et beaucoup changent aussi. Tu n'es pas seul(e) dans les deux cas."],["Juste une fois ne compte pas","Chaque fois renforce le circuit de l'habitude. L'exception est souvent la porte d'entrée."]]},["La mémoire revient","Après quelques semaines, beaucoup de personnes retrouvent une meilleure mémoire de travail et plus de concentration.","Note un détail dont tu te souviens mieux."]],["Bilan de la semaine 2","Tu as appris à voir l'envie venir, à l'attendre et à changer le rituel. Chaque jour compte, même imparfait.","Regarde ton compteur de jours sans et d'envies surmontées. Note le moment le plus dur et ce qui t'a aidé.",null,{},{"q":"Ce qui t'a le plus aidé(e) cette semaine ?","o":[["Attendre 10 minutes","Garde-le : c'est ton outil principal. Il marche d'autant mieux qu'il est automatique."],["Respirer","La respiration est toujours avec toi. Utilise-la avant que l'envie ne soit à son maximum."],["Éloigner ce qui donne accès","Bien joué : réduire l'accès est l'une des méthodes les plus solides."],["Rien de précis","Pas grave. Regarde le bilan : tu as peut-être tenu plus que tu ne le penses."]]},["L'anxiété peut baisser","Une consommation régulière peut entretenir l'anxiété ; chez beaucoup, elle diminue après quelques semaines sans.","Note ton niveau d'anxiété de 1 à 10."]],["Remplacer, pas seulement enlever","Quand on enlève une habitude sans rien mettre à la place, le vide la rappelle. Construis ta boîte à outils : des actions simples que tu peux faire à la place.","Choisis 3 activités de remplacement et garde-les dans une note. Fais-en une aujourd'hui, même 10 minutes.",null,{},{"q":"Quel remplaçant te semble le plus réaliste ?","o":[["Un geste (eau, étirements)","Les petits gestes sont faciles à répéter. Garde-les à portée de main."],["Une activité courte (marche, jeu)","Dix minutes suffisent souvent. Choisis-en une que tu peux faire n'importe où."],["Une personne (appel, message)","Un lien humain est l'un des meilleurs remplaçants. Mets 2 prénoms dans tes favoris."],["Je n'en ai pas encore","Essaie les trois cette semaine. Tu verras vite lequel marche pour toi."]]},["Un rituel sans produit","Tisane chaude, douche, lumière tamisée : ces gestes déclenchent la détente physiologique, sans produit.","Prépare ta tisane avant de rentrer."]],["Bouger","Le mouvement change l'humeur, aide au sommeil et occupe les moments à risque. Pas besoin de sport intense : marcher compte.","Fais 20 minutes d'activité physique aujourd'hui, de préférence à l'heure où tu consommais.","move",{},{"q":"Ton niveau de mouvement dans une journée ?","o":[["Presque aucun","Commence par 5 minutes de marche : c'est déjà un effet mesurable sur l'humeur."],["Un peu","Ajoute 10 minutes à l'heure où l'envie est la plus forte."],["Régulier","Excellent. Place-le aux heures à risque : c'est là qu'il protège le plus."],["Beaucoup","Parfait. N'oublie pas le repos : il fait partie de la récupération."]]},["Le sport aide le sommeil","L'exercice régulier améliore la profondeur du sommeil, à condition de ne pas s'y mettre juste avant de dormir.","20 minutes de marche rapide, en fin d'après-midi."]],["Soirées et week-ends","Les soirées entre amis et les week-ends sont des moments à risque. Un plan évite de se retrouver coincé.","Regarde les 2 prochains événements. Décide à l'avance ce que tu feras, avec qui, et ce que tu diras si on te propose.",null,{},{"q":"Le plus dur dans tes week-ends, c'est…","o":[["Le temps libre","Prévois deux activités par jour : le vide appelle l'habitude."],["Les amis","Propose un lieu ou une activité sans l'habitude, ou dis-le d'avance. Les vrais amis comprennent."],["Le soir tard","Fixe une heure limite de coucher : la fatigue baisse les défenses."],["Rien de particulier","Prévois quand même un plan B, au cas où."]]},["Seul(e) et fatigué(e)","Fatigue, solitude et soirée libre : la combinaison la plus à risque. Il suffit d'en retirer un pour baisser le risque.","Prévois un appel ou une sortie ce soir."]],["En parler à quelqu'un","Garder ça pour soi entretient la honte. Parler à un proche de confiance, ou à Drogues info service (0 800 23 13 13, gratuit et anonyme), allège.","Choisis une personne de confiance et dis-lui que tu veux réduire ou arrêter. Dis-lui ce dont tu as besoin.",null,{},{"q":"À qui pourrais-tu en parler ?","o":[["Un(e) ami(e)","Un ami de confiance suffit. Dis simplement : « j'essaie de changer, peux-tu me demander demain comment ça va ? »"],["Un proche de la famille","Choisis la personne la plus calme et la moins critique. Un message écrit peut être plus facile."],["Un professionnel ou une ligne d'aide","Excellente idée : Drogues info service (0 800 23 13 13) est là pour ça, gratuitement et sans jugement."],["Personne pour l'instant","C'est possible, et ce n'est pas grave. Une ligne d'aide (Drogues info service (0 800 23 13 13)) peut être ton premier interlocuteur."]]},["Le soutien aide","Parler à quelqu'un qui comprend réduit la honte et le stress, deux moteurs de l'envie.","Parle à une personne de confiance."]],["Les pensées-pièges","« Juste pour dormir », « c'est naturel », « demain j'arrête ». Ces phrases sont normales. Les repérer leur enlève du pouvoir.","Écris 3 phrases que tu te dis avant de consommer. À côté de chacune, une réponse honnête et courte.","pieges",{},{"q":"Quelle pensée te fait le plus craquer ?","o":[["« Juste une fois »","C'est le piège le plus courant. Réponse : « si c'est juste une fois, je peux attendre demain »."],["« Je l'ai bien mérité »","Oui, et tu peux te récompenser autrement : repas, film, sortie. Sans la facture."],["« Je m'y mets demain »","Demain sera pareil. Réponse : « je commence par les 10 prochaines minutes »."],["« J'ai déjà craqué, tant pis »","Un faux pas n'efface pas les jours passés. Reprends dès la prochaine heure."]]},["Le cerveau négocie","Pour obtenir un soulagement rapide, le cerveau fabrique des excuses (« juste pour dormir »). Les repérer leur enlève du pouvoir.","Note ta pensée-piège préférée."]],["Te récompenser autrement","Ton cerveau aime les petites récompenses. Tu peux en garder sans consommer : un bon repas, un loisir, une sortie avec l'argent économisé.","Choisis une récompense pour chaque semaine tenue. Calcule ce que ça coûte et compare avec ce que tu aurais dépensé.",null,{},{"q":"Quelle récompense te ferait vraiment plaisir ?","o":[["Un bon repas","Parfait : choisis le jour et le lieu à l'avance, une récompense prévue motive mieux qu'une récompense improvisée."],["Une sortie","Planifie-la dans ton agenda dès aujourd'hui : l'avoir devant soi aide à tenir."],["Un achat","Mets de côté la somme économisée dans une enveloppe : la voir grossir motive."],["Du repos","Le repos est une vraie récompense. Offre-toi une soirée sans obligation."]]},["La récompense prévue","Une récompense choisie à l'avance renforce un nouveau comportement mieux qu'une récompense improvisée.","Choisis ta récompense de la semaine."]],["Bilan de la semaine 3","Trois semaines de pratique. Regarde ce qui a changé : sommeil, énergie, humeur, argent, motivation.","Écris 3 changements que tu constates, même petits.",null,{},{"q":"Ce qui a changé depuis le début ?","o":[["Mon sommeil","Un meilleur sommeil réduit l'impulsivité : c'est un cercle vertueux qui s'installe."],["Mon humeur","Chaque jour, le cerveau se rééquilibre un peu. L'humeur suit souvent avec un décalage."],["Mon argent","Note la somme : c'est un des gains les plus concrets."],["Pas encore grand-chose","Normal : les changements sont souvent lents au début. Continue, ils arrivent avec la régularité."]]},["La motivation revient","Avec le temps, le système de récompense se rééquilibre et la motivation revient, souvent avec un décalage.","Fais une petite tâche que tu repoussais."]],["Un dérapage n'est pas une rechute","Si tu consommes, ce n'est pas la fin. C'est une information : qu'est-ce qui l'a déclenché ? Reprends le fil dès que possible, sans te punir.","Écris ce que tu feras après un dérapage : t'arrêter là, noter le déclencheur, le dire à quelqu'un.","scenario",{},{"q":"Si tu craques ce soir, tu te diras…","o":[["« Je suis nul(le) »","La honte nourrit le cycle. Parle-toi comme à un ami : « ça arrive, je reprends »."],["« C'est une information »","Exactement. Note ce qui l'a déclenché et ajuste ton plan."],["« Autant tout lâcher »","C'est l'effet « tant pis », le vrai piège. Reprends au prochain repas, pas à la prochaine semaine."],["« Je préviens quelqu'un »","Excellent réflexe : ça casse l'isolement et la honte."]]},["Un faux pas, pas une chute","Un dérapage ne défait pas les circuits déjà en place. Ce qui compte, c'est de reprendre vite.","Écris ta phrase de reprise."]],["Ton plan en cas de rechute","Prévoir le plan B enlève la peur. Qu'est-ce qui m'a fait craquer ? Qu'est-ce que je change ? Qui je préviens ?","Rédige un plan en 3 points : ce que je fais dans l'heure, ce que j'analyse, ce que j'ajuste. Note le 0 800 23 13 13.","relapse",{},{"q":"En cas de rechute, ce qui t'aiderait le plus ?","o":[["Un message tout prêt","Écris-le maintenant, il sera là quand tu en auras besoin. Tu n'auras plus qu'à l'envoyer."],["Quelqu'un à appeler","Choisis la personne et enregistre son numéro en favori."],["Une règle simple","Par exemple : « je m'arrête là, je bois de l'eau, je reprends demain »."],["Je préfère ne pas y penser","C'est compréhensible, mais prévoir réduit la peur. Ça prend 2 minutes et tu seras plus serein(e)."]]},["Anticiper apaise","Prévoir ce qu'on fera en cas de craquage réduit la panique et l'effet « tant pis ».","Relis ton plan B ce soir."]],["Ce que ton corps récupère","Au fil des semaines, beaucoup de personnes retrouvent des nuits plus profondes, de l'énergie, de la concentration et de la motivation. Chaque personne a son rythme.","Note 3 changements que tu constates depuis le début, même petits.","timeline",{},{"q":"Dans 6 mois, tu aimerais être quelqu'un qui…","o":[["Dort bien","Un objectif concret : les nuits s'améliorent souvent dès les premières semaines."],["Tient ses engagements","Chaque petit engagement tenu renforce la confiance en toi."],["A de l'énergie","L'énergie revient avec le sommeil, le mouvement et moins d'à-coups."],["Se sent libre","La liberté, c'est choisir. Chaque envie traversée est un choix de plus."]]},["Le corps récupère","Les bronches, souvent irritées par la fumée, s'améliorent en quelques semaines : moins de toux et plus de souffle.","Respire profondément 3 fois et note ton souffle."]],["Les moments à risque à venir","Vacances, concerts, soirées, périodes de stress : certains moments vont remettre l'envie en jeu. Les prévoir, c'est déjà y être préparé.","Liste les 3 prochains moments à risque et ce que tu feras à chaque fois.",null,{},{"q":"Ton prochain moment à risque, c'est…","o":[["Un week-end","Prévois deux activités par jour et une heure de coucher."],["Une fête ou un événement","Décide à l'avance ce que tu fais et à quelle heure tu pars."],["Une période de stress","Planifie des pauses et du mouvement. Le stress est un déclencheur majeur."],["Je ne sais pas","Regarde ton agenda des 2 semaines à venir : tu en verras un ou deux."]]},["Le contexte déclenche","Concerts, soirées, périodes de stress : certains moments ravivent l'envie. Les repérer permet de s'y préparer.","Note les 3 prochains moments à risque."]],["Mieux dormir","Le sommeil est souvent perturbé les premières semaines, puis s'améliore. Une routine du soir régulière aide beaucoup.","Fixe une heure de coucher. Téléphone hors du lit. Prévois une activité calme avant de dormir.","evening",{},{"q":"Tes nuits en ce moment ?","o":[["Courtes","Une nuit courte renforce l'envie et réduit le contrôle. Couche-toi 30 minutes plus tôt ce soir."],["Agitées","Écrans coupés 30 minutes avant, chambre fraîche (18-19 °C) et dîner léger aident."],["Correctes","Bien. Garde un horaire régulier : c'est ça qui consolide."],["Très bonnes","Parfait. Protège-les : c'est un de tes meilleurs alliés."]]},["Mieux dormir","Chambre fraîche, écrans coupés, horaires réguliers : c'est le trio qui consolide les nuits.","Chambre à 18-19 °C ce soir."]],["L'argent économisé","Cet argent est ton vrai gain. Le chiffrer le rend concret et motive.","Reprends ton chiffre du jour 2. Écris ce que tu veux faire avec cet argent.",null,{},{"q":"Le temps ou l'argent récupéré, tu en feras…","o":[["Du repos","Le repos compte aussi. Planifie-le au lieu de le subir."],["Un projet","Choisis un petit projet de 30 minutes par jour : c'est ce qui remplit le vide."],["Du temps avec des proches","Les liens sont l'un des meilleurs soutiens pour tenir."],["Un plaisir ou de l'épargne","Mets une somme de côté chaque semaine : la voir grossir motive."]]},["L'argent économisé","L'argent non dépensé s'accumule vite : quelques dizaines d'euros par semaine font plusieurs centaines sur l'année.","Calcule ta somme annuelle et choisis ce que tu en fais."]],["Ton réseau d'aide","Si tu as du mal à tenir, ou si tu consommais beaucoup depuis longtemps, un professionnel peut t'aider gratuitement : consultation jeunes consommateurs, ton médecin, Drogues info service.","Note le 0 800 23 13 13 et le nom de ton médecin. Si tu vas mal, le 3114 répond 24h/24.",null,{},{"q":"Qui est ton premier appel en cas de coup dur ?","o":[["Un(e) ami(e)","Garde son numéro en favori. Dis-lui d'avance qu'il peut t'aider."],["Un proche de la famille","Préviens-le à l'avance : il saura quoi répondre quand ça arrivera."],["Un professionnel","Drogues info service (0 800 23 13 13) est joignable. Note le numéro dans ton téléphone."],["Je n'ai pas de nom","Alors Drogues info service (0 800 23 13 13) peut être ce nom. C'est gratuit, tu n'as pas à te justifier."]]},["L'aide existe","Les consultations jeunes consommateurs et Drogues info service sont gratuites, confidentielles et sans jugement.","Note le 0 800 23 13 13."]],["Lettre à toi-même","Ce que tu as fait pendant 30 jours mérite d'être écrit. Cette lettre te servira les jours où tu auras oublié pourquoi c'était important.","Écris-toi une lettre pour dans 3 mois : ce que tu as appris, ce que tu veux avoir gardé, ce que tu te souhaites.","letter",{},{"q":"Pour toi dans 3 mois, le plus important à te rappeler ?","o":[["Ce que j'ai tenu","Écris-le : les chiffres sont des preuves quand le doute revient."],["Pourquoi j'ai commencé","Relis ton pourquoi du premier jour. Il est dans ton espace."],["Que ça passe","Oui : une envie passe toujours. C'est ta meilleure information."],["Que je mérite d'aller bien","C'est vrai. Écris-le comme si tu parlais à un ami."]]},["Écrire aide","Écrire ce qu'on ressent aide à réguler les émotions, c'est ce qu'on appelle l'écriture expressive.","Écris 5 minutes, sans te relire."]],["Et maintenant ?","30 jours, c'est un début, pas une fin. Garde les règles qui ont marché, et refais le point une fois par mois.","Choisis les 3 règles à garder. Plante un rappel mensuel dans ton agenda.","final",{},{"q":"Pour la suite, tu comptes…","o":[["Continuer chaque jour","Excellent. La régularité fait plus que l'intensité."],["Faire un point par semaine","Très bien : un point de 10 minutes le dimanche suffit."],["Appeler en cas de doute","Drogues info service (0 800 23 13 13) est là. Un coup de fil évite souvent une rechute."],["Je ne sais pas encore","Pas de pression. Garde juste la règle : au moindre doute, 10 minutes d'attente et un souffle lent."]]},["Garder le cap","Les rechutes sont fréquentes dans tout changement ; ce qui compte, c'est de reprendre vite, sans te punir.","Fixe un rappel mensuel pour faire le point."]]]},"drogues-de-soiree":{"kit":{"raisons":["Ma santé","Mon argent","Mon sommeil","Mes relations","Mon humeur","Mon énergie","Mes projets","Ma confiance en moi","Ma liberté","Moins de descentes"],"pros":["L'énergie","La confiance en moi","Appartenir au groupe","Faire la fête plus longtemps","Oublier mes soucis","Me désinhiber"],"cons":["Je dépense beaucoup","La descente","Je dors mal","Mon humeur baisse après","Mon cœur s'emballe","Je m'éloigne de mes proches","Je perds le contrôle","J'ai peur de ce que je fais"],"calc":{"q":"Combien dépenses-tu par mois ?","unit":"€ par mois","min":0,"max":1000,"step":10,"def":150,"mult":12,"out":"€ par an","div":0,"divLabel":"","eq":[500,"week-ends en voyage"],"gain":"économisés chaque année"},"env":["Supprimer les contacts et conversations","Prévoir mes soirées à l'avance","Réduire l'alcool, qui lève les barrières","Laisser l'argent liquide à la maison","Prévenir un ami de ma décision","Éviter les soirées à risque au début"],"triggers":["Les soirées en club","Certains amis","L'alcool","La fin de semaine","Le stress","L'ennui","Quand j'ai de l'argent sur moi","Les festivals","Après une dispute","Quand je me sens seul"],"actions":["Appeler un ami","Sortir marcher","Respirer lentement","Boire de l'eau","Faire du sport","Danser sans produit","Rentrer plus tôt","Écouter de la musique","Changer de pièce","Écrire ce que je ressens"],"distract":["Un ami : « t'as de quoi ? »","Le vendredi soir","L'odeur de la soirée","Un message de ton contact","Pause toilettes","Une chanson qui rappelle des soirées"],"myths":[["On a besoin d'un produit pour s'amuser.",false,"La confiance et l'énergie reviennent peu à peu, avec le sommeil et le sport."],["L'alcool n'a pas d'effet sur l'envie.",false,"L'alcool baisse la vigilance et augmente les envies. Réduire l'alcool aide à tenir."],["La descente est normale et ne dure que quelques jours.",true,"Fatigue et humeur basse sont fréquentes. Dormir, manger et parler aident."],["Un dérapage = tout est à refaire.",false,"Un dérapage est une information. On reprend le fil."],["Planifier sa soirée aide à ne pas craquer.",true,"Heure de départ, boisson, personne de confiance : ça réduit les décisions sous pression."],["Il vaut mieux consommer seul pour ne pas se faire repérer.",false,"Consommer seul est plus risqué. En cas de rechute, ne reste pas seul et appelle le 15 en cas de malaise."]],"pairs":[["Soirée en club","Partir à une heure fixée"],["Un ami propose","« Non merci, j'arrête »"],["L'alcool","Boisson sans alcool"],["La descente","Dormir et manger"],["Le vendredi soir","Un plan prévu à l'avance"]],"pieges":[["Juste ce soir.",true,"« Juste ce soir » est la phrase qui relance le cycle."],["Tout le monde le fait.",true,"Beaucoup de gens ne le font pas, et passent de bonnes soirées."],["Je peux partir plus tôt si ça devient dur.",false,"Oui. Un plan de sortie est un super outil."],["Je contrôle, une fois ne compte pas.",true,"Le contrôle se perd souvent d'un coup. Mieux vaut ne pas tester."],["Je peux appeler Drogues info service.",false,"Oui : 0 800 23 13 13, gratuit et anonyme."],["J'ai besoin de ça pour être drôle.",true,"Ta personnalité est toujours là. La confiance revient avec le temps."],["Un dérapage n'est pas un échec.",false,"Exact. Reprends le fil sans te punir."],["C'est le seul moyen de décompresser.",true,"Le sport, la musique, le sommeil et les amis marchent aussi."]],"scenarios":[{"q":"Vendredi soir, en club. Un ami te propose de partager quelque chose.","c":[["Je dis « non merci, j'arrête » et je prends de l'eau",2,"Simple et sans justification. Tu protèges ta décision."],["J'accepte juste pour cette fois",0,"« Juste cette fois » est le piège classique."],["Je pars aux toilettes et je réfléchis",1,"Pause utile, mais prépare ta réponse à l'avance."]]},{"q":"Dimanche, descente : tu es fatigué, triste, et tu penses à reprendre pour te sentir mieux.","c":[["Je dors, je mange et j'appelle un ami",2,"Tu laisses la descente passer et tu t'appuies sur quelqu'un."],["Je reprends un peu pour remonter",0,"Ça repousse la descente et relance le cycle."],["Je me dis que je suis nul",1,"Ce jugement fatigue. Parle-toi comme à un ami."]]},{"q":"Tu as craqué ce week-end. Tu te sens mal.","c":[["Je me dis que c'est foutu",0,"Un dérapage n'est pas une rechute. Ne te punis pas."],["Je note ce qui m'a déclenché et je reprends dès aujourd'hui",2,"C'est exactement ça. Et si malaise, appelle le 15."],["Je ne dis rien à personne",1,"Parler à quelqu'un de confiance aide énormément."]]}],"relapse":{"heure":["Je ne reste pas seul et je bois de l'eau","En cas de malaise, j'appelle le 15 ou le 112","Je note ce qui s'est passé"],"ajuster":["Je réduis l'alcool en soirée","Je change de lieux ou d'amis","Je consulte une CJC ou mon médecin"],"prevenir":["Un ami proche","Mon frère ou ma sœur","Mon conjoint ou ma conjointe","Un professionnel","Personne, je gère seul"]},"events":["Soirée en club","Festival","Anniversaire","Nouvel an","Dimanche de descente","Période de stress"],"messages":["J'arrête les produits en soirée. Peux-tu me garder à l'œil ce week-end ?","Je sors ce soir sans rien prendre. Peux-tu me soutenir ?"],"rules":["Garder mes barrières en place","Utiliser le bouton SOS à chaque envie","Prévoir mes moments à risque","Parler à quelqu'un quand c'est dur","Bouger régulièrement","Bien dormir","Me récompenser autrement","Faire un point chaque mois","Ne jamais consommer seul","Partir à l'heure prévue"],"identite":["qui décide de son temps","qui tient ses engagements","qui prend soin de lui","qui sait demander de l'aide","qui ose dire non","qui se réveille avec de l'énergie","qui choisit ses soirées","qui protège son argent","qui est présent avec ses proches","qui avance sur ses projets","qui se respecte","qui ne se juge plus durement"],"rewards":["Un bon repas au restaurant","Une sortie au cinéma","Un week-end dans la nature","Un vêtement qui me plaît","Un moment avec un ami","Une journée sans rien faire","Un livre ou un jeu","Un hammam ou un massage","Un petit voyage","Un cadeau pour quelqu'un"],"evening":["Fixer l'heure du coucher","Téléphone hors du lit","Écrans éteints 30 minutes avant","Douche ou tisane","Préparer la journée de demain","Respirer 2 minutes"],"people":["Un ami proche","Mon frère ou ma sœur","Mon conjoint ou ma conjointe","Un parent","Un collègue de confiance","Mon médecin"],"pause":["Lève-toi et étire-toi","Bois un verre d'eau, lentement","Regarde loin, par la fenêtre","Respire lentement 5 fois","Note ce que tu ressens, en une phrase"]},"days":[["Ton pourquoi","Avant de changer quoi que ce soit, il faut savoir pour quoi tu le fais : ta santé, ton argent, ton sommeil, tes relations, ta liberté. Ce pourquoi sera ta réserve les jours difficiles : il doit venir de toi.","Écris 3 raisons personnelles de réduire ou d'arrêter. Garde-les en note sur ton écran de verrouillage.","choose",{},{"q":"Qu'est-ce qui te pousse à changer aujourd'hui ?","o":[["Ma santé","Excellent moteur. Le corps commence à récupérer très tôt : chaque jour compte déjà, même si tu ne le sens pas encore."],["Mon argent","Chiffrer l'argent regagné est l'un des meilleurs rappels les jours difficiles. On le fera dans quelques jours."],["Mes proches","Faire ça pour les autres aide, mais garde aussi une raison rien que pour toi : c'est elle qui tient quand personne ne regarde."],["Je me sens dépassé(e)","C'est une raison valable. Tu n'as pas à tout régler aujourd'hui : un seul petit pas suffit pour commencer."]]},["Dopamine et sérotonine","Les stimulants de soirée provoquent une forte libération de dopamine et de sérotonine. Les réserves se vident ensuite, d'où la baisse d'humeur du lendemain.","Note comment tu te sens le lendemain d'une soirée."]],["Ton usage réel","On sous-estime presque toujours ce qu'on consomme et ce que ça coûte, surtout sur plusieurs soirées. Regarder le chiffre sans te juger, c'est le vrai premier pas.","Fais le total de tes 3 derniers mois : combien de soirées, combien dépensé. Note le chiffre sans le commenter.","calc",{},{"q":"Ton estimation de ta semaine dernière, elle est…","o":[["Plutôt juste","C'est rare : la plupart des gens sous-estiment. Vérifie quand même avec les vrais chiffres ce soir."],["Sûrement en dessous de la réalité","C'est le cas de presque tout le monde : le cerveau oublie les automatismes. Mesurer sans te juger, c'est tout ce qu'on te demande."],["Je n'ose pas regarder","Normal : voir le chiffre pique un peu. C'est pourtant ce qui permet de reprendre la main. Regarde-le comme un simple relevé."],["Je n'en ai aucune idée","Alors note pendant 3 jours, une ligne à chaque fois. Les automatismes se voient dès qu'on les écrit."]]},["La descente","Fatigue, humeur basse, anxiété : la descente dure souvent un à trois jours. Elle vient de ce déséquilibre, pas d'un manque de caractère.","Prévois tes lendemains de soirée à l'avance."]],["Ce que ça t'apporte, ce que ça te coûte","Le produit te rend service : énergie, confiance, appartenance au groupe. Le reconnaître permet de trouver d'autres façons d'obtenir la même chose. Ça coûte aussi de la santé, du sommeil, de l'argent.","Fais deux colonnes sur papier : ce que ça t'apporte / ce que ça te coûte. Entoure ce que tu pourrais obtenir autrement.",null,{},{"q":"Qu'est-ce que ça t'apporte de consommer ?","o":[["Me détendre","La détente est réelle mais courte : elle soulage surtout le manque que l'habitude crée. Respiration lente, marche ou douche chaude donnent un calme plus durable."],["Ne plus penser à rien","C'est un vrai besoin : ton cerveau veut une pause. Une vraie pause (marche, étirements) repose mieux et ne laisse pas de culpabilité."],["Me sentir moins seul(e)","Besoin légitime. Un message ou un appel, même court, y répond mieux et plus longtemps."],["Du plaisir, tout simplement","Le plaisir compte. L'idée n'est pas de t'en priver mais de le retrouver ailleurs : dans quelques jours tu choisiras tes remplaçants."]]},["L'énergie empruntée","L'énergie d'un produit est empruntée à ton corps, à rembourser avec des intérêts : fatigue, sommeil, humeur.","Note ce que la soirée t'a coûté en énergie."]],["Tes déclencheurs","Certains lieux, certains amis, l'alcool, le vendredi soir, la fatigue : ce sont des déclencheurs. Quand tu les repères, tu les vois venir.","Pense à tes 3 dernières soirées. À chaque fois, note ce qui t'a donné envie et à quel moment.","heat",{},{"q":"Quand l'envie est-elle la plus forte ?","o":[["Le soir, seul(e)","Fatigue et solitude : le soir, le cerveau freine moins bien. Prévois quelque chose de précis pour ces heures-là."],["Quand je m'ennuie","L'ennui est un déclencheur très fréquent. Il retombe en quelques minutes si on ne le fuit pas : prépare une action de 5 minutes."],["Quand je suis stressé(e)","Le stress donne envie d'un soulagement rapide. Un souffle plus long à l'expiration (4 s / 6 s) calme le corps en 2 minutes."],["Avec d'autres personnes","Le contexte social pèse beaucoup. Dire à une personne que tu changes suffit souvent à désamorcer."]]},["Le cerveau associe","Musique, lieux, amis : le cerveau associe le contexte au produit. L'envie peut revenir en retrouvant le lieu.","Repère les lieux et sons qui déclenchent l'envie."]],["Verrouiller l'accès","Moins c'est facile d'en avoir, moins tu peux craquer sur un coup de tête. Ton contact, ton argent liquide, tes messages : tout ça peut se couper à l'avance.","Supprime les contacts et les conversations. Décide combien d'argent liquide tu emportes en soirée : le minimum.",null,{},{"q":"Quelle barrière poses-tu en premier ?","o":[["Supprimer l'accès","Chaque étape en plus fait baisser le passage à l'acte : un obstacle de 20 secondes laisse souvent l'envie retomber."],["Changer de lieu ou d'horaire","Les habitudes sont liées à des lieux et des heures. Change l'un des deux et l'automatisme perd son déclencheur."],["Prévenir quelqu'un","Dire ton objectif à voix haute le rend plus réel et te donne un témoin bienveillant."],["Aucune, c'est trop dur","Prends la plus petite, une seule. Une barrière imparfaite vaut mieux qu'un plan parfait jamais appliqué."]]},["Retirer la décision","À 3 h du matin, la volonté est faible. Supprimer le contact et limiter l'argent liquide retire la décision impulsive.","Supprime les contacts et ne prends que le minimum en espèces."]],["Le plan « si… alors… »","Un plan précis marche mieux qu'une bonne intention. Tu décides à l'avance quoi faire quand le moment arrive, pour ne pas avoir à choisir sous l'impulsion, avec du bruit, de la fatigue et de l'alcool.","Écris 3 phrases : « Si on me propose, alors je dis… / si la fatigue arrive, alors je… / si je suis seul, alors je… »","pairs",{},{"q":"Quel plan « si… alors… » te ressemble ?","o":[["Si l'envie vient, je bois de l'eau et j'attends 10 minutes","Un délai court plus un geste simple : c'est très efficace. Les plans précis marchent bien mieux que les bonnes intentions."],["Si je m'ennuie, je sors 5 minutes","Bouger change l'état du corps et coupe l'automatisme. Même monter un escalier compte."],["Si je suis stressé(e), je respire 1 minute","Inspire 4 secondes, souffle 6 : l'expiration longue ralentit le cœur et calme le système nerveux."],["Si je craque, j'appelle quelqu'un","Parler casse l'isolement et la honte, qui poussent à recommencer."]]},["L'expiration longue","Souffler plus longtemps qu'on inspire active le frein du système nerveux et fait baisser l'excitation.","Inspire 4 s, souffle 6 s, cinq fois."]],["Bilan de la semaine 1","Une semaine pour comprendre. Tu sais maintenant ce que tu consommes, ce que ça t'apporte et ce qui se déclenche. C'est suffisant pour attaquer la suite.","Relis tes notes. Complète : « Ce que j'ai appris sur moi cette semaine, c'est… ». Choisis une soirée à préparer cette semaine.",null,{},{"q":"Cette semaine, qu'est-ce qui t'a le plus surpris(e) ?","o":[["À quel point c'est automatique","Voir l'automatisme, c'est déjà la moitié du chemin : on ne peut changer que ce qu'on remarque."],["Les moments où l'envie arrive","Tu connais maintenant tes heures et tes lieux : tu peux les anticiper au lieu de les subir."],["Que ça passe quand j'attends","C'est l'info la plus utile : une envie qui passe n'est pas un ordre."],["Rien de spécial","Pas grave, c'est une semaine d'observation. Continue : les effets arrivent avec la pratique."]]},["La nuit blanche coûte","Veiller toute la nuit perturbe l'horloge biologique et l'humeur pendant plusieurs jours.","Rentre à l'heure que tu t'es fixée."]],["Comprendre l'envie","L'envie monte, atteint un pic, puis retombe, même si tu ne fais rien. Savoir que ça passe change tout : une envie n'est pas un ordre.","Quand l'envie arrive, attends 10 minutes avant d'agir. Observe où tu la sens dans le corps, et ce qu'elle devient.","wave",{},{"q":"Quand l'envie arrive, que fais-tu d'habitude ?","o":[["Je cède tout de suite","Normal : céder soulage vite, et c'est ce qui apprend au cerveau à recommencer. Aujourd'hui, repousse seulement de 10 minutes."],["Je lutte de toutes mes forces","Lutter épuise. Observe l'envie comme une vague : elle monte, plafonne, redescend. Laisse-la passer sans la combattre."],["Je me distrais","Très bien : 10 minutes de distraction suffisent souvent. Prépare-en deux à l'avance, à portée de main."],["Je ne sais pas","Aujourd'hui, note l'heure et ce que tu ressens quand elle vient. Un schéma va apparaître."]]},["Une vague","Une envie monte, plafonne et retombe en quelques minutes, même si on ne fait rien.","Chronomètre ta prochaine envie."]],["Tenir 10 minutes","Quand une envie arrive, ne te dis pas « jamais », dis-toi « dans 10 minutes ». Souvent, elle est partie avant. Si elle est encore là, tu décides en conscience.","Utilise le bouton SOS à chaque envie aujourd'hui. Compte combien sont passées.","hold",{},{"q":"Peux-tu tenir 10 minutes avant de passer à l'acte ?","o":[["Oui, facilement","Alors fais-en une règle : la plupart des envies retombent avant 10 minutes."],["Oui, avec une distraction","Parfait. Prépare deux distractions : musique, verre d'eau, marche. Elles font la moitié du travail."],["Difficile","Commence par 2 minutes. Chaque envie traversée entraîne ton cerveau à tolérer l'inconfort."],["Impossible","Pas de souci : 1 minute compte déjà. Le bouton SOS te guide pendant 10 minutes, un souffle après l'autre."]]},["Le délai","Attendre 10 minutes laisse redescendre l'excitation et redonne la main à la partie réfléchie du cerveau.","Lance un minuteur de 10 minutes."]],["Respirer pour retomber","Une respiration lente, avec un souffle plus long que l'inspiration, aide à calmer le corps en quelques minutes. C'est un outil que tu emportes partout, y compris en soirée.","Fais 2 minutes de respiration (inspire 4 secondes, souffle 6), deux fois dans la journée, dont une avant de sortir.","breathe",{},{"q":"Quand tu es tendu(e), ton souffle est plutôt…","o":[["Court et haut","Respirer haut met le corps en alerte. Allonge l'expiration : c'est le levier le plus rapide pour te calmer."],["Je le retiens parfois","Retenir son souffle augmente la tension. Souffle doucement par la bouche, comme dans une paille."],["Je n'y ai jamais fait attention","Pose une main sur le ventre : si elle ne bouge pas, ta respiration est haute. Essaie de la faire gonfler."],["Plutôt calme","Bien. Garde ce réflexe pour les moments d'envie, c'est là qu'il compte le plus."]]},["Le nerf vague","Respirer lentement stimule le nerf vague, qui ralentit le cœur et apaise.","Deux minutes de respiration avant de sortir."]],["Gérer la descente","Fatigue, humeur basse, anxiété : la descente donne envie de reprendre « pour remonter ». Elle passe avec le sommeil, la nourriture et un peu de patience.","Prépare ta prochaine descente : un repas, de l'eau, un film, un ami joignable, un lit propre. Tu n'as pas à la traverser seul.","slot",{},{"q":"Pour t'occuper 10 minutes, tu préfères…","o":[["Bouger","Le mouvement réduit les envies et améliore l'humeur en quelques minutes."],["Parler à quelqu'un","Une voix humaine apaise plus vite qu'un écran ou un produit."],["Faire quelque chose de mes mains","Cuisine, dessin, rangement : occuper les mains occupe aussi l'attention, l'envie perd de la place."],["Rien ne me tente","Normal au début : l'envie rend tout fade. Essaie quand même 3 minutes, l'envie baisse avant que l'activité ne devienne agréable."]]},["Traverser la descente","Pendant la descente : manger, boire de l'eau, dormir, marcher et se faire accompagner aident le cerveau à retrouver son équilibre.","Prévois repas, eau et un ami joignable pour dimanche."]],["Stress, fatigue et humeur","On consomme davantage quand on est stressé ou fatigué. Si tu t'accordes de vraies pauses à ces moments, le produit devient moins nécessaire. Si l'humeur reste très basse, parles-en à un professionnel.","Prévois 3 pauses de 5 minutes aujourd'hui : étirements, fenêtre ouverte, verre d'eau, marche. Note comment tu te sens après.",null,{},{"q":"Quand tu es stressé(e), ton corps réagit surtout par…","o":[["De la tension (épaules, mâchoire)","Relâche : épaules vers le bas, mâchoire détendue, trois souffles lents."],["De la fatigue","La fatigue baisse le frein de la volonté. Une sieste de 15 à 20 minutes aide, sinon couche-toi plus tôt ce soir."],["De l'agitation","Marche rapide 5 minutes : elle dépense l'adrénaline en trop."],["Je ne sais pas","Scanne : tête, épaules, ventre, jambes. Où ça serre ? C'est là qu'il faut respirer."]]},["Stress et cortisol","Le stress élève le cortisol et pousse vers le soulagement rapide. Marcher 10 minutes le fait redescendre.","Marche 10 minutes dehors."]],["Idées reçues sur les produits de soirée","« Tout le monde en prend », « j'ai besoin de ça pour m'amuser », « je contrôle ». Certaines idées reçues retiennent au même endroit. Les regarder d'un œil honnête enlève du pouvoir à la routine.","Écris l'idée reçue qui te parle le plus et ce que tu en penses maintenant.","myths",{},{"q":"Quelle idée te retient le plus ?","o":[["J'en ai besoin pour me détendre ou dormir","Ça détend sur l'instant mais entretient le manque ensuite. À terme, la détente et le sommeil naturels reviennent."],["Je gère, ce n'est pas un problème","Si tu es ici, c'est que tu veux plus de contrôle. Fais confiance à ça."],["Tout le monde le fait","Beaucoup le font, et beaucoup changent aussi. Tu n'es pas seul(e) dans les deux cas."],["Juste une fois ne compte pas","Chaque fois renforce le circuit de l'habitude. L'exception est souvent la porte d'entrée."]]},["L'alcool amplifie","L'alcool baisse l'inhibition et la vigilance, et augmente nettement l'envie comme les risques en soirée.","Alterne avec de l'eau ou une boisson sans alcool."]],["Bilan de la semaine 2","Tu as appris à voir l'envie venir, à l'attendre et à préparer la descente. Chaque jour compte, même imparfait.","Regarde ton compteur de jours sans et d'envies surmontées. Note le moment le plus dur et ce qui t'a aidé.",null,{},{"q":"Ce qui t'a le plus aidé(e) cette semaine ?","o":[["Attendre 10 minutes","Garde-le : c'est ton outil principal. Il marche d'autant mieux qu'il est automatique."],["Respirer","La respiration est toujours avec toi. Utilise-la avant que l'envie ne soit à son maximum."],["Éloigner ce qui donne accès","Bien joué : réduire l'accès est l'une des méthodes les plus solides."],["Rien de précis","Pas grave. Regarde le bilan : tu as peut-être tenu plus que tu ne le penses."]]},["Le cœur sous pression","Les stimulants accélèrent le cœur et montent la tension. En cas de douleur à la poitrine, malaise ou confusion : appelle le 15 ou le 112.","Enregistre le 15 et le 112 en favoris."]],["Faire la fête autrement","Danser, rire, rencontrer des gens : tout ça n'a pas besoin d'un produit. Construis ta boîte à outils pour sortir sans : une boisson sans alcool en main, un point de départ, un ami de confiance.","Choisis 3 actions pour ta prochaine soirée et garde-les dans une note.",null,{},{"q":"Quel remplaçant te semble le plus réaliste ?","o":[["Un geste (eau, étirements)","Les petits gestes sont faciles à répéter. Garde-les à portée de main."],["Une activité courte (marche, jeu)","Dix minutes suffisent souvent. Choisis-en une que tu peux faire n'importe où."],["Une personne (appel, message)","Un lien humain est l'un des meilleurs remplaçants. Mets 2 prénoms dans tes favoris."],["Je n'en ai pas encore","Essaie les trois cette semaine. Tu verras vite lequel marche pour toi."]]},["Danser libère","Danser libère des endorphines, et la musique active le circuit de la récompense, sans produit.","Mets de la musique et danse 5 minutes."]],["Bouger","Le sport aide au sommeil, à l'humeur et à la confiance. Pas besoin de sport intense : danse, marche, vélo comptent.","Fais 20 minutes d'activité physique aujourd'hui, de préférence à l'heure où tu aurais préparé ta soirée.","move",{},{"q":"Ton niveau de mouvement dans une journée ?","o":[["Presque aucun","Commence par 5 minutes de marche : c'est déjà un effet mesurable sur l'humeur."],["Un peu","Ajoute 10 minutes à l'heure où l'envie est la plus forte."],["Régulier","Excellent. Place-le aux heures à risque : c'est là qu'il protège le plus."],["Beaucoup","Parfait. N'oublie pas le repos : il fait partie de la récupération."]]},["Le mouvement répare","L'exercice améliore le sommeil, l'humeur et la confiance, trois choses que la descente abîme.","20 minutes de marche rapide."]],["Soirées et week-ends","Les soirées, les festivals, les anniversaires sont des moments à risque. Un plan évite de se retrouver coincé : qui, où, jusqu'à quand, avec quel budget.","Regarde les 2 prochains événements. Décide à l'avance ce que tu feras, avec qui, à quelle heure tu pars.",null,{},{"q":"Le plus dur dans tes week-ends, c'est…","o":[["Le temps libre","Prévois deux activités par jour : le vide appelle l'habitude."],["Les amis","Propose un lieu ou une activité sans l'habitude, ou dis-le d'avance. Les vrais amis comprennent."],["Le soir tard","Fixe une heure limite de coucher : la fatigue baisse les défenses."],["Rien de particulier","Prévois quand même un plan B, au cas où."]]},["Chaleur et eau","Danser longtemps fait monter la température et la transpiration. Boire de l'eau par petites gorgées et faire des pauses au frais.","Prévois une pause au frais toutes les heures."]],["En parler à quelqu'un","Garder ça pour soi entretient la honte. Parler à un ami de confiance, ou à Drogues info service (0 800 23 13 13, gratuit et anonyme), allège.","Choisis une personne de confiance et dis-lui que tu veux réduire ou arrêter. Dis-lui ce dont tu as besoin.",null,{},{"q":"À qui pourrais-tu en parler ?","o":[["Un(e) ami(e)","Un ami de confiance suffit. Dis simplement : « j'essaie de changer, peux-tu me demander demain comment ça va ? »"],["Un proche de la famille","Choisis la personne la plus calme et la moins critique. Un message écrit peut être plus facile."],["Un professionnel ou une ligne d'aide","Excellente idée : Drogues info service (0 800 23 13 13) est là pour ça, gratuitement et sans jugement."],["Personne pour l'instant","C'est possible, et ce n'est pas grave. Une ligne d'aide (Drogues info service (0 800 23 13 13)) peut être ton premier interlocuteur."]]},["Parler allège","Parler à un ami de confiance réduit la honte et le stress, deux moteurs de l'envie.","Parle à une personne de confiance."]],["Les pensées-pièges","« Juste ce soir », « tout le monde le fait », « je contrôle ». Ces phrases sont normales. Les repérer leur enlève du pouvoir.","Écris 3 phrases que tu te dis avant de consommer. À côté de chacune, une réponse honnête et courte.","pieges",{},{"q":"Quelle pensée te fait le plus craquer ?","o":[["« Juste une fois »","C'est le piège le plus courant. Réponse : « si c'est juste une fois, je peux attendre demain »."],["« Je l'ai bien mérité »","Oui, et tu peux te récompenser autrement : repas, film, sortie. Sans la facture."],["« Je m'y mets demain »","Demain sera pareil. Réponse : « je commence par les 10 prochaines minutes »."],["« J'ai déjà craqué, tant pis »","Un faux pas n'efface pas les jours passés. Reprends dès la prochaine heure."]]},["Le cerveau négocie","Pour obtenir un plaisir rapide, le cerveau fabrique des excuses (« juste ce soir »). Les repérer leur enlève du pouvoir.","Note ta pensée-piège préférée."]],["Te récompenser autrement","Ton cerveau aime les petites récompenses. Tu peux en garder sans consommer : un bon repas, une sortie, un week-end avec l'argent économisé.","Choisis une récompense pour chaque semaine tenue. Calcule ce que ça coûte et compare avec ce que tu aurais dépensé.",null,{},{"q":"Quelle récompense te ferait vraiment plaisir ?","o":[["Un bon repas","Parfait : choisis le jour et le lieu à l'avance, une récompense prévue motive mieux qu'une récompense improvisée."],["Une sortie","Planifie-la dans ton agenda dès aujourd'hui : l'avoir devant soi aide à tenir."],["Un achat","Mets de côté la somme économisée dans une enveloppe : la voir grossir motive."],["Du repos","Le repos est une vraie récompense. Offre-toi une soirée sans obligation."]]},["La récompense prévue","Une récompense choisie à l'avance renforce un nouveau comportement mieux qu'une récompense improvisée.","Choisis ta récompense de la semaine."]],["Bilan de la semaine 3","Trois semaines de pratique. Regarde ce qui a changé : sommeil, énergie, humeur, argent, relations.","Écris 3 changements que tu constates, même petits.",null,{},{"q":"Ce qui a changé depuis le début ?","o":[["Mon sommeil","Un meilleur sommeil réduit l'impulsivité : c'est un cercle vertueux qui s'installe."],["Mon humeur","Chaque jour, le cerveau se rééquilibre un peu. L'humeur suit souvent avec un décalage."],["Mon argent","Note la somme : c'est un des gains les plus concrets."],["Pas encore grand-chose","Normal : les changements sont souvent lents au début. Continue, ils arrivent avec la régularité."]]},["La sérotonine remonte","Avec le temps, le sommeil et la régularité, l'humeur remonte : beaucoup de personnes se sentent mieux après quelques semaines.","Note ton humeur de 1 à 10."]],["Un dérapage n'est pas une rechute","Si tu consommes, ce n'est pas la fin. C'est une information : qu'est-ce qui l'a déclenché ? Ne reste pas seul, bois de l'eau, et reprends le fil dès que possible, sans te punir.","Écris ce que tu feras après un dérapage : t'arrêter là, ne pas rester seul, noter le déclencheur, le dire à quelqu'un.","scenario",{},{"q":"Si tu craques ce soir, tu te diras…","o":[["« Je suis nul(le) »","La honte nourrit le cycle. Parle-toi comme à un ami : « ça arrive, je reprends »."],["« C'est une information »","Exactement. Note ce qui l'a déclenché et ajuste ton plan."],["« Autant tout lâcher »","C'est l'effet « tant pis », le vrai piège. Reprends au prochain repas, pas à la prochaine semaine."],["« Je préviens quelqu'un »","Excellent réflexe : ça casse l'isolement et la honte."]]},["Un faux pas, pas une chute","Un dérapage ne défait pas les circuits déjà en place. Ne reste pas seul(e), bois de l'eau, et reprends vite.","Écris ta phrase de reprise."]],["Ton plan en cas de rechute","Prévoir le plan B enlève la peur. Qu'est-ce qui m'a fait craquer ? Qu'est-ce que je change ? Qui je préviens ? En cas de malaise : 15 ou 112.","Rédige un plan en 3 points : ce que je fais dans l'heure, ce que j'analyse, ce que j'ajuste. Note le 0 800 23 13 13 et le 15.","relapse",{},{"q":"En cas de rechute, ce qui t'aiderait le plus ?","o":[["Un message tout prêt","Écris-le maintenant, il sera là quand tu en auras besoin. Tu n'auras plus qu'à l'envoyer."],["Quelqu'un à appeler","Choisis la personne et enregistre son numéro en favori."],["Une règle simple","Par exemple : « je m'arrête là, je bois de l'eau, je reprends demain »."],["Je préfère ne pas y penser","C'est compréhensible, mais prévoir réduit la peur. Ça prend 2 minutes et tu seras plus serein(e)."]]},["Anticiper apaise","Prévoir ce qu'on fera en cas de craquage réduit la panique. En cas de malaise : 15 ou 112.","Relis ton plan B ce soir."]],["Qui tu deviens","Au fil des semaines, tu n'es plus la même personne qu'au jour 1. Nommer qui tu deviens rend le changement concret et te donne une direction.","Écris une phrase : « Je deviens quelqu'un qui… ». Relis-la le matin.",null,{},{"q":"Dans 6 mois, tu aimerais être quelqu'un qui…","o":[["Dort bien","Un objectif concret : les nuits s'améliorent souvent dès les premières semaines."],["Tient ses engagements","Chaque petit engagement tenu renforce la confiance en toi."],["A de l'énergie","L'énergie revient avec le sommeil, le mouvement et moins d'à-coups."],["Se sent libre","La liberté, c'est choisir. Chaque envie traversée est un choix de plus."]]},["Une nouvelle identité","Chaque soirée vécue sans renforce la confiance : tu n'as pas besoin d'un produit pour être drôle ou à l'aise.","Note une chose que tu as aimée en soirée sans."]],["Les moments à risque à venir","Festivals, anniversaires, nouvel an, périodes de stress : certains moments vont remettre l'envie en jeu. Les prévoir, c'est déjà y être préparé.","Liste les 3 prochains moments à risque et ce que tu feras à chaque fois.",null,{},{"q":"Ton prochain moment à risque, c'est…","o":[["Un week-end","Prévois deux activités par jour et une heure de coucher."],["Une fête ou un événement","Décide à l'avance ce que tu fais et à quelle heure tu pars."],["Une période de stress","Planifie des pauses et du mouvement. Le stress est un déclencheur majeur."],["Je ne sais pas","Regarde ton agenda des 2 semaines à venir : tu en verras un ou deux."]]},["Le contexte déclenche","Festivals, anniversaires, nouvel an : certains moments ravivent l'envie. Les repérer permet de s'y préparer.","Note les 3 prochains moments à risque."]],["Mieux dormir","Le sommeil est souvent perturbé les premières semaines, puis s'améliore. Une routine du soir régulière aide beaucoup.","Fixe une heure de coucher. Téléphone hors du lit. Prévois une activité calme avant de dormir.","evening",{},{"q":"Tes nuits en ce moment ?","o":[["Courtes","Une nuit courte renforce l'envie et réduit le contrôle. Couche-toi 30 minutes plus tôt ce soir."],["Agitées","Écrans coupés 30 minutes avant, chambre fraîche (18-19 °C) et dîner léger aident."],["Correctes","Bien. Garde un horaire régulier : c'est ça qui consolide."],["Très bonnes","Parfait. Protège-les : c'est un de tes meilleurs alliés."]]},["Dormir 7 à 9 heures","Un sommeil régulier rééquilibre humeur et énergie, et réduit les envies.","Fixe une heure de coucher, même le week-end."]],["L'argent que tu récupères","Cet argent est ton vrai gain. Le chiffrer le rend concret et motive.","Reprends ton chiffre du jour 2. Écris ce que tu veux faire avec cet argent.",null,{},{"q":"Le temps ou l'argent récupéré, tu en feras…","o":[["Du repos","Le repos compte aussi. Planifie-le au lieu de le subir."],["Un projet","Choisis un petit projet de 30 minutes par jour : c'est ce qui remplit le vide."],["Du temps avec des proches","Les liens sont l'un des meilleurs soutiens pour tenir."],["Un plaisir ou de l'épargne","Mets une somme de côté chaque semaine : la voir grossir motive."]]},["L'argent regagné","Chaque soirée sans produit, ce sont des dizaines d'euros de moins dépensés. Les voir s'accumuler motive.","Mets la somme de côté dans une enveloppe."]],["Ton réseau d'aide","Si tu as du mal à tenir, un professionnel peut t'aider gratuitement : consultation jeunes consommateurs, CSAPA, ton médecin, Drogues info service. Ce n'est pas un échec.","Note le 0 800 23 13 13 et le nom de ton médecin. Si tu vas mal, le 3114 répond 24h/24.",null,{},{"q":"Qui est ton premier appel en cas de coup dur ?","o":[["Un(e) ami(e)","Garde son numéro en favori. Dis-lui d'avance qu'il peut t'aider."],["Un proche de la famille","Préviens-le à l'avance : il saura quoi répondre quand ça arrivera."],["Un professionnel","Drogues info service (0 800 23 13 13) est joignable. Note le numéro dans ton téléphone."],["Je n'ai pas de nom","Alors Drogues info service (0 800 23 13 13) peut être ce nom. C'est gratuit, tu n'as pas à te justifier."]]},["L'aide existe","Drogues info service, les CSAPA et ton médecin sont gratuits, confidentiels et sans jugement.","Note le 0 800 23 13 13."]],["Lettre à toi-même","Ce que tu as fait pendant 30 jours mérite d'être écrit. Cette lettre te servira les jours où tu auras oublié pourquoi c'était important.","Écris-toi une lettre pour dans 3 mois : ce que tu as appris, ce que tu veux avoir gardé, ce que tu te souhaites.","letter",{},{"q":"Pour toi dans 3 mois, le plus important à te rappeler ?","o":[["Ce que j'ai tenu","Écris-le : les chiffres sont des preuves quand le doute revient."],["Pourquoi j'ai commencé","Relis ton pourquoi du premier jour. Il est dans ton espace."],["Que ça passe","Oui : une envie passe toujours. C'est ta meilleure information."],["Que je mérite d'aller bien","C'est vrai. Écris-le comme si tu parlais à un ami."]]},["Écrire aide","Écrire ce qu'on ressent aide à réguler les émotions, c'est ce qu'on appelle l'écriture expressive.","Écris 5 minutes, sans te relire."]],["Et maintenant ?","30 jours, c'est un début, pas une fin. Garde les règles qui ont marché, et refais le point une fois par mois. Ne reste jamais seul en cas de rechute.","Choisis les 3 règles à garder. Plante un rappel mensuel dans ton agenda.","final",{},{"q":"Pour la suite, tu comptes…","o":[["Continuer chaque jour","Excellent. La régularité fait plus que l'intensité."],["Faire un point par semaine","Très bien : un point de 10 minutes le dimanche suffit."],["Appeler en cas de doute","Drogues info service (0 800 23 13 13) est là. Un coup de fil évite souvent une rechute."],["Je ne sais pas encore","Pas de pression. Garde juste la règle : au moindre doute, 10 minutes d'attente et un souffle lent."]]},["Garder le cap","Les rechutes sont fréquentes dans tout changement ; ce qui compte, c'est de reprendre vite. Ne reste jamais seul(e) en cas de rechute.","Fixe un rappel mensuel pour faire le point."]]]}};
const okPaid = (s: any) => s.payment_status === 'paid' || s.payment_status === 'no_payment_required';
const PROGS: Record<string, { cents: number; name: string }> = {
  'ecrans': { cents: 999, name: 'Écrans et réseaux (30 jours)' },
  'pornographie': { cents: 999, name: 'Pornographie (30 jours)' },
  'jeux-d-argent': { cents: 999, name: 'Jeux d\'argent et paris (30 jours)' },
  'vape-tabac': { cents: 999, name: 'Vape et tabac (30 jours)' },
  'cannabis': { cents: 999, name: 'Cannabis (30 jours)' },
  'drogues-de-soiree': { cents: 999, name: 'Cocaïne et drogues de soirée (30 jours)' },
  'pack': { cents: 2499, name: 'Les 6 programmes' },
};

async function stripe(path: string, body?: URLSearchParams) {
  const r = await fetch('https://api.stripe.com/v1/' + path, {
    method: body ? 'POST' : 'GET', body,
    headers: { Authorization: 'Bearer ' + SK, 'Content-Type': 'application/x-www-form-urlencoded' },
  });
  return r.json();
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: CORS });
  if (!SK) return json({ error: 'paiement non configuré' }, 500);
  const body = await req.json().catch(() => ({}));
  const { action, id, cle, sid } = body;

  if (action === 'prog_checkout') {
    const prog = String(body.prog || ''), P = PROGS[prog];
    if (!P) return json({ error: 'demande invalide' }, 400);
    const p = new URLSearchParams({
      mode: 'payment', locale: 'fr', allow_promotion_codes: 'true',
      'line_items[0][quantity]': '1',
      'line_items[0][price_data][currency]': 'eur',
      'line_items[0][price_data][unit_amount]': String(P.cents),
      'line_items[0][price_data][product_data][name]': 'Lookmiz · ' + P.name,
      success_url: SITE + 'app/?achat=1&sid={CHECKOUT_SESSION_ID}',
      cancel_url: SITE + (prog === 'pack' ? '#tarifs' : 'programmes/' + prog + '/#achat'),
      'metadata[prog]': prog,
    });
    const s = await stripe('checkout/sessions', p);
    if (!s.url) return json({ error: s.error?.message || 'Stripe a refusé' }, 502);
    return json({ url: s.url });
  }
  if (action === 'prog_verify') {
    if (!/^cs_[A-Za-z0-9_]+$/.test(String(sid || ''))) return json({ paid: false });
    const s = await stripe('checkout/sessions/' + sid), prog = s.metadata?.prog;
    return json(okPaid(s) && prog && PROGS[prog] ? { paid: true, prog } : { paid: false });
  }
  if (action === 'prog_day') {
    const prog = String(body.prog || ''), list = Array.isArray(body.sids) ? body.sids.slice(0, 5) : [];
    if (!DAYS[prog]) return json({ error: 'programme inconnu' }, 400);
    for (const one of list) {
      if (!/^cs_[A-Za-z0-9_]+$/.test(String(one))) continue;
      const s = await stripe('checkout/sessions/' + one), pr = s.metadata?.prog;
      if (okPaid(s) && (pr === prog || pr === 'pack')) return json({ days: DAYS[prog].days, kit: DAYS[prog].kit });
    }
    return json({ error: 'accès refusé' }, 403);
  }

  if (!/^[a-z0-9]{10,20}$/.test(id || '')) return json({ error: 'carte invalide' }, 400);
  const { data: carte } = await admin.from('cartes').select('cle, data, paid').eq('id', id).maybeSingle();
  if (!carte) return json({ error: 'carte introuvable' }, 404);

  if (action === 'checkout') {
    if (carte.cle !== cle) return json({ error: 'refusé' }, 403);
    if (carte.paid) return json({ paid: true });
    const dest = Array.isArray(carte.data?.f?.dest) ? carte.data.f.dest.length : 0;
    const extra = Math.max(0, dest - 1);            // 1,20 € la carte, puis 0,60 € par personne ajoutée
    const p = new URLSearchParams({
      mode: 'payment',
      'line_items[0][quantity]': '1',
      'line_items[0][price_data][currency]': 'eur',
      'line_items[0][price_data][unit_amount]': '120',
      'line_items[0][price_data][product_data][name]': 'Carte Lookmiz animée',
      success_url: SITE + '?paye=' + id + '&sid={CHECKOUT_SESSION_ID}',
      cancel_url: SITE + '#mes-cartes',
      'metadata[carte]': id,
    });
    if (extra) { p.set('line_items[1][quantity]', String(extra)); p.set('line_items[1][price_data][currency]', 'eur'); p.set('line_items[1][price_data][unit_amount]', '60'); p.set('line_items[1][price_data][product_data][name]', 'Personne supplémentaire'); }
    const s = await stripe('checkout/sessions', p);
    if (!s.url) return json({ error: s.error?.message || 'Stripe a refusé' }, 502);
    return json({ url: s.url });
  }

  if (action === 'verify') {
    if (carte.paid) return json({ paid: true });
    if (!/^cs_[A-Za-z0-9_]+$/.test(sid || '')) return json({ paid: false });
    const s = await stripe('checkout/sessions/' + sid);
    const ok = s.payment_status === 'paid' && s.metadata?.carte === id;
    if (ok) await admin.from('cartes').update({ paid: true }).eq('id', id);
    return json({ paid: ok });
  }
  return json({ error: 'demande invalide' }, 400);
});
